import { draftRequest, getAppDraftSession, type AppSnapshot } from "@/lib/app-drafts"
import { getAppStateEditor } from "@/lib/app-state-editor"
import { captureMapSvgOwner, isMapSvgOwnerCurrent, type MapSvgOwner } from "@/lib/map-svg-operations"
import { readPageBinding } from "../../../mapsvg/Map/pageBindings"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

export type RegionSyncOwner = MapSvgOwner & { pageId: string; stateId: string; prefix: string; binding: string }
export type RegionSyncPlan = {
  token: string; revision: number; pageId: string; stateId: string; prefix: string
  collection: { id: number; name: string; title: string }
  matched: number; existing: number; orphaned: number
  additions: Array<{ id: string; title: string }>
}
export type RegionCleanupPlan = {
  token: string; revision: number; collection: RegionSyncPlan["collection"]
  removals: Array<{ id: string; title: string }>; protected: number
}

export function captureRegionSyncOwner(map: MapsvgMapInstance): RegionSyncOwner {
  const editor = getAppStateEditor(map)
  const pageId = editor.activePageId()
  if (!pageId) throw new Error("Select a Page with a Regions Query first.")
  return { ...captureMapSvgOwner(map), pageId, stateId: editor.activeId,
    prefix: String(map.options.regionPrefix ?? ""), binding: JSON.stringify(readPageBinding(map.options, "regions", pageId)) }
}

export function isRegionSyncOwnerCurrent(owner: RegionSyncOwner): boolean {
  if (!isMapSvgOwnerCurrent(owner) || String(owner.map.options.regionPrefix ?? "") !== owner.prefix) return false
  const editor = getAppStateEditor(owner.map)
  return editor.activePageId() === owner.pageId && editor.activeId === owner.stateId
    && JSON.stringify(readPageBinding(owner.map.options, "regions", owner.pageId)) === owner.binding
}

function workingCopy(owner: RegionSyncOwner) {
  if (!isRegionSyncOwnerCurrent(owner)) throw new Error("The draft, SVG or Regions binding changed. Open synchronization again.")
  const session = getAppDraftSession(owner.map.id)
  if (!session.ready || owner.draftId == null || session.activeId !== owner.draftId || !session.active) throw new Error("Open a saved draft before synchronizing Regions.")
  if (session.active.conflicted) throw new Error("Resolve the draft conflict before synchronizing Regions.")
  if (session.offline) throw new Error("Connect to the server before synchronizing Regions.")
  return { session, copy: session.active }
}

async function previewRegionOperation<T>(owner: RegionSyncOwner, operation: "sync" | "cleanup"): Promise<T> {
  const { session } = workingCopy(owner)
  const snapshot = owner.map.getData?.()
  if (snapshot) session.capture(snapshot as AppSnapshot)
  await session.flush(owner.draftId)
  const { copy } = workingCopy(owner)
  if (copy.dirty) throw new Error("The draft changed while saving. Review the changes again.")
  const plan = await draftRequest<T>(`/apps/${owner.map.id}/drafts/${owner.draftId}/regions-${operation}/preview`, "POST", {
    revision: copy.revision, pageId: owner.pageId, stateId: owner.stateId,
  })
  workingCopy(owner)
  return plan
}

export const previewRegionSync = (owner: RegionSyncOwner) => previewRegionOperation<RegionSyncPlan>(owner, "sync")
export const previewRegionCleanup = (owner: RegionSyncOwner) => previewRegionOperation<RegionCleanupPlan>(owner, "cleanup")

export async function applyRegionSync(owner: RegionSyncOwner, plan: RegionSyncPlan): Promise<number> {
  return applyRegionOperation(owner, plan, "sync")
}
export async function applyRegionCleanup(owner: RegionSyncOwner, plan: RegionCleanupPlan): Promise<number> {
  return applyRegionOperation(owner, plan, "cleanup")
}
async function applyRegionOperation(owner: RegionSyncOwner, plan: Pick<RegionSyncPlan, "revision" | "token">, operation: "sync" | "cleanup"): Promise<number> {
  const { copy } = workingCopy(owner)
  if (copy.dirty || copy.revision !== plan.revision) throw new Error("The draft changed after this preview. Review the changes again.")
  const result = await draftRequest<{ inserted?: number; deleted?: number }>(`/apps/${owner.map.id}/drafts/${owner.draftId}/regions-${operation}`, "POST", {
    revision: plan.revision, pageId: owner.pageId, stateId: owner.stateId, token: plan.token,
  })
  if (isRegionSyncOwnerCurrent(owner)) owner.map.regionsRepository?.reload?.({ automatic: true })
  return (operation === "sync" ? result.inserted : result.deleted) ?? 0
}
