import { createContext, useContext, useEffect, useState, type ReactNode } from "react"
import { Button } from "@/components/ui/button"
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle,
} from "@/components/ui/dialog"
import { findLegacyContainerCssClasses } from "@/lib/layout-migration"
import { readLayoutOptions } from "@/lib/layout-grid"
import { useAdminMap } from "@/lib/live-map-options"

type PendingMigration = { mapId: number; action: () => void }
type MigrationContext = { requestMigration: (action: () => void) => void }

const LayoutMigrationContext = createContext<MigrationContext | null>(null)

/** All map editing surfaces share one confirmation for the first tree-layout change. */
export function LayoutMigrationProvider({ mapId, children }: {
  mapId: number | null
  children: ReactNode
}) {
  const map = useAdminMap()
  const [pending, setPending] = useState<PendingMigration | null>(null)
  useEffect(() => setPending(null), [mapId])

  const requestMigration = (action: () => void) => {
    if (!map || mapId == null || map.id !== mapId) return
    if (readLayoutOptions(map.options?.layout).mountMode === "tree") {
      action()
      return
    }
    setPending({ mapId, action })
  }

  const matches = findLegacyContainerCssClasses(map?.options?.css)
  const confirm = () => {
    const current = pending
    setPending(null)
    if (current && map?.id === current.mapId && mapId === current.mapId) {
      current.action()
    }
  }

  return (
    <LayoutMigrationContext.Provider value={{ requestMigration }}>
      {children}
      <Dialog open={pending != null} onOpenChange={(open) => { if (!open) setPending(null) }}>
        <DialogContent className="sm:max-w-xl">
          <DialogHeader className="text-left">
            <DialogTitle>Migrate to the new layout?</DialogTitle>
            <DialogDescription>
              The new layout mounts components in slot containers instead of the old sidebar,
              header, and footer containers.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3 text-sm">
            <p>
              Custom CSS targeting old container classes will no longer style the new slot
              containers. Custom JavaScript that selects or controls the old containers will
              no longer control slot content.
            </p>
            {matches.length > 0 ? (
              <p className="rounded-md border border-amber-300 bg-amber-50 p-3 text-amber-900">
                Your map CSS contains references to old container classes:{" "}
                <strong>{matches.map((name) => `.${name}`).join(", ")}</strong>.
              </p>
            ) : (
              <p className="rounded-md border border-border bg-muted/40 p-3">
                We did not find old container classes in this map’s CSS. They may still be used
                in your WordPress theme or elsewhere, so please check any custom code you added.
              </p>
            )}
            <p>
              Migration is saved automatically in your draft. You can inspect the result
              before publishing it to the front-end.
            </p>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setPending(null)}>Cancel</Button>
            <Button type="button" onClick={confirm}>Migrate</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </LayoutMigrationContext.Provider>
  )
}

export function useLayoutMigration(): MigrationContext {
  const context = useContext(LayoutMigrationContext)
  // Standalone settings renderers use the immediate path; the app installs the provider.
  return context ?? { requestMigration: (action) => action() }
}
