import { useMemo } from "react"
import { getAdminPanelDefinition } from "@/lib/admin-extension-registry"
import { Button } from "@/components/ui/button"
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/components/ui/empty"

/** Welcome/chat startup must not import the map canvas, settings or SVG editor. */
export function StartScreenPanel({ onNewMap, chatId, onChatSaved }: {
  onNewMap?: () => void
  chatId?: number | null
  onChatSaved?: (chat: import("@/lib/project-chats").ProjectChat) => void
}) {
  const StartScreen = useMemo(() => getAdminPanelDefinition("ai-start-screen")?.Panel, [])
  const actions = <div data-slot="start-screen-actions" role="group" aria-label="Map creation" className="flex flex-wrap justify-center gap-2 py-2">
    <Button type="button" variant="outline" onClick={onNewMap}>Create new map manually</Button>
  </div>
  return <div data-slot="map-preview-panel" className="relative flex h-full min-h-0 flex-col overflow-hidden">
    <div className="relative min-h-0 flex-1 overflow-hidden">
      {StartScreen ? <StartScreen mapId={null} chatId={chatId} onChatSaved={onChatSaved} startScreenActions={actions} /> : <div className="flex h-full items-center justify-center p-6">
        <Empty className="border-0 md:p-6"><EmptyHeader>
          <EmptyTitle className="text-xl">Welcome to MapSVG</EmptyTitle>
          <EmptyDescription>Select a map from Maps, or create a new one to get started.</EmptyDescription>
        </EmptyHeader>{actions}</Empty>
      </div>}
    </div>
  </div>
}
