import { deferredAdminComponent } from "@/lib/deferred-admin-component"

export { ComponentInteractionsProvider } from "@/components/component-interactions-context"

// Registration needs the shared provider immediately. The controller renderer
// is only needed when a paid panel mounts; core's synchronous public controller
// is already owned by the deferred SettingsPanel graph.
export const ComponentController = deferredAdminComponent(() => import("@/components/ComponentController").then(module => ({ default: module.ComponentController })))
