import { useSyncExternalStore } from "react"
import { APP_STATE_CHANGED } from "@/lib/app-state-editor"
import {
  DEFAULT_TEMPLATE_JS,
  TEMPLATE_DEFAULTS,
} from "@/components/settings/componentContentDefaults"
import {
  getAdminMapInstance,
  subscribeAdminMapInstance,
} from "@/lib/apply-options-patch"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v)
}

/** Live MapPreview instance (null until a map is selected/loaded). */
export function useAdminMap(): MapsvgMapInstance | null {
  return useSyncExternalStore(subscribeAdminMapInstance, getAdminMapInstance, () => null)
}

/**
 * Overlay live values onto defaults, only for keys present in defaults
 * (so passing full `map.options` does not pollute a settings slice).
 */
export function mergeOptionsSlice(
  defaults: Record<string, unknown>,
  live: unknown,
): Record<string, unknown> {
  const base = structuredClone(defaults) as Record<string, unknown>
  if (!isPlainObject(live)) return base

  const merge = (
    target: Record<string, unknown>,
    patch: Record<string, unknown>,
  ): Record<string, unknown> => {
    const out: Record<string, unknown> = { ...target }
    for (const key of Object.keys(target)) {
      if (!(key in patch)) continue
      const value = patch[key]
      if (isPlainObject(value) && isPlainObject(out[key])) {
        out[key] = merge(
          out[key] as Record<string, unknown>,
          value,
        )
      } else {
        out[key] = value
      }
    }
    return out
  }

  return merge(base, live)
}

export function readLiveTemplate(
  map: MapsvgMapInstance | null,
  name: string,
): { html: string; css: string; js: string } {
  const fallback = TEMPLATE_DEFAULTS[name]
  const templates = map?.options?.templates
  const raw =
    templates && isPlainObject(templates) ? templates[name] : undefined

  if (typeof raw === "string") {
    return {
      html: raw,
      css: fallback?.css ?? "",
      js: fallback?.js || DEFAULT_TEMPLATE_JS,
    }
  }

  if (isPlainObject(raw)) {
    return {
      html:
        typeof raw.html === "string"
          ? raw.html
          : (fallback?.html ?? ""),
      css:
        typeof raw.css === "string" ? raw.css : (fallback?.css ?? ""),
      js:
        typeof raw.js === "string"
          ? raw.js
          : fallback?.js || DEFAULT_TEMPLATE_JS,
    }
  }

  return {
    html: fallback?.html ?? "",
    css: fallback?.css ?? "",
    js: fallback?.js || DEFAULT_TEMPLATE_JS,
  }
}

export function readLiveCss(map: MapsvgMapInstance | null, fallback: string): string {
  const css = map?.options?.css
  return typeof css === "string" ? css : fallback
}

export function readLiveEventScript(
  map: MapsvgMapInstance | null,
  name: string,
  fallback: string,
): string {
  const events = map?.options?.events
  if (isPlainObject(events) && typeof events[name] === "string") {
    return events[name] as string
  }
  return fallback
}

export function readLiveMiddleware(
  map: MapsvgMapInstance | null,
  name: string,
  fallback: string,
): string {
  const middlewares = map?.options?.middlewares
  if (isPlainObject(middlewares) && typeof middlewares[name] === "string") {
    return middlewares[name] as string
  }
  return fallback
}

/** Apply a partial options patch to the live map (preview). */
export function patchLiveMapOptions(patch: Record<string, unknown>): void {
  const map = getAdminMapInstance()
  if (!map || typeof map.update !== "function") return
  const previousNodes = Object.keys(patch).length === 1 && patch.nodes ? map.options.nodes : undefined
  map.update(patch)
  if ((patch.nodes || patch.scenes) && !patch.layout) map.refreshTreeLayout?.(previousNodes)
  notifyOptionsListeners()
}

/** Replace editor-owned scripts through the runtime's configured-handler seam. */
export function patchLiveMapScript(id: string, source: string): void {
  const map = getAdminMapInstance()
  if (!map) return
  if (id.startsWith("middlewares.")) {
    const scripts = { [id.slice("middlewares.".length)]: source }
    if (map.setMiddlewares) map.setMiddlewares(scripts, true)
    else map.update({ middlewares: scripts })
  } else {
    if (map.setEvents) map.setEvents({ [id]: source }, true)
    else map.update({ events: { [id]: source } })
  }
  notifyOptionsListeners()
}

const optionsListeners = new Set<() => void>()

/** Re-render admin UI when live map options change (nodes, layout, …). */
export function subscribeLiveMapOptions(listener: () => void): () => void {
  optionsListeners.add(listener)
  window.addEventListener(APP_STATE_CHANGED, listener)
  return () => {
    optionsListeners.delete(listener)
    window.removeEventListener(APP_STATE_CHANGED, listener)
  }
}

function notifyOptionsListeners(): void {
  for (const listener of optionsListeners) listener()
}

/** Deep-merge a partial `colors` slice onto live options. */
export function patchLiveColors(slice: Record<string, unknown>): void {
  patchLiveMapOptions({ colors: slice })
}

function isBrightnessValue(v: unknown): boolean {
  if (typeof v === "number") return true
  if (typeof v === "string") return /^-?\d+(\.\d+)?$/.test(v.trim())
  return false
}

/**
 * Region styles form = `colors` + UI-only hoverMode/selectedMode
 * (inferred from whether hover/selected are brightness numbers or color strings).
 */
export function regionStylesFromColors(
  defaults: Record<string, unknown>,
  colors: unknown,
): Record<string, unknown> {
  const merged = mergeOptionsSlice(defaults, colors)
  return {
    ...merged,
    hoverMode: isBrightnessValue(merged.hover) ? "brightness" : "color",
    selectedMode: isBrightnessValue(merged.selected)
      ? "brightness"
      : "color",
  }
}

/** Strip UI-only mode keys before writing back to `colors`. */
export function regionStylesToColors(
  next: Record<string, unknown>,
): Record<string, unknown> {
  const { hoverMode: _h, selectedMode: _s, ...rest } = next
  return rest
}

/** Nested `database` slice (pagination / loadOnStart / autoRefetch). */
export function readLiveDatabase(
  map: MapsvgMapInstance | null,
): Record<string, unknown> {
  const db = map?.options?.database
  return isPlainObject(db) ? db : {}
}

/** Nested `colors` object. */
export function readLiveColors(
  map: MapsvgMapInstance | null,
): Record<string, unknown> {
  const colors = map?.options?.colors
  return isPlainObject(colors) ? colors : {}
}
