function asPromise<T = unknown>(request: any): Promise<T> {
  if (request && typeof request.done === "function" && typeof request.fail === "function") {
    return new Promise<T>((resolve, reject) => {
      request.done((value: T) => resolve(value))
      request.fail((error: unknown) => reject(error))
    })
  }
  return Promise.resolve(request as T)
}

function getMapsRepository(): any {
  const mapsvg = (window as any).mapsvg
  if (!mapsvg?.useRepository) {
    throw new Error("Maps repository is unavailable")
  }
  return mapsvg.useRepository("maps")
}

type AppSurface = "workspace" | "start" | "database-index"

function useDialogRequested(open: boolean): boolean {
  const [requested, setRequested] = useState(open)
  useEffect(() => { if (open) setRequested(true) }, [open])
  return open || requested
}

