export function installSharedAdmin(): void {
 Object.assign(window, { MapSVGAdminShared: {
   "@/lib/upgrade-reload": upgradeReload,
   "@/lib/workspace-context": workspaceContext,
   "@/components/layout/LayoutMigrationDialog": migration,
   "@/components/ComponentController": controller,
   "@/components/ui/tooltip": tooltip,
   "@/lib/live-map-options": live,
   "@/lib/apply-options-patch": map,
   "@/lib/shadow-root": shadow,
   "@/lib/app-galleries": galleries,
   "@/lib/app-drafts": drafts,
 } })
}
