/** Layout grid slot widget (GridStack JSON → future CSS Grid runtime). */

export type LayoutBreakpoint = "desktop" | "tablet" | "mobile"

export type LayoutGsWidget = {
  id: string
  x: number
  y: number
  w: number
  h: number
}

export type LayoutGrids = Record<LayoutBreakpoint, LayoutGsWidget[]>

export type LayoutOptionsSlice = {
  column: number
  gap: number
  cellHeight: number
  grids: LayoutGrids
  mountMode?: "tree"
  /** Explicit deletion suppresses legacy required-node seeding until added again. */
  deletedNodeTypes?: string[]
}

export const LAYOUT_SLOT_ID_RE = /^[A-Z][A-Za-z0-9]*$/

/** Human names stay in node.title; internal references use a safe, unique ID. */
export function slotIdFromName(name: string, existing: Iterable<string>, opts?: { excludeId?: string }): string {
  const words = name.normalize("NFKD").replace(/\p{M}/gu, "").match(/[A-Za-z0-9]+/g) ?? []
  let base = words.map(word => word[0].toUpperCase() + (/^[A-Z]+$/.test(word) ? word.slice(1).toLowerCase() : word.slice(1))).join("") || "Slot"
  if (!/^[A-Z]/.test(base)) base = `Slot${base}`
  base = base.slice(0, 64)
  const used = new Set(existing)
  if (opts?.excludeId) used.delete(opts.excludeId)
  used.add("Map") // Legacy parser aliases Map to Main.
  let id = base, suffix = 2
  while (used.has(id)) {
    const ending = String(suffix++)
    id = base.slice(0, 64 - ending.length) + ending
  }
  return id
}

export const LAYOUT_BREAKPOINTS: LayoutBreakpoint[] = [
  "desktop",
  "tablet",
  "mobile",
]

/** Preview frame max widths (px). Desktop = full panel. */
export const LAYOUT_DEVICE_FRAME_PX: Record<LayoutBreakpoint, number | null> = {
  desktop: null,
  tablet: 768,
  mobile: 390,
}

export const DEFAULT_LAYOUT_COLUMN = 12
export const DEFAULT_LAYOUT_GAP = 0
export const DEFAULT_LAYOUT_CELL_HEIGHT = 64

const CLASSIC_DESKTOP: LayoutGsWidget[] = [
  { id: "Header", x: 0, y: 0, w: 12, h: 1 },
  { id: "LeftSidebar", x: 0, y: 1, w: 3, h: 6 },
  { id: "Main", x: 3, y: 1, w: 6, h: 6 },
  { id: "RightSidebar", x: 9, y: 1, w: 3, h: 6 },
  { id: "Footer", x: 0, y: 7, w: 12, h: 1 },
]

const CLASSIC_TABLET: LayoutGsWidget[] = [
  { id: "Header", x: 0, y: 0, w: 12, h: 1 },
  { id: "LeftSidebar", x: 0, y: 1, w: 4, h: 5 },
  { id: "Main", x: 4, y: 1, w: 8, h: 5 },
  { id: "RightSidebar", x: 0, y: 6, w: 12, h: 2 },
  { id: "Footer", x: 0, y: 8, w: 12, h: 1 },
]

const CLASSIC_MOBILE: LayoutGsWidget[] = [
  { id: "Header", x: 0, y: 0, w: 12, h: 1 },
  { id: "Main", x: 0, y: 1, w: 12, h: 4 },
  { id: "LeftSidebar", x: 0, y: 5, w: 12, h: 2 },
  { id: "RightSidebar", x: 0, y: 7, w: 12, h: 2 },
  { id: "Footer", x: 0, y: 9, w: 12, h: 1 },
]

export function classicLayoutGrids(): LayoutGrids {
  return {
    desktop: structuredClone(CLASSIC_DESKTOP),
    tablet: structuredClone(CLASSIC_TABLET),
    mobile: structuredClone(CLASSIC_MOBILE),
  }
}

export function defaultLayoutOptions(): LayoutOptionsSlice {
  return {
    column: DEFAULT_LAYOUT_COLUMN,
    gap: DEFAULT_LAYOUT_GAP,
    cellHeight: DEFAULT_LAYOUT_CELL_HEIGHT,
    grids: classicLayoutGrids(),
  }
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v)
}

function parseWidget(raw: unknown): LayoutGsWidget | null {
  if (!isPlainObject(raw)) return null
  let id = typeof raw.id === "string" ? raw.id : ""
  // Early seed used "Map" for the center cell; canonical id is Main.
  if (id === "Map") id = "Main"
  if (!LAYOUT_SLOT_ID_RE.test(id)) return null
  const x = Number(raw.x)
  const y = Number(raw.y)
  const w = Number(raw.w)
  const h = Number(raw.h)
  if (![x, y, w, h].every((n) => Number.isFinite(n))) return null
  return {
    id,
    x: Math.max(0, Math.floor(x)),
    y: Math.max(0, Math.floor(y)),
    w: Math.max(1, Math.floor(w)),
    h: Math.max(1, Math.floor(h)),
  }
}

function parseGrid(raw: unknown, fallback: LayoutGsWidget[]): LayoutGsWidget[] {
  if (!Array.isArray(raw)) return structuredClone(fallback)
  const out: LayoutGsWidget[] = []
  const seen = new Set<string>()
  for (const item of raw) {
    const w = parseWidget(item)
    if (!w || seen.has(w.id)) continue
    seen.add(w.id)
    out.push(w)
  }
  return out
}

/** Normalize live `options.layout` or seed classic grids. */
export function readLayoutOptions(live: unknown): LayoutOptionsSlice {
  const defaults = defaultLayoutOptions()
  if (!isPlainObject(live)) return defaults

  const gridsRaw = isPlainObject(live.grids) ? live.grids : {}
  const classic = classicLayoutGrids()

  return {
    column:
      typeof live.column === "number" && live.column > 0
        ? Math.floor(live.column)
        : defaults.column,
    // Page containers touch, including retained layouts with an older saved gap.
    gap: DEFAULT_LAYOUT_GAP,
    cellHeight: (() => {
      const raw =
        typeof live.cellHeight === "number" && live.cellHeight > 0
          ? live.cellHeight
          : defaults.cellHeight
      return Math.max(raw, DEFAULT_LAYOUT_CELL_HEIGHT)
    })(),
    grids: {
      desktop: parseGrid(gridsRaw.desktop, classic.desktop),
      tablet: parseGrid(gridsRaw.tablet, classic.tablet),
      mobile: parseGrid(gridsRaw.mobile, classic.mobile),
    },
    ...(live.mountMode === "tree" ? { mountMode: "tree" as const } : {}),
    ...(Array.isArray(live.deletedNodeTypes) ? { deletedNodeTypes: [...new Set(live.deletedNodeTypes.filter((type):type is string => type === "map" || type === "mobileToolbar"))] } : {}),
  }
}

export function validateSlotId(
  id: string,
  existing: Iterable<string>,
  opts?: { excludeId?: string },
): string | null {
  const trimmed = id.trim()
  if (!LAYOUT_SLOT_ID_RE.test(trimmed)) {
    return "Use PascalCase (e.g. LeftSidebar)."
  }
  if (trimmed === "Map") {
    return "Map is reserved for the legacy Main slot alias."
  }
  for (const other of existing) {
    if (other === trimmed) {
      if (opts?.excludeId && opts.excludeId === other) continue
      return "This slot id is already used."
    }
  }
  return null
}

export function widgetsFromGridSave(
  nodes: Array<{ id?: string | number; x?: number; y?: number; w?: number; h?: number }>,
): LayoutGsWidget[] {
  const out: LayoutGsWidget[] = []
  const seen = new Set<string>()
  for (const n of nodes) {
    const id = n.id != null ? String(n.id) : ""
    if (!LAYOUT_SLOT_ID_RE.test(id) || seen.has(id)) continue
    seen.add(id)
    out.push({
      id,
      x: Math.max(0, Math.floor(Number(n.x) || 0)),
      y: Math.max(0, Math.floor(Number(n.y) || 0)),
      w: Math.max(1, Math.floor(Number(n.w) || 1)),
      h: Math.max(1, Math.floor(Number(n.h) || 1)),
    })
  }
  return out
}
