type Node = { id: string; type: string; children?: string[] }
type Page = { id: string; rootNodeId?: string; bodyNodeId?: string }
type Options = { nodes?: unknown; scenes?: unknown }

function counts(options: Options): Map<string, number> {
  const nodes = Array.from((options.nodes ?? []) as ArrayLike<Node>)
  const pages = Array.from((options.scenes ?? []) as ArrayLike<Page>)
  const byId = new Map(nodes.map(node => [node.id, node]))
  return new Map((pages.length ? pages : [{ id: "default" }]).map(page => {
    // A single legacy Page includes all layout slots, not only its Main root.
    const pending = pages.length > 1 ? [page.rootNodeId, page.bodyNodeId]
      : nodes.filter(node => node.type === "slot" || node.type === "body").map(node => node.id)
    const visited = new Set<string>()
    let maps = 0
    while (pending.length) {
      const id = pending.pop()
      if (!id || visited.has(id)) continue
      visited.add(id)
      const node = byId.get(id)
      if (!node) continue
      if (node.type === "map") maps++
      pending.push(...(node.children ?? []))
    }
    return [page.id, maps]
  }))
}

/** Preserve old documents, but never add another Map to an occupied Page. */
export function introducesExtraPageMap(before: Options, after: Options): boolean {
  const previous = counts(before)
  return [...counts(after)].some(([id, count]) => count > 1 && count > (previous.get(id) ?? 0))
}

export function canAddMapToPage(nodes: Node[], scenes: Page[], parentId: string): boolean {
  let id = "new-map"
  while (nodes.some(node => node.id === id)) id += "-new"
  const next = nodes.map(node => node.id === parentId ? { ...node, children: [...(node.children ?? []), id] } : node)
  next.push({ id, type: "map", children: [] })
  return !introducesExtraPageMap({ nodes, scenes }, { nodes: next, scenes })
}
