import { useImperativeHandle, useLayoutEffect, useState, type Ref } from "react"
import { FocusScope } from "@radix-ui/react-focus-scope"
import { Branch, DismissableLayer } from "@radix-ui/react-dismissable-layer"

function useVisibleAuthCheck() {
  const [visible, setVisible] = useState<HTMLElement | null>(null)

  useLayoutEffect(() => {
    let wrap: HTMLElement | null = null
    const syncVisibility = () => {
      setVisible(wrap && !wrap.hidden && !wrap.classList.contains("hidden") &&
        getComputedStyle(wrap).display !== "none" ? wrap : null)
    }
    const visibilityObserver = new MutationObserver(syncVisibility)
    const findWrap = () => {
      const next = document.getElementById("wp-auth-check-wrap")
      if (next !== wrap) {
        visibilityObserver.disconnect()
        wrap = next
        if (wrap) visibilityObserver.observe(wrap, { attributes: true, attributeFilter: ["class", "style", "hidden"] })
      }
      syncVisibility()
    }
    // WordPress appends this native, light-DOM sibling to body in the footer.
    const bodyObserver = new MutationObserver(findWrap)
    bodyObserver.observe(document.body, { childList: true })
    findWrap()
    return () => {
      visibilityObserver.disconnect()
      bodyObserver.disconnect()
    }
  }, [])

  return visible
}

// Register the existing native node with Radix without moving or replacing any
// WordPress markup/iframe. This adapter supplies refs only; WP owns its DOM/events.
function NativeAuthElement({ element, ref }: { element: HTMLElement; ref?: Ref<HTMLElement> }) {
  useImperativeHandle(ref, () => element, [element])
  return null
}

function ActiveAuthCheck({ wrap }: { wrap: HTMLElement }) {
  useLayoutEffect(() => {
    const pointerEvents = wrap.style.getPropertyValue("pointer-events")
    const pointerPriority = wrap.style.getPropertyPriority("pointer-events")
    wrap.style.setProperty("pointer-events", "auto")
    // A previously opened modal's hideOthers() may have hidden this sibling.
    // Keep its counter/marker owned by Radix; the native hidden class suffices
    // after reauthentication closes, so do not restore a stale aria-hidden=true.
    const expose = () => {
      if (wrap.getAttribute("aria-hidden") === "true") wrap.removeAttribute("aria-hidden")
    }
    const accessibilityObserver = new MutationObserver(expose)
    accessibilityObserver.observe(wrap, { attributes: true, attributeFilter: ["aria-hidden"] })
    expose()
    const keepNativeScroll = (event: Event) => event.stopPropagation()
    wrap.addEventListener("wheel", keepNativeScroll)
    wrap.addEventListener("touchmove", keepNativeScroll)
    return () => {
      accessibilityObserver.disconnect()
      wrap.style.setProperty("pointer-events", pointerEvents, pointerPriority)
      wrap.removeEventListener("wheel", keepNativeScroll)
      wrap.removeEventListener("touchmove", keepNativeScroll)
    }
  }, [wrap])

  return (
    <FocusScope
      asChild
      onMountAutoFocus={event => {
        event.preventDefault()
        wrap.querySelector<HTMLElement>("#wp-auth-check-frame, .wp-auth-fallback-expired")?.focus()
      }}
      onUnmountAutoFocus={event => event.preventDefault()}
    >
      <DismissableLayer asChild disableOutsidePointerEvents onEscapeKeyDown={event => event.preventDefault()}>
        <Branch asChild>
          <NativeAuthElement element={wrap} />
        </Branch>
      </DismissableLayer>
    </FocusScope>
  )
}

/** Native reauthentication temporarily takes priority over every retained modal. */
export function WordPressAuthCheckBridge() {
  const wrap = useVisibleAuthCheck()
  return wrap ? <ActiveAuthCheck key={wrap.id} wrap={wrap} /> : null
}
