import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

export const MAX_LIVE_ADMIN_MAP_RUNTIMES = 2

type CacheEntry = {
  mapId: number
  map: MapsvgMapInstance
  root: HTMLElement
  holder: DocumentFragment
  lastUsed: number
}

const cache = new Map<number, CacheEntry>()
const discardOnPark = new Set<number>()
let clock = 0

function getRuntimeRoot(map: MapsvgMapInstance): HTMLElement | null {
  const containers = (map as unknown as {
    containers?: {
      root?: HTMLElement
      wrapAll?: HTMLElement
    }
  }).containers
  return containers?.root ?? containers?.wrapAll ?? null
}
function destroyEntry(entry: CacheEntry): void {
  cache.delete(entry.mapId)
  try {
    entry.map.destroy()
  } catch {
    // Runtime may already have been destroyed by an explicit reload.
  }
}

function trimCache(protectedMapId: number): void {
  while (cache.size > MAX_LIVE_ADMIN_MAP_RUNTIMES) {
    const candidates = [...cache.values()]
      .filter((entry) => entry.mapId !== protectedMapId)
      .sort((a, b) => a.lastUsed - b.lastUsed)
    const victim = candidates[0]
    if (!victim) return
    destroyEntry(victim)
  }
}

export function rememberAdminMapRuntime(
  mapId: number,
  map: MapsvgMapInstance,
): boolean {
  const root = getRuntimeRoot(map)
  if (!root) return false
  const existing = cache.get(mapId)
  if (existing && existing.map !== map) destroyEntry(existing)

  cache.set(mapId, {
    mapId,
    map,
    root,
    holder: document.createDocumentFragment(),
    lastUsed: ++clock,
  })
  trimCache(mapId)
  return true
}

export function parkAdminMapRuntime(
  mapId: number,
  map: MapsvgMapInstance,
): boolean {
  const entry = cache.get(mapId)
  if (!entry || entry.map !== map) return false

  if (discardOnPark.delete(mapId)) {
    destroyEntry(entry)
    return true
  }

  entry.lastUsed = ++clock
  entry.holder.appendChild(entry.root)
  return true
}
export function takeAdminMapRuntime(
  mapId: number,
  host: HTMLElement,
): MapsvgMapInstance | null {
  const entry = cache.get(mapId)
  if (!entry) return null

  entry.lastUsed = ++clock
  host.innerHTML = ""
  host.appendChild(entry.root)

  window.requestAnimationFrame(() => {
    const runtime = entry.map as MapsvgMapInstance & { redraw?: () => void }
    runtime.redraw?.()
  })

  return entry.map
}

export function markAdminMapRuntimeForDiscard(mapId: number): void {
  if (cache.has(mapId)) discardOnPark.add(mapId)
}

export function invalidateAdminMapRuntime(mapId: number): void {
  discardOnPark.delete(mapId)
  const entry = cache.get(mapId)
  if (entry) destroyEntry(entry)
}

export function getCachedAdminMapIds(): number[] {
  return [...cache.values()]
    .sort((a, b) => b.lastUsed - a.lastUsed)
    .map((entry) => entry.mapId)
}

export function clearAdminMapRuntimeCache(): void {
  discardOnPark.clear()
  for (const entry of [...cache.values()]) destroyEntry(entry)
  clock = 0
}
