import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { appPageLabel } from "@/lib/app-page-label"
import { pageOwnsNode } from "@/lib/app-page-context"
import { introducesExtraPageMap } from "@/lib/single-page-map"
import { onlySurfaceColorChanges, SURFACE_COLOR_KEYS } from "../../../mapsvg/Map/surfaceColors"
import {
  ROOT_STATE, addAppState, applyChanges, clone, diffSettings, emptyStateGraph,
  independentStateGraph, isStateSetting, resolveState, scenePointId, stateScenes, updateStateChanges,
  validateStateGraph, type StateGraph,
} from "@/lib/app-state-graph"

export const APP_STATE_CHANGED = "mapsvg:app-state-changed"
// A live Map survives Vite HMR. Module-local ownership would wrap its already
// canonical getData() again and mistake the base for the effective projection.
const EDITOR_OWNER = Symbol.for("mapsvg.admin.app-state-editor")
type OwnedMap = MapsvgMapInstance & { [EDITOR_OWNER]?: AppStateEditor }

/** Owns authoring options; map.options remains the effective preview projection. */
export class AppStateEditor {
  // Increment if retained fields require migration, not for method-only updates.
  readonly ownerStateVersion = 1
  private base: Record<string, unknown>
  private projected: Record<string, unknown>
  private persisted: boolean
  private applying = false
  private pendingNotification = false
  private rawData: NonNullable<MapsvgMapInstance["getData"]>
  private rawUpdate: MapsvgMapInstance["update"]
  graph: StateGraph
  activeId = ROOT_STATE
  projectionRevision = 0
  private listeners = new Set<() => void>()

  constructor(readonly map: MapsvgMapInstance) {
    this.rawData = map.getData?.bind(map) ?? (() => ({ id: map.id, options: clone(map.options) }))
    this.rawUpdate = map.update.bind(map)
    this.base = this.readRaw()
    const scenes = stateScenes(this.base)
    this.persisted = map.options.stateGraph !== undefined
    this.graph = independentStateGraph(this.persisted ? validateStateGraph(map.options.stateGraph, scenes) : emptyStateGraph(scenes), scenes)
    this.projected = clone(this.base)
    map.getData = () => {
      this.capture()
      const record = this.rawData()
      return { ...record, options: this.canonicalOptions() }
    }
    map.update = (patch) => {
      if (this.applying) { this.rawUpdate(patch); return }
      if ((patch.nodes || patch.scenes) && introducesExtraPageMap(map.options, { ...map.options, ...patch })) {
        throw new Error("Only one Map component can be added to a Page.")
      }
      this.capture()
      // Legacy PHP can hydrate this ID-keyed dictionary as []. String-keyed region
      // changes on an array disappear during the runtime's JSON serialization.
      if (patch.regions && Array.isArray(map.options.regions)) map.options.regions = Object.fromEntries(Object.entries(map.options.regions))
      this.rawUpdate(patch)
      if (patch.regions) map.reloadAllRegionStyles?.()
      this.capture()
      this.project()
    }
    const selected = useWorkspaceStore.getState().mapSessions[String(map.id)]?.activeStateId
    const initial = selected && this.isPoint(selected) ? selected : this.graph.defaultStateId ?? ROOT_STATE
    if (this.isPoint(initial)) this.activeId = initial
    this.project(true)
  }

  /** Keep references/subscriptions and original runtime wrappers through HMR. */
  static adopt(editor: AppStateEditor) {
    if (Object.getPrototypeOf(editor) === AppStateEditor.prototype) return editor
    if (editor.ownerStateVersion !== undefined && editor.ownerStateVersion !== 1) {
      throw new Error("Reload the Map editor after changing its Scene storage contract.")
    }
    editor.capture()
    // These adapters use ordinary TS private fields, not JS #private slots.
    // The pre-version-marker owner has the same retained field contract.
    Object.setPrototypeOf(editor, AppStateEditor.prototype)
    if (editor.ownerStateVersion === undefined) Object.defineProperty(editor, "ownerStateVersion", { value: 1 })
    editor.project(true)
    editor.notify()
    return editor
  }

  private readRaw() {
    const options = clone(this.rawData().options)
    delete options.stateGraph
    return options
  }

  canonicalOptions() {
    return { ...clone(this.base), ...(this.persisted ? { stateGraph: clone(this.graph) } : {}) }
  }

  scenes() { return stateScenes(this.base) }
  activePageId() {
    const state = this.graph.states.find(item => item.id === this.activeId)
    const selected = state?.sceneId ?? this.scenes().find(page => scenePointId(page.id) === this.activeId)?.id
      ?? useWorkspaceStore.getState().mapSessions[String(this.map.id)]?.activePageId
    return this.scenes().find(page => page.id === selected)?.id ?? this.scenes()[0]?.id
  }
  canEditNode(id: string) {
    const pageId = this.activePageId()
    return !pageId || pageOwnsNode(this.base, pageId, id)
  }
  isPoint(id: string) {
    return id === ROOT_STATE || this.scenes().some((scene) => scenePointId(scene.id) === id) || this.graph.states.some((state) => state.id === id)
  }
  label() {
    const state = this.graph.states.find((point) => point.id === this.activeId)
    if (state) return `${appPageLabel(this.scenes().find(scene => scene.id === state.sceneId))}: ${state.title}`
    const scene = this.scenes().find((item) => scenePointId(item.id) === this.activeId) ?? this.scenes()[0]
    return this.activeId === ROOT_STATE ? "App : Base" : `${appPageLabel(scene)}: Base`
  }

  subscribe = (listener: () => void) => {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  private notify() {
    if (this.pendingNotification) return
    this.pendingNotification = true
    queueMicrotask(() => {
      this.pendingNotification = false
      for (const listener of this.listeners) listener()
      if (typeof window !== "undefined") window.dispatchEvent(new Event(APP_STATE_CHANGED))
    })
  }

  /** Captures direct runtime setters/pan as well as update() calls before draft or Publish reads. */
  capture() {
    if (this.applying) return
    const current = this.readRaw()
    const changes = diffSettings(this.projected, current)
    if (!changes.length) return
    const active = this.graph.states.find((state) => state.id === this.activeId)
    const pageId = this.activePageId()
    const foreign = this.activeId !== ROOT_STATE && pageId && changes.some(change => isStateSetting(change.path) && (
      change.path[0] === "scenes" && change.path[1] !== `@${pageId}`
      || change.path[0] === "nodes" && !pageOwnsNode(this.base, pageId, change.path[1].slice(1))
    ))
    if (foreign) {
      // Reject the whole authoring operation and restore runtime before exposing the error.
      // Never reclassify foreign page properties as shared base writes.
      this.project(true)
      this.notify()
      throw new Error("Switch to the owning Page before editing its settings.")
    }
    const own = changes.filter((change) => active && isStateSetting(change.path)
      && (change.path[0] !== "scenes" || change.path[1] === `@${active.sceneId}`))
    const shared = changes.filter((change) => !own.includes(change))
    this.base = applyChanges(this.base, shared)
    if (active && own.length) {
      this.graph = updateStateChanges(this.graph, active.id, own)
      this.persisted = true
    }
    // Prune references to removed components/Scenes without resurrecting their identities.
    const sceneIds = new Set(this.scenes().map((scene) => scene.id))
    this.graph.states = this.graph.states.filter((state) => sceneIds.has(state.sceneId))
    this.graph.branches = this.graph.branches.filter((branch) => sceneIds.has(branch.sceneId))
    const nodeIds = new Set((Array.isArray(this.base.nodes) ? this.base.nodes : []).map((node) => `@${(node as { id: string }).id}`))
    for (const state of this.graph.states) state.changes = state.changes.filter((change) => change.path[0] !== "nodes" || nodeIds.has(change.path[1]))
    if (this.graph.defaultStateId && !this.isPoint(this.graph.defaultStateId)) this.graph.defaultStateId = null
    if (!this.isPoint(this.activeId)) this.activeId = ROOT_STATE
    this.projected = current
    this.notify()
  }

  private readRuntime() {
    const options = clone(this.map.getRuntimeOptions?.() ?? this.readRaw())
    // Compatibility with already-loaded runtime bundles during admin HMR.
    if (!this.map.getRuntimeOptions && this.map.getViewBox) options.viewBox = this.map.getViewBox().toArray()
    delete options.stateGraph
    return options
  }

  private project(reconcileRuntime = false) {
    const desired = resolveState(this.base, this.graph, this.activeId)
    const current = this.readRaw()
    const changes = diffSettings(current, desired)
    // Authoring serialization can differ from what is currently displayed.
    // State activation reconciles every runtime slice; ordinary field edits
    // preserve transient navigation instead of resetting it on each keystroke.
    if (reconcileRuntime) changes.push(...diffSettings(this.readRuntime(), desired))
    const changed = [...new Set(changes.map((change) => change.path[0]))]
    const beforeScenes = JSON.stringify(current.scenes)
    this.applying = true
    try {
      const patch: Record<string, unknown> = {}
      for (const key of changed) patch[key] = desired[key]
      if (changed.includes("colors")) {
        // Runtime color setters merge. Paint removed Scene backgrounds as empty,
        // then restore the exact serializable slice below (without authored defaults).
        const before = current.colors as Record<string, unknown> | undefined
        const after = desired.colors as Record<string, unknown> | undefined
        patch.colors = { ...after, ...Object.fromEntries(Object.keys(before ?? {})
          .filter(key => SURFACE_COLOR_KEYS.has(key) && !(key in (after ?? {})))
          .map(key => [key, ""])) }
      }
      // getData() serializes _viewBox, not the current camera. Restore both
      // when projecting a State's initial position so later edits stay isolated.
      if (changed.includes("viewBox") && Array.isArray(desired.viewBox)) {
        this.map.setInitialViewBox?.(clone(desired.viewBox) as number[])
      }
      if (changed.includes("events") && this.map.setEvents) {
        this.map.setEvents((desired.events ?? {}) as Record<string, string>, true)
        delete patch.events
      }
      if (changed.includes("middlewares") && this.map.setMiddlewares) {
        this.map.setMiddlewares((desired.middlewares ?? {}) as Record<string, string>, true)
        delete patch.middlewares
      }
      this.map.setActivePage?.(this.activePageId()!)
      if (Object.keys(patch).length) this.rawUpdate(patch)
      // Runtime setters can merge nested objects. Replace their serializable slices too,
      // so missing keys from a previous branch cannot leak into the next projection.
      for (const key of changed) {
        if (desired[key] === undefined) delete this.map.options[key]
        else this.map.options[key] = clone(desired[key])
      }
      // Per-region setters merge styles; a branch without that override must repaint too.
      if (changed.some((key) => ["regions", "regionStatuses", "regionDataRules"].includes(key)) ||
        changed.includes("colors") && !onlySurfaceColorChanges(current.colors, desired.colors)) this.map.reloadAllRegionStyles?.()
      if (changed.includes("markerDataRules")) this.map.reloadMarkerImages?.()
      if (changed.includes("nodes") || changed.includes("scenes")) this.map.refreshTreeLayout?.(changed.length === 1 && changed[0] === "nodes" ? current.nodes : undefined)
      if (this.persisted) this.map.options.stateGraph = clone(this.graph)
      this.projected = this.readRaw()
      this.map.refreshPageBindings?.()
    } finally { this.applying = false }
    if (!this.map.refreshPageBindings && beforeScenes !== JSON.stringify(desired.scenes)) {
      const repositories = this.map as MapsvgMapInstance & {
        objectsRepository?: { reload?: () => void }; regionsRepository?: { reload?: () => void }
      }
      repositories.objectsRepository?.reload?.()
      repositories.regionsRepository?.reload?.()
    }
  }

  select(id: string) {
    if (!this.isPoint(id)) throw new Error("Unknown App Scene.")
    this.capture()
    const previousPage = this.activePageId()
    this.activeId = id
    this.project(true)
    this.projectionRevision++
    const pageId = this.activePageId()
    useWorkspaceStore.getState().patchMapSession(this.map.id, {
      activeStateId: id, activePageId: pageId,
      ...(previousPage !== pageId ? { selectedNodeId: null, selectedSceneId: pageId, selectedComponentId: null } : {}),
    })
    this.notify()
  }

  create(sceneId: string, title: string) {
    this.capture()
    if (!this.scenes().some(scene => scene.id === sceneId)) throw new Error("Unknown Page.")
    const result = addAppState(this.graph, sceneId, null, "continue", title)
    this.graph = validateStateGraph(result.graph, this.scenes())
    this.persisted = true
    this.project()
    this.notify()
    return result.id
  }

  duplicate(id: string) {
    this.capture()
    const original = this.graph.states.find(state => state.id === id)
    if (!original) throw new Error("Unknown Scene.")
    const titles = new Set(this.graph.states.filter(state => state.sceneId === original.sceneId).map(state => state.title))
    let title = `${original.title} copy`, suffix = 2
    while (titles.has(title)) title = `${original.title} copy ${suffix++}`
    const duplicateId = this.create(original.sceneId, title)
    this.graph.states.find(state => state.id === duplicateId)!.changes = clone(original.changes)
    this.project()
    this.notify()
    return duplicateId
  }

  rename(id: string, title: string) {
    this.capture()
    const state = this.graph.states.find((item) => item.id === id)
    if (!state || !title.trim()) throw new Error("Enter a Scene title.")
    state.title = title.trim()
    this.persisted = true
    this.project()
    this.notify()
  }

  reset(id: string) {
    this.capture()
    const state = this.graph.states.find((item) => item.id === id)
    if (!state) return
    state.changes = []
    this.project(true)
    this.projectionRevision++
    this.notify()
  }

  setDefault(id: string) {
    if (!this.isPoint(id)) throw new Error("Choose a Scene, Page or root.")
    this.capture()
    this.graph.defaultStateId = id === ROOT_STATE ? null : id
    this.persisted = true
    this.project()
    this.notify()
  }
}

export function getAppStateEditor(map: MapsvgMapInstance): AppStateEditor {
  let editor = (map as OwnedMap)[EDITOR_OWNER]
  if (!editor) {
    editor = new AppStateEditor(map)
    Object.defineProperty(map, EDITOR_OWNER, { value: editor })
  }
  return AppStateEditor.adopt(editor)
}

/** Selection/reset invalidate editor drafts; ordinary keystrokes must keep focus. */
export function appStateProjectionKey(map: MapsvgMapInstance | null): string {
  if (!map) return "pending"
  const editor = (map as OwnedMap)[EDITOR_OWNER]
  return `${map.id}:${editor?.activeId ?? ROOT_STATE}:${editor?.projectionRevision ?? 0}`
}

/** Read-only context lookup for components that do not own adapter attachment. */
export function appEditingPageId(map: MapsvgMapInstance | null): string | undefined {
  if (!map) return undefined
  return (map as OwnedMap)[EDITOR_OWNER]?.activePageId() ?? stateScenes(map.options)[0]?.id
}
