/** Navigation metadata only. Collections and App snapshots retain their own owners. */
export type ProjectChat = {
  id: number
  mapId: number | null
  title: string
  updatedAt: string
  createdAt: string
}
export const PROJECT_CHAT_CHANGED = "mapsvg:project-chat-changed"
export function notifyProjectChat(chat: ProjectChat): void {
  window.dispatchEvent(
    new CustomEvent(PROJECT_CHAT_CHANGED, {
      detail: {
        id: chat.id,
        mapId: chat.mapId,
        title: chat.title,
        updatedAt: chat.updatedAt,
        createdAt: chat.createdAt,
      },
    }),
  )
}
export type ProjectChatProvider = {
  list: () => Promise<ProjectChat[]>
  rename: (id: number, title: string) => Promise<ProjectChat>
  attachMap: (chatId: number | null, mapId: number) => Promise<ProjectChat>
}
