export type ReactAdminMapListItem = {
  id: number
  title: string
}

export type ReactAdminAssetOrigin = "library" | "uploads"

export type ReactAdminSvgFileItem = {
  name: string
  relativeUrl: string
  pathShort: string
  origin?: ReactAdminAssetOrigin
  geoCalibrated?: boolean
  googleOverlay?: boolean
  assetId?: number
  revisionId?: number
  originalUrl?: string | null
}

export type ReactAdminImageFileItem = {
  name: string
  relativeUrl: string
  pathShort: string
  origin: ReactAdminAssetOrigin
  width: number
  height: number
  sourceKind?: "raster" | "svg"
  mimeType: "image/png" | "image/jpeg" | "image/gif" | "image/webp" | "image/svg+xml"
}

export type ReactAdminMarkerImageItem = {
  name: string
  relativeUrl: string
  pathShort: string
}

export type PreviewScript = { src: string; type: string; before: string[]; after: string[] }

export type ReactAdminParams = {
  apiUrl: string
  ajaxUrl?: string
  nonce: string
  pluginUrl: string
  homeUrl: string
  dashboardUrl?: string
  licenseProductSlug?: string
  cssUrl: string
  previewScripts?: PreviewScript[]
  version: string
  plan: string
  adminFeatureModules?: string[]
  dataLayerV2Enabled: boolean
  globalQueriesEnabled: boolean
  databaseImportEnabled: boolean
  maps: ReactAdminMapListItem[]
  svgFiles: ReactAdminSvgFileItem[]
  deferredCatalogs?: boolean
  svgRegistryEnabled?: boolean
  imageFiles?: ReactAdminImageFileItem[]
  markerImages: ReactAdminMarkerImageItem[]
  user: {
    id: number
    name: string
    email: string
    isAdmin: boolean
    canEditJavaScript?: boolean
  }
  options: unknown
  license?: {
    hasCode: boolean
    maskedKey: string
    currentDomain: string
    ok: boolean
    message: string
    code: string
    warning: string
    warningCode: string
    domainsUsed: number | null
    domainsMax: number | null
  } | null
  ai?: {
    provider?: string
    model?: string
    openaiConfigured?: boolean
    deepseekConfigured?: boolean
    configured?: boolean
  }
}

declare global {
  interface Window {
    // wp_localize_script stringifies top-level scalar booleans (true → "1").
    ajaxurl?: string
    mapsvgReactAdminParams?: Omit<ReactAdminParams, "databaseImportEnabled" | "deferredCatalogs"> & {
      databaseImportEnabled?: boolean | string
      deferredCatalogs?: boolean | string
    }
  }
}

export function getAdminParams(): ReactAdminParams {
  const p = window.mapsvgReactAdminParams
  return {
    apiUrl: p?.apiUrl ?? "",
    ajaxUrl: p?.ajaxUrl ?? window.ajaxurl ?? "",
    nonce: p?.nonce ?? "",
    pluginUrl: p?.pluginUrl ?? "",
    homeUrl: p?.homeUrl ?? "",
    dashboardUrl: p?.dashboardUrl,
    licenseProductSlug: p?.licenseProductSlug,
    cssUrl: p?.cssUrl ?? "",
    previewScripts: p?.previewScripts,
    version: p?.version ?? "",
    plan: p?.plan ?? "",
    adminFeatureModules: Array.isArray(p?.adminFeatureModules)
      ? p.adminFeatureModules.filter((id): id is string => typeof id === "string")
      : [],
    dataLayerV2Enabled: Boolean(p?.dataLayerV2Enabled),
    globalQueriesEnabled: Boolean(p?.globalQueriesEnabled),
    databaseImportEnabled: p?.databaseImportEnabled === true || p?.databaseImportEnabled === "1",
    maps: Array.isArray(p?.maps) ? p.maps : [],
    svgFiles: Array.isArray(p?.svgFiles) ? p.svgFiles : [],
    deferredCatalogs: p?.deferredCatalogs === true || p?.deferredCatalogs === "1",
    svgRegistryEnabled: p?.svgRegistryEnabled === true || (p?.svgRegistryEnabled as unknown) === "1",
    imageFiles: Array.isArray(p?.imageFiles) ? p.imageFiles : [],
    markerImages: Array.isArray(p?.markerImages) ? p.markerImages : [],
    user: {
      id: Number(p?.user?.id ?? 0),
      name: p?.user?.name ?? "User",
      email: p?.user?.email ?? "",
      isAdmin: Boolean(p?.user?.isAdmin),
      canEditJavaScript: p?.user?.canEditJavaScript,
    },
    options: p?.options ?? {},
    license: p?.license ?? undefined,
    ai: p?.ai,
  }
}

/** True only for the canonical WordPress.org/base Lite artifact. */
export function isLitePlan(plan: string | null | undefined): boolean {
  return plan === "mapsvg-lite"
}
