import { hasProductFeature } from "./product-features"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { patchLiveMapOptions } from "@/lib/live-map-options"
import { useWorkspaceStore } from "@/lib/workspace-store"
import {
  newGallery,
  readGalleries,
  type GalleryOptions,
} from "../../../mapsvg/Gallery/gallery-options"

export {
  galleryTitle,
  galleryTemplateTag,
  validGalleryFieldPath,
  readGalleries,
  GALLERY_DEFAULTS,
  galleryBoolean,
} from "../../../mapsvg/Gallery/gallery-options"
export type { GalleryOptions } from "../../../mapsvg/Gallery/gallery-options"

export function selectAppGallery(mapId: number, id: string | number | null, section: "components" | "gallery" = "components") {
  useWorkspaceStore.getState().patchMapSession(mapId, {
    selectedComponentId: section,
    selectedGalleryId: id === null ? null : String(id),
    selectedNodeId: null,
    selectedSceneId: null,
  })
}

/** Re-read the live list on every edit; never mutate ArrayIndexed or replace siblings with stale forms. */
export function updateAppGallery(
  map: MapsvgMapInstance,
  id: string | number,
  patch: Record<string, unknown>,
) {
  if (!hasProductFeature("gallery") || getAdminMapInstance() !== map) return
  const galleries = readGalleries(map.options.galleries)
  if (!galleries.some((gallery) => String(gallery.id) === String(id))) return
  const settings = Object.fromEntries(Object.entries(patch).filter(([key]) => key !== "id"))
  if (!Object.keys(settings).length) return
  patchLiveMapOptions({
    galleries: galleries.map((gallery) =>
      String(gallery.id) === String(id) ? { ...gallery, ...settings } : gallery,
    ),
  })
}

export function createAppGallery(map: MapsvgMapInstance, name?: string): GalleryOptions | undefined {
  if (!hasProductFeature("gallery") || getAdminMapInstance() !== map) return
  const galleries = readGalleries(map.options.galleries)
  const gallery = newGallery(galleries)
  if (name) { gallery.id = name; gallery.title = name }
  patchLiveMapOptions({ galleries: [...galleries, gallery] })
  selectAppGallery(map.id, gallery.id)
  return gallery
}

export function deleteAppGallery(map: MapsvgMapInstance, id: string | number) {
  if (!hasProductFeature("gallery") || getAdminMapInstance() !== map) return
  patchLiveMapOptions({
    galleries: readGalleries(map.options.galleries).filter(
      (gallery) => String(gallery.id) !== String(id),
    ),
  })
  selectAppGallery(map.id, null)
}

type Field = { name: string; label?: string; type: string; protected?: boolean; visible?: boolean }
type Repository = {
  getSchema?: () => { getFields?: () => Field[] }
  events?: {
    on: (event: string, cb: () => void) => void
    off: (event: string, cb: () => void) => void
  }
}
export type GallerySchemaMap = MapsvgMapInstance & {
  objectsRepository?: Repository
  regionsRepository?: Repository
}

export function galleryImageFields(map: GallerySchemaMap | null) {
  const fields: Array<{ value: string; label: string; path: string }> = []
  for (const [role, repository] of [
    ["Objects", map?.objectsRepository],
    ["Regions", map?.regionsRepository],
  ] as const) {
    for (const field of repository?.getSchema?.()?.getFields?.() ?? []) {
      if (field.protected && field.visible === false) continue
      const path =
        field.type === "post"
          ? `${field.name}.gallery`
          : ["image", "images"].includes(field.type)
            ? field.name
            : null
      if (!path) continue
      const label = `${role} · ${field.label || field.name} (${path})`
      fields.push({ value: `${role}:${path}`, path, label })
      if (role === "Objects")
        fields.push({
          value: `RegionObjects:${path}`,
          path: `objects.0.${path}`,
          label: `Region → first object · ${field.label || field.name} (objects.0.${path})`,
        })
    }
  }
  return fields
}
