import { adminRestFetch } from "@/lib/admin-rest-fetch"
import { getAdminParams } from "@/lib/admin-params"

/** Matches ResizablePanel `id`s in App.tsx. */
export const ADMIN_PANEL_PREVIEW_ID = "map-preview"
export const ADMIN_PANEL_SETTINGS_ID = "settings"

/** MapSVG Options key (plugin settings table). */
export const ADMIN_PANELS_LAYOUT_OPTION = "admin_panels_layout"

/** Legacy jQuery admin localStorage key (left panel %). */
const LEGACY_LS_KEY = "mapsvg-admin-panels-left-width"

export type AdminPanelsLayout = {
  [ADMIN_PANEL_PREVIEW_ID]: number
  [ADMIN_PANEL_SETTINGS_ID]: number
}

export const DEFAULT_ADMIN_PANELS_LAYOUT: AdminPanelsLayout = {
  [ADMIN_PANEL_PREVIEW_ID]: 50,
  [ADMIN_PANEL_SETTINGS_ID]: 50,
}

function clampPercent(n: number): number {
  return Math.min(80, Math.max(20, n))
}

function normalizeLayout(raw: unknown): AdminPanelsLayout | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null
  const obj = raw as Record<string, unknown>
  const left = Number(obj[ADMIN_PANEL_PREVIEW_ID])
  const right = Number(obj[ADMIN_PANEL_SETTINGS_ID])
  if (!Number.isFinite(left) || !Number.isFinite(right)) return null
  const preview = clampPercent(left)
  return {
    [ADMIN_PANEL_PREVIEW_ID]: preview,
    [ADMIN_PANEL_SETTINGS_ID]: clampPercent(100 - preview),
  }
}

function parseStoredLayout(value: unknown): AdminPanelsLayout | null {
  if (typeof value === "string") {
    const trimmed = value.trim()
    if (!trimmed) return null
    // Whole layout JSON, or a bare left-% number (legacy Options shape).
    if (/^\d+(\.\d+)?$/.test(trimmed)) {
      const preview = clampPercent(parseFloat(trimmed))
      return {
        [ADMIN_PANEL_PREVIEW_ID]: preview,
        [ADMIN_PANEL_SETTINGS_ID]: clampPercent(100 - preview),
      }
    }
    try {
      return normalizeLayout(JSON.parse(trimmed))
    } catch {
      return null
    }
  }
  return normalizeLayout(value)
}

function readLegacyLocalStorage(): AdminPanelsLayout | null {
  try {
    const saved = localStorage.getItem(LEGACY_LS_KEY)
    if (saved === null) return null
    const percent = parseFloat(saved)
    if (!Number.isFinite(percent)) return null
    const preview = clampPercent(percent)
    return {
      [ADMIN_PANEL_PREVIEW_ID]: preview,
      [ADMIN_PANEL_SETTINGS_ID]: clampPercent(100 - preview),
    }
  } catch {
    return null
  }
}

/** Initial layout: MapSVG Options → legacy localStorage → 50/50. */
export function readAdminPanelsLayout(options?: unknown): AdminPanelsLayout {
  const opts =
    options && typeof options === "object" && !Array.isArray(options)
      ? (options as Record<string, unknown>)
      : (getAdminParams().options as Record<string, unknown> | undefined)

  const fromOptions = parseStoredLayout(opts?.[ADMIN_PANELS_LAYOUT_OPTION])
  if (fromOptions) return fromOptions

  const fromLegacy = readLegacyLocalStorage()
  if (fromLegacy) return fromLegacy

  return { ...DEFAULT_ADMIN_PANELS_LAYOUT }
}

function apiBase(): { base: string; nonce: string } {
  const p = getAdminParams()
  return { base: p.apiUrl.replace(/\/?$/, ""), nonce: p.nonce }
}

/** Persist layout to MapSVG Options (fire-and-forget safe). */
export async function saveAdminPanelsLayout(
  layout: AdminPanelsLayout,
): Promise<void> {
  const normalized = normalizeLayout(layout) ?? DEFAULT_ADMIN_PANELS_LAYOUT
  const payload = JSON.stringify(normalized)
  const { base, nonce } = apiBase()

  // Keep in-memory bootstrap params in sync for this session.
  const params = window.mapsvgReactAdminParams
  if (params && typeof params.options === "object" && params.options) {
    ;(params.options as Record<string, unknown>)[ADMIN_PANELS_LAYOUT_OPTION] =
      payload
  }

  try {
    localStorage.setItem(
      LEGACY_LS_KEY,
      String(normalized[ADMIN_PANEL_PREVIEW_ID]),
    )
  } catch {
    // ignore
  }

  const res = await adminRestFetch(`${base}/options/`, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      "X-WP-Nonce": nonce,
    },
    credentials: "same-origin",
    body: JSON.stringify({
      options: { [ADMIN_PANELS_LAYOUT_OPTION]: payload },
    }),
  })
  if (!res.ok) {
    throw new Error(`Failed to save panel layout (${res.status})`)
  }
}
