import type { MapWorkspaceDraft } from "@/lib/workspace-store"

const suppressedDraftCapture = new Set<number>()

export function suppressMapDraftCapture(mapId: number): void {
  suppressedDraftCapture.add(mapId)
}

export function resumeMapDraftCapture(mapId: number): void {
  suppressedDraftCapture.delete(mapId)
}

export function isMapDraftCaptureSuppressed(mapId: number): boolean {
  return suppressedDraftCapture.has(mapId)
}

export function cloneMapOptions(map: unknown): Record<string, unknown> {
  const source =
    map && typeof map === "object" && typeof (map as { getData?: unknown }).getData === "function"
      ? (map as { getData: () => { options?: unknown } }).getData().options
      : (map as { options?: unknown } | null)?.options

  if (!source || typeof source !== "object") return {}
  return JSON.parse(JSON.stringify(source)) as Record<string, unknown>
}

function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null"
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableStringify(item)).join(",")}]`
  }

  const object = value as Record<string, unknown>
  const keys = Object.keys(object).sort()
  return `{${keys
    .map((key) => `${JSON.stringify(key)}:${stableStringify(object[key])}`)
    .join(",")}}`
}

export function fingerprintMapOptions(options: Record<string, unknown>): string {
  const serialized = stableStringify(options)
  let hash = 0x811c9dc5
  for (let index = 0; index < serialized.length; index += 1) {
    hash ^= serialized.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return `${(hash >>> 0).toString(16)}:${serialized.length}`
}

/**
 * Preserve the stored fingerprint format. Title dirty/conflict detection uses
 * a separate baselineTitle because sidebar rename persists it independently.
 * useShadowRoot is an admin runtime concern rather than map content.
 */
export function fingerprintEditableMapOptions(options: Record<string, unknown>): string {
  const editable = { ...options }
  delete editable.title
  delete editable.useShadowRoot
  return fingerprintMapOptions(editable)
}

export function mapOptionsTitle(options: Record<string, unknown>): string {
  return typeof options.title === "string" ? options.title : ""
}

/** Missing title metadata follows the legacy title-agnostic comparison. */
export function mapOptionsMatchBaseline(
  options: Record<string, unknown>,
  fingerprint: string,
  baselineTitle?: string,
): boolean {
  return (
    fingerprintEditableMapOptions(options) === fingerprint &&
    (baselineTitle === undefined || mapOptionsTitle(options) === baselineTitle)
  )
}

/** Sidebar rename acknowledges only title, preserving all other draft edits. */
export function rebaseMapDraftTitle(
  draft: MapWorkspaceDraft,
  title: string,
  baselineFingerprint = draft.baselineFingerprint,
): MapWorkspaceDraft | null {
  const options = { ...draft.options, title }
  if (mapOptionsMatchBaseline(options, draft.baselineOptionsFingerprint, title)) return null
  return {
    ...draft,
    options,
    baselineTitle: title,
    baselineFingerprint,
    draftFingerprint: fingerprintEditableMapOptions(options),
    conflicted: false,
    updatedAt: Date.now(),
  }
}
