export type DraftRecoveryEntry = { key: string; value: string }
export interface DraftRecoveryStore {
  read(scope: string): Promise<DraftRecoveryEntry[]>
  /** Read, compare and replace within one transaction, so another tab cannot race cleanup. */
  update(scope: string, change: (entries: Map<string, string>) => void): Promise<DraftRecoveryEntry[]>
}

/** The single local draft cache. Only transaction completion acknowledges durability. */
export class IndexedDbDraftRecoveryStore implements DraftRecoveryStore {
  constructor(private name = "mapsvg-app-draft-recovery-v1") {}
  private open(): Promise<IDBDatabase> {
    if (typeof indexedDB === "undefined") return Promise.reject(new Error("IndexedDB is unavailable"))
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.name, 1)
      request.onupgradeneeded = () => request.result.createObjectStore("copies", { keyPath: "key" })
      request.onsuccess = () => resolve(request.result)
      request.onerror = () => reject(request.error ?? new Error("Could not open local draft storage"))
      request.onblocked = () => reject(new Error("Local draft storage is blocked by another tab"))
    })
  }
  private async transaction(scope: string, change?: (entries: Map<string, string>) => void): Promise<DraftRecoveryEntry[]> {
    const database = await this.open()
    try {
      return await new Promise((resolve, reject) => {
        const transaction = database.transaction("copies", change ? "readwrite" : "readonly")
        const store = transaction.objectStore("copies")
        const request = store.getAll(IDBKeyRange.bound(`${scope}:`, `${scope}:\uffff`))
        let result: DraftRecoveryEntry[] = []
        let failure: unknown
        request.onsuccess = () => {
          try {
            const before = new Map((request.result as DraftRecoveryEntry[]).map(item => [item.key, item.value]))
            const after = new Map(before)
            change?.(after)
            if (change) {
              for (const key of before.keys()) if (!after.has(key)) store.delete(key)
              for (const [key, value] of after) {
                if (!key.startsWith(`${scope}:`)) throw new Error("Draft cache write outside its scope")
                if (before.get(key) !== value) store.put({ key, value } satisfies DraftRecoveryEntry)
              }
            }
            result = [...after].map(([key, value]) => ({ key, value }))
          } catch (error) { failure = error; transaction.abort() }
        }
        transaction.oncomplete = () => resolve(result)
        transaction.onerror = transaction.onabort = () => reject(failure ?? transaction.error ?? new Error("Local draft transaction failed"))
      })
    } finally { database.close() }
  }
  read(scope: string) { return this.transaction(scope) }
  update(scope: string, change: (entries: Map<string, string>) => void) { return this.transaction(scope, change) }
}
