import { adminRestFetch } from "@/lib/admin-rest-fetch"
import { getAdminParams } from "@/lib/admin-params"
import { adminReadContext, invalidateAdminReadFlights, singleFlightAdminRead } from "@/lib/admin-read-flight"
import { resourceApiUrl } from "@/lib/resource-api-url"
import type {
  MapWorkspaceDraft,
  PersistedWorkspacePayload,
} from "@/lib/workspace-store"

function endpoint(path = ""): { url: string; nonce: string } {
  const params = getAdminParams()
  return {
    url: resourceApiUrl(params.apiUrl, `/admin-workspace${path}`),
    nonce: params.nonce,
  }
}

function headers(nonce: string, withBody = false): HeadersInit {
  return {
    Accept: "application/json",
    ...(withBody ? { "Content-Type": "application/json" } : {}),
    "X-WP-Nonce": nonce,
  }
}

const workspaceFamily = "admin-workspace"
type StartupRead = { context: string; promise: Promise<PersistedWorkspacePayload | null> }
let startupRead: StartupRead | null = null

async function readRemoteWorkspace(url: string, nonce: string): Promise<PersistedWorkspacePayload | null> {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), 8000)
  try {
    const response = await adminRestFetch(url, {
      method: "GET", signal: controller.signal,
      headers: headers(nonce),
      credentials: "same-origin",
    })
    if (!response.ok) {
      throw new Error(`Failed to load admin workspace (${response.status})`)
    }
    const payload = (await response.json()) as {
      workspace?: PersistedWorkspacePayload | null
    }
    return payload.workspace ?? null
  } finally { clearTimeout(timer) }
}

export function fetchRemoteWorkspace(options: { metadataOnly?: boolean } = {}): Promise<PersistedWorkspacePayload | null> {
  const context = adminReadContext()
  if (startupRead && startupRead.context !== context) startupRead = null
  if (options.metadataOnly && startupRead) return startupRead.promise
  const { url, nonce } = endpoint()
  let requestUrl = url
  if (options.metadataOnly) {
    const projection = new URL(url, getAdminParams().homeUrl || undefined)
    projection.searchParams.set("projection", "startup")
    requestUrl = projection.href
  }
  return singleFlightAdminRead(workspaceFamily, requestUrl, () => readRemoteWorkspace(requestUrl, nonce))
}

/** One boot scope overlaps metadata with CSS; it never caches normal/full reads. */
export function preloadRemoteWorkspaceStartup(): void {
  const context = adminReadContext()
  if (startupRead?.context === context) return
  startupRead = null
  const promise = fetchRemoteWorkspace({ metadataOnly: true })
  startupRead = { context, promise }
  // The App's allSettled restore still receives this failure after mounting.
  void promise.catch(() => {})
}

/** Only the live restore effect calls this, after local/remote reconciliation. */
export function finishRemoteWorkspaceStartup(): void {
  startupRead = null
}

function invalidateWorkspaceReads(): void {
  startupRead = null
  invalidateAdminReadFlights(workspaceFamily)
}

/**
 * Persist lightweight workspace metadata. Dirty map snapshots are intentionally
 * excluded and use their per-map endpoint so scroll/UI changes do not resend
 * every large draft.
 */
export async function saveRemoteWorkspace(
  workspace: PersistedWorkspacePayload,
  options: { keepalive?: boolean } = {},
): Promise<void> {
  invalidateWorkspaceReads()
  try {
    const { mapDrafts: _drafts, ...metadata } = workspace
    const { url, nonce } = endpoint()
    const response = await adminRestFetch(url, {
      method: "POST",
      headers: headers(nonce, true),
      credentials: "same-origin",
      keepalive: options.keepalive,
      body: JSON.stringify({ workspace: metadata }),
    })
    if (!response.ok) {
      throw new Error(`Failed to save admin workspace (${response.status})`)
    }
  } finally { invalidateWorkspaceReads() }
}

export async function saveRemoteMapDraft(
  mapId: number,
  draft: MapWorkspaceDraft | null,
  options: { keepalive?: boolean } = {},
): Promise<void> {
  invalidateWorkspaceReads()
  try {
    const { url, nonce } = endpoint(`/drafts/${mapId}`)
    const response = await adminRestFetch(url, {
      method: draft ? "POST" : "DELETE",
      headers: headers(nonce, draft != null),
      credentials: "same-origin",
      keepalive: options.keepalive,
      body: draft ? JSON.stringify({ draft }) : undefined,
    })
    if (!response.ok) {
      throw new Error(
        `Failed to ${draft ? "save" : "clear"} map draft (${response.status})`,
      )
    }
  } finally { invalidateWorkspaceReads() }
}
