import type { CanvasView, PreviewOrientation } from "@/lib/preview-canvas"
import { create } from "zustand"
import { createJSONStorage, persist } from "zustand/middleware"

export type MapWorkspaceResource = {
  kind: "map"
  mapId: number
}

export type DatabaseTableWorkspaceResource = {
  kind: "db-table"
  schemaId: string
  tableName: string
}

export type DatabaseQueryWorkspaceResource = {
  kind: "db-query"
  queryId: string
}
export type DatabaseWorkspaceResource = DatabaseTableWorkspaceResource | DatabaseQueryWorkspaceResource
export type DatabaseTabWorkspaceResource = {
  kind: "database"
  sessionId: string
  selection: DatabaseWorkspaceResource | null
}

export type ChatWorkspaceResource = {
  kind: "chat"
  sessionId: string
  chatId: number | null
  mapId: number | null
}
export type WorkspaceResource =
  | MapWorkspaceResource
  | DatabaseTableWorkspaceResource
  | DatabaseQueryWorkspaceResource
  | DatabaseTabWorkspaceResource
  | ChatWorkspaceResource
export function workspaceMapId(resource?: WorkspaceResource | null): number | null {
  return resource?.kind === "map" || resource?.kind === "chat" ? resource.mapId : null
}
export function isDatabaseWorkspace(resource?: WorkspaceResource | null): resource is DatabaseWorkspaceResource | DatabaseTabWorkspaceResource {
  return resource?.kind === "database" || resource?.kind === "db-table" || resource?.kind === "db-query"
}
export function workspaceDatabaseSelection(resource?: WorkspaceResource | null): DatabaseWorkspaceResource | null {
  return resource?.kind === "database" ? resource.selection : isDatabaseWorkspace(resource) ? resource : null
}
function sameResource(a: WorkspaceResource, b: WorkspaceResource): boolean {
  const map = workspaceMapId(a)
  if (map && map === workspaceMapId(b)) return true
  return (
    (a.kind === "chat" && b.kind === "chat" && a.chatId != null && a.chatId === b.chatId) ||
    workspaceResourceKey(a) === workspaceResourceKey(b)
  )
}

export type WorkspaceTab = {
  id: string
  resource: WorkspaceResource
  title: string
}

export type AdminUiTheme = "default" | "compact"

export type MapWorkspaceSession = {
  /** Editor selection only; persisted default is owned by options.stateGraph. */
  activeStateId?: string
  /** Page context for the component tree; editor-only, never a runtime option. */
  activePageId?: string
  settingsTab?: string
  previewMode?: "layout" | "preview"
  previewDevice?: "desktop" | "tablet" | "mobile"
  previewCanvas?: CanvasView
  layoutCanvas?: CanvasView
  previewOrientations?: Partial<Record<"tablet" | "mobile", PreviewOrientation>>
  selectedNodeId?: string | null
  selectedSceneId?: string | null
  /** Map-wide settings selection, separate from persisted runtime nodes/scenes. */
  selectedComponentId?: string | null
  /** App Gallery resource selection; never a Layout node or a runtime option. */
  selectedGalleryId?: string | null
  componentMode?:
    | "settings"
    | "fields"
    | "interactions"
    | "styles"
    | "code"
    | "template"
    | "css"
    | "js"
  componentCodeDocument?: string
  componentTemplateKey?: string
  componentScriptKey?: string
  sceneDetailsMode?: "settings" | "data"
  dataSelection?:
    | { kind: "source"; schemaId: string }
    | { kind: "query"; schemaId: string; queryId: "getObjects" | "getRegions" }
    | { kind: "savedQuery"; schemaId: string; savedQueryId: string }
  dataQueryViewMode?: "data" | "edit"
  dataSourceViewMode?: "rows" | "fields"
  dataSelectedRowId?: string | number | null
  scrollPositions?: Record<string, number>
  updatedAt?: number
}

export type MapWorkspaceDraft = {
  options: Record<string, unknown>
  /** Raw saved server options fingerprint used only for stale-draft detection. */
  baselineFingerprint: string
  /** Normalized MapSVG getData().options fingerprint used for dirty detection. */
  baselineOptionsFingerprint: string
  /** Saved title, tracked separately to preserve the legacy fingerprint format. */
  baselineTitle?: string
  draftFingerprint: string
  updatedAt: number
  conflicted?: boolean
}

type WorkspaceState = {
  tabs: WorkspaceTab[]
  activeTabId: string | null
  mapSessions: Record<string, MapWorkspaceSession>
  mapDrafts: Record<string, MapWorkspaceDraft>
  mapBaselines: Record<string, string>
  mapServerBaselines: Record<string, string>
  mapTitleBaselines: Record<string, string>
  uiTheme: AdminUiTheme
  updatedAt: number

  setUiTheme: (theme: AdminUiTheme) => void
  openResource: (resource: WorkspaceResource, title: string) => string
  activateTab: (id: string | null) => void
  attachMapTab: (id: string, mapId: number, title: string) => void
  updateChatTab: (id: string, chat: { id: number; mapId: number | null; title: string }) => void
  updateDatabaseTab: (id: string, selection: DatabaseWorkspaceResource | null, title: string) => void
  closeTab: (id: string) => void
  closeResource: (resource: WorkspaceResource) => void
  renameResource: (resource: WorkspaceResource, title: string) => void

  patchMapSession: (mapId: number, patch: Partial<MapWorkspaceSession>) => void
  setMapScroll: (mapId: number, key: string, scrollTop: number) => void

  setMapBaseline: (mapId: number, fingerprint: string) => void
  setMapServerBaseline: (mapId: number, fingerprint: string) => void
  setMapTitleBaseline: (mapId: number, title: string) => void
  setMapDraft: (mapId: number, draft: MapWorkspaceDraft) => void
  clearMapDraft: (mapId: number) => void
  setMapDraftConflict: (mapId: number, conflicted: boolean) => void
  clearMapWorkspaceState: (mapId: number) => void

  hydrateLocalDrafts: (drafts: Record<string, MapWorkspaceDraft>) => void
  hydrateRemote: (payload: PersistedWorkspacePayload) => void
}

export type PersistedWorkspacePayload = {
  tabs: WorkspaceTab[]
  activeTabId: string | null
  mapSessions: Record<string, MapWorkspaceSession>
  mapDrafts: Record<string, MapWorkspaceDraft>
  uiTheme?: AdminUiTheme
  updatedAt: number
}

export function workspaceResourceKey(resource: WorkspaceResource): string {
  if (resource.kind === "map") return `map:${resource.mapId}`
  if (resource.kind === "chat") return `chat:${resource.sessionId}`
  if (resource.kind === "database") return `database:${resource.sessionId}`
  if (resource.kind === "db-query") return `db-query:${resource.queryId}`
  return `db-table:${resource.schemaId}`
}

function storageKey(): string {
  if (typeof window === "undefined") return "mapsvg-react-workspace-v2:ssr"
  const userId = window.mapsvgReactAdminParams?.user?.id
  const site = window.mapsvgReactAdminParams?.homeUrl ?? window.location.origin
  return `mapsvg-react-workspace-v2:${encodeURIComponent(site)}:${userId ?? "anonymous"}`
}

function now(): number {
  return Date.now()
}

function persistedPayload(state: WorkspaceState): PersistedWorkspacePayload {
  return {
    tabs: state.tabs,
    activeTabId: state.activeTabId,
    mapSessions: state.mapSessions,
    mapDrafts: state.mapDrafts,
    uiTheme: state.uiTheme,
    updatedAt: state.updatedAt,
  }
}

export function getPersistedWorkspacePayload(): PersistedWorkspacePayload {
  return persistedPayload(useWorkspaceStore.getState())
}

export const useWorkspaceStore = create<WorkspaceState>()(
  persist(
    (set, get) => ({
      tabs: [],
      activeTabId: null,
      mapSessions: {},
      mapDrafts: {},
      mapBaselines: {},
      mapServerBaselines: {},
      mapTitleBaselines: {},
      uiTheme: "compact",
      updatedAt: 0,

      setUiTheme: (uiTheme) => {
        set({ uiTheme, updatedAt: now() })
      },

      openResource: (resource, title) => {
        const id = workspaceResourceKey(resource)
        const existing = get().tabs.find((tab) => sameResource(tab.resource, resource))
        if (existing) {
          set({ activeTabId: existing.id, updatedAt: now() })
          return existing.id
        }
        set((state) => ({
          tabs: [...state.tabs, { id, resource, title }],
          activeTabId: id,
          updatedAt: now(),
        }))
        return id
      },

      activateTab: (id) => {
        if (id === null || get().tabs.some((tab) => tab.id === id)) {
          set({ activeTabId: id, updatedAt: now() })
        }
      },

      updateDatabaseTab: (id, selection, title) => {
        set(state => ({
          tabs: state.tabs.map(tab => tab.id === id && isDatabaseWorkspace(tab.resource)
            ? { ...tab, title, resource: { kind: "database" as const, sessionId: tab.resource.kind === "database" ? tab.resource.sessionId : crypto.randomUUID(), selection } }
            : tab),
          updatedAt: now(),
        }))
      },

      attachMapTab: (id, mapId, title) =>
        set((state) => ({
          tabs: state.tabs.map((t) =>
            t.id === id ? { ...t, title, resource: { kind: "map" as const, mapId } } : t,
          ),
          updatedAt: now(),
        })),
      updateChatTab: (id, chat) => {
        set((state) => {
          const target =
            state.tabs.find((t) => t.id === id && t.resource.kind === "chat") ??
            state.tabs.find((t) => t.resource.kind === "chat" && t.resource.chatId === chat.id)
          if (!target || target.resource.kind !== "chat") return state
          const resource = target.resource
          const duplicate = state.tabs.filter(
            (t) =>
              t.id !== target.id &&
              ((chat.mapId && workspaceMapId(t.resource) === chat.mapId) ||
                (t.resource.kind === "chat" && t.resource.chatId === chat.id)),
          )
          const tabs = state.tabs
            .filter((t) => !duplicate.includes(t))
            .map((t) =>
              t.id === target.id
                ? {
                    ...t,
                    title: chat.title,
                    resource: {
                      ...resource,
                      kind: "chat" as const,
                      chatId: chat.id,
                      mapId: chat.mapId,
                    },
                  }
                : t,
            )
          if (JSON.stringify(tabs) === JSON.stringify(state.tabs)) return state
          return {
            tabs,
            activeTabId: duplicate.some((t) => t.id === state.activeTabId)
              ? target.id
              : state.activeTabId,
            updatedAt: now(),
          }
        })
      },
      closeTab: (id) => {
        set((state) => {
          const index = state.tabs.findIndex((tab) => tab.id === id)
          if (index < 0) return state
          const tabs = state.tabs.filter((tab) => tab.id !== id)
          if (state.activeTabId !== id) return { tabs, updatedAt: now() }
          const neighbor = tabs[Math.min(index, tabs.length - 1)] ?? null
          return { tabs, activeTabId: neighbor?.id ?? null, updatedAt: now() }
        })
      },

      closeResource: (resource) => {
        for (const tab of get().tabs.filter((t) => sameResource(t.resource, resource)))
          get().closeTab(tab.id)
      },

      renameResource: (resource, title) => {
        set((state) => ({
          tabs: state.tabs.map((tab) =>
            sameResource(tab.resource, resource) ? { ...tab, title } : tab,
          ),
          updatedAt: now(),
        }))
      },

      patchMapSession: (mapId, patch) => {
        const key = String(mapId)
        set((state) => ({
          mapSessions: {
            ...state.mapSessions,
            [key]: {
              ...state.mapSessions[key],
              ...patch,
              updatedAt: now(),
            },
          },
          updatedAt: now(),
        }))
      },

      setMapScroll: (mapId, key, scrollTop) => {
        const id = String(mapId)
        set((state) => {
          const current = state.mapSessions[id] ?? {}
          return {
            mapSessions: {
              ...state.mapSessions,
              [id]: {
                ...current,
                scrollPositions: {
                  ...(current.scrollPositions ?? {}),
                  [key]: scrollTop,
                },
                updatedAt: now(),
              },
            },
            updatedAt: now(),
          }
        })
      },

      setMapBaseline: (mapId, fingerprint) => {
        set((state) => ({
          mapBaselines: { ...state.mapBaselines, [String(mapId)]: fingerprint },
        }))
      },

      setMapServerBaseline: (mapId, fingerprint) => {
        set((state) => ({
          mapServerBaselines: {
            ...state.mapServerBaselines,
            [String(mapId)]: fingerprint,
          },
        }))
      },

      setMapTitleBaseline: (mapId, title) => {
        set((state) => ({
          mapTitleBaselines: { ...state.mapTitleBaselines, [String(mapId)]: title },
        }))
      },

      setMapDraft: (mapId, draft) => {
        set((state) => ({
          mapDrafts: { ...state.mapDrafts, [String(mapId)]: draft },
          updatedAt: now(),
        }))
      },

      clearMapDraft: (mapId) => {
        const key = String(mapId)
        set((state) => {
          if (!state.mapDrafts[key]) return state
          const next = { ...state.mapDrafts }
          delete next[key]
          return { mapDrafts: next, updatedAt: now() }
        })
      },

      setMapDraftConflict: (mapId, conflicted) => {
        const key = String(mapId)
        set((state) => {
          const draft = state.mapDrafts[key]
          if (!draft || Boolean(draft.conflicted) === conflicted) return state
          return {
            mapDrafts: {
              ...state.mapDrafts,
              [key]: { ...draft, conflicted },
            },
            updatedAt: now(),
          }
        })
      },

      clearMapWorkspaceState: (mapId) => {
        const key = String(mapId)
        set((state) => {
          const mapSessions = { ...state.mapSessions }
          const mapDrafts = { ...state.mapDrafts }
          const mapBaselines = { ...state.mapBaselines }
          const mapServerBaselines = { ...state.mapServerBaselines }
          const mapTitleBaselines = { ...state.mapTitleBaselines }
          delete mapSessions[key]
          delete mapDrafts[key]
          delete mapBaselines[key]
          delete mapServerBaselines[key]
          delete mapTitleBaselines[key]
          return {
            mapSessions,
            mapDrafts,
            mapBaselines,
            mapServerBaselines,
            mapTitleBaselines,
            updatedAt: now(),
          }
        })
      },

      hydrateLocalDrafts: (drafts) => {
        set((state) => {
          const mapDrafts = { ...state.mapDrafts }
          let newest = state.updatedAt
          for (const [mapId, draft] of Object.entries(drafts)) {
            const current = mapDrafts[mapId]
            if (!current || draft.updatedAt > current.updatedAt) {
              mapDrafts[mapId] = draft
            }
            newest = Math.max(newest, draft.updatedAt)
          }
          return { mapDrafts, updatedAt: newest }
        })
      },

      hydrateRemote: (payload) => {
        if (!payload) return
        const current = get()

        const remoteDrafts = payload.mapDrafts ?? {}
        const mapDrafts = { ...current.mapDrafts }
        let draftsChanged = false
        for (const [mapId, draft] of Object.entries(remoteDrafts)) {
          const local = current.mapDrafts[mapId]
          if (!local || draft.updatedAt > local.updatedAt) {
            mapDrafts[mapId] = draft
            draftsChanged = true
          }
        }

        if (payload.updatedAt > current.updatedAt) {
          set({
            tabs: Array.isArray(payload.tabs) ? payload.tabs : [],
            activeTabId: payload.activeTabId ?? null,
            mapSessions: payload.mapSessions ?? {},
            mapDrafts,
            uiTheme:
              payload.uiTheme === "default" || payload.uiTheme === "compact"
                ? payload.uiTheme
                : current.uiTheme,
            updatedAt: payload.updatedAt,
          })
          return
        }

        if (draftsChanged) set({ mapDrafts })
      },
    }),
    {
      name: storageKey(),
      storage: createJSONStorage(() => localStorage),
      // Keep localStorage lightweight. Full map drafts live in IndexedDB
      // and on the per-user server endpoint.
      partialize: (state) => ({
        ...persistedPayload(state),
        mapDrafts: {},
      }),
      version: 3,
    },
  ),
)
