/**
 * Tailwind v4 + Shadow DOM:
 * - `@property` is not supported inside shadow roots — hoist to document.head
 * - theme tokens on `:root` don't apply in shadow — rewrite to `:host`
 * - `@layer properties` fallbacks are gated by `@supports` that assumes `@property`
 *   works; unwrap so `--tw-*` defaults apply inside the shadow tree
 *
 * @see https://github.com/tailwindlabs/tailwindcss/issues/15005
 */

const PROPERTY_STYLE_ID = "mapsvg-admin-react-css-properties"
const PROPERTY_RE = /@property\s+[^{]+\{[^}]*\}/g

export function injectTailwindIntoShadow(shadow: ShadowRoot, css: string, source = "app"): HTMLStyleElement {
  const propertyRules: string[] = []
  let shadowCss = css.replace(PROPERTY_RE, (match) => {
    propertyRules.push(match)
    return ""
  })

  // Prefer :host so CSS variables inherit into the shadow tree.
  shadowCss = shadowCss.replace(/:root\b/g, ":host")
  shadowCss = unwrapPropertiesSupports(shadowCss)

  if (propertyRules.length > 0 && !document.getElementById(PROPERTY_STYLE_ID)) {
    const propStyle = document.createElement("style")
    propStyle.id = PROPERTY_STYLE_ID
    propStyle.textContent = propertyRules.join("\n")
    document.head.appendChild(propStyle)
  }

  const style = document.createElement("style")
  style.setAttribute("data-mapsvg-admin-react", source)
  style.textContent = shadowCss
  shadow.appendChild(style)
  return style
}

/**
 * Turn `@layer properties { @supports (...) { RULES } }` into
 * `@layer properties { RULES }` so Tailwind utility defaults work in shadow DOM.
 */
function unwrapPropertiesSupports(css: string): string {
  const layerPrefix = "@layer properties{"
  const i = css.indexOf(layerPrefix)
  if (i < 0) return css

  const supportsStart = i + layerPrefix.length
  if (!css.startsWith("@supports", supportsStart)) return css

  let brace = supportsStart + "@supports".length
  while (brace < css.length && css[brace] !== "{") brace++
  if (css[brace] !== "{") return css

  let depth = 0
  let supportsEnd = -1
  for (let p = brace; p < css.length; p++) {
    const ch = css[p]
    if (ch === "{") depth++
    else if (ch === "}") {
      depth--
      if (depth === 0) {
        supportsEnd = p
        break
      }
    }
  }
  if (supportsEnd < 0) return css

  const rules = css.slice(brace + 1, supportsEnd)
  let layerEnd = supportsEnd + 1
  while (layerEnd < css.length && /\s/.test(css[layerEnd])) layerEnd++
  if (css[layerEnd] !== "}") return css

  return css.slice(0, i) + layerPrefix + rules + "}" + css.slice(layerEnd + 1)
}

/**
 * Mirror Vite's dev <style data-vite-dev-id> tags into the MapSVG shadow root.
 * Vite owns the source tags and updates them during CSS HMR; we keep shadow
 * copies in sync because document.head styles do not cross the shadow boundary.
 */
export function mirrorViteDevStylesIntoShadow(shadow: ShadowRoot): () => void {
  const mirroredSources = new Map<string, { text: string; style: HTMLStyleElement }>()
  const mirror = () => {
    const sourceStyles = Array.from(
      document.head.querySelectorAll<HTMLStyleElement>("style[data-vite-dev-id]"),
    )
    const activeIds = new Set<string>()

    for (const sourceStyle of sourceStyles) {
      const id = sourceStyle.getAttribute("data-vite-dev-id")
      if (!id) continue
      activeIds.add(id)

      const source = "vite:" + id
      const text = sourceStyle.textContent ?? ""
      const previous = mirroredSources.get(id)
      if (previous?.text === text && previous.style.parentNode === shadow) continue
      const existing = shadow.querySelector<HTMLStyleElement>(
        'style[data-mapsvg-admin-react="' + CSS.escape(source) + '"]',
      )
      const style = injectTailwindIntoShadow(shadow, text, source)
      // Updating one source must retain its place in the stylesheet cascade.
      existing?.replaceWith(style)
      mirroredSources.set(id, { text, style })
    }

    for (const mirrored of shadow.querySelectorAll<HTMLStyleElement>(
      'style[data-mapsvg-admin-react^="vite:"]',
    )) {
      const source = mirrored.getAttribute("data-mapsvg-admin-react") ?? ""
      const id = source.slice("vite:".length)
      if (!activeIds.has(id)) {
        mirrored.remove()
        mirroredSources.delete(id)
      }
    }
  }

  mirror()

  const observer = new MutationObserver(() => mirror())
  observer.observe(document.head, {
    childList: true,
    subtree: true,
    characterData: true,
  })

  return () => observer.disconnect()
}

export async function loadCssText(cssUrl: string): Promise<string> {
  const res = await fetch(cssUrl, { credentials: "same-origin" })
  if (!res.ok) {
    throw new Error(`Failed to load CSS (${res.status}): ${cssUrl}`)
  }
  return res.text()
}
