import type { MapsvgMapInstance } from "./mapsvg-client"

/** Named Page Queries resolve their Collection at runtime; legacy bindings can be stale. */
export function boundRuntimeCollections(map: MapsvgMapInstance): string[] {
  type Repository = { getSchema?: () => { name?: string } }
  const runtime = map as MapsvgMapInstance & { objectsRepository?: Repository; regionsRepository?: Repository }
  const legacy = (map.options.database as { schemas?: Record<string, { name?: string }> } | undefined)?.schemas
  return [...new Set((["objects", "regions"] as const).flatMap(role => {
    const repository = role === "objects" ? runtime.objectsRepository : runtime.regionsRepository
    const name = repository?.getSchema?.()?.name || legacy?.[role]?.name
    return typeof name === "string" && name ? [name] : []
  }))]
}
