import { IndexedDbDraftRecoveryStore, type DraftRecoveryStore } from "./app-draft-recovery"
import { AdminSessionError, adminRestFetch } from "@/lib/admin-rest-fetch"
import { canEditJavaScript, retainReadOnlyJavaScript } from "./app-code-permissions"
import { getAdminParams } from "@/lib/admin-params"
import { resourceApiUrl } from "@/lib/resource-api-url"

export type AppSnapshot = { id: number; options: Record<string, unknown>; [key: string]: unknown }
export type AppDraft = {
  id: number; map_id: number; title: string; snapshot: AppSnapshot; revision: number
  migration?: boolean; source_version_id: number | null; author_id: number; created_at: string; updated_at: string
}
export type AppVersion = Omit<AppDraft, "revision" | "updated_at" | "snapshot"> & {
  engine?: 8 | 9; old_editor_url?: string; draft_id: number | null; kind: string; published_at: string | null
}
export type DraftIndex = { drafts: AppDraft[]; versions: AppVersion[]; published_version_id: number | null }
export type DraftWorkingCopy = {
  draft: AppDraft; confirmed: AppSnapshot; snapshot: AppSnapshot; revision: number
  dirty: boolean; localSaved: boolean; localError?: string; serverError?: string; conflicted: boolean
}
type LocalCopy = { draft?: Omit<AppDraft, "snapshot" | "revision">; snapshot: AppSnapshot; revision: number; confirmed: AppSnapshot; writer: string; updatedAt?: number; sequence?: number; conflicted?: boolean }
// Clean cache records store one snapshot. Dirty records additionally retain their server baseline.
function readLocal(raw: string): LocalCopy {
  const local = JSON.parse(raw) as LocalCopy & { synced?: boolean }
  if (local.synced === true && !local.confirmed) local.confirmed = local.snapshot
  return local
}
function writeLocal(local: LocalCopy): string {
  if (!equal(local.snapshot, local.confirmed)) return JSON.stringify(local)
  const { confirmed: _confirmed, ...rest } = local
  return JSON.stringify({ ...rest, synced: true })
}
type Request = <T>(path: string, method?: string, body?: unknown, signal?: AbortSignal) => Promise<T>
export class DraftHttpError extends Error {
  constructor(message: string, public status: number) { super(message) }
}

export async function draftRequest<T>(path: string, method = "GET", body?: unknown, signal?: AbortSignal): Promise<T> {
  const params = getAdminParams()
  const controller = new AbortController()
  const abort = () => controller.abort()
  if (signal?.aborted) controller.abort()
  signal?.addEventListener("abort", abort, { once: true })
  const timer = setTimeout(abort, 15000)
  try {
    const response = await adminRestFetch(resourceApiUrl(params.apiUrl, path), {
      method, signal: controller.signal, credentials: "same-origin", cache: "no-store",
      headers: { Accept: "application/json", "X-WP-Nonce": params.nonce, ...(body === undefined ? {} : { "Content-Type": "application/json" }) },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    })
    const data = await response.json().catch(() => null)
    controller.signal.throwIfAborted()
    if (!response.ok || !data) throw new DraftHttpError(data?.message ?? `Draft operation failed (${response.status}).`, response.status)
    return data as T
  } finally { clearTimeout(timer); signal?.removeEventListener("abort", abort) }
}

function unavailable(error: unknown): boolean {
  if (error instanceof AdminSessionError) return false
  const status = error && typeof error === "object" && "status" in error ? Number(error.status) : null
  return status === null || status >= 500 || status === 408 || status === 429
}
function draftMetadata(draft: AppDraft): Omit<AppDraft, "snapshot" | "revision"> {
  const { snapshot: _snapshot, revision: _revision, ...metadata } = draft
  return metadata
}
function clone<T>(value: T): T { return JSON.parse(JSON.stringify(value)) as T }
function stable(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stable).join(",")}]`
  if (value && typeof value === "object") return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${stable((value as Record<string, unknown>)[key])}`).join(",")}}`
  return JSON.stringify(value) ?? "null"
}
export function authoringSnapshot(record: AppSnapshot): AppSnapshot {
  const snapshot = clone(record)
  delete snapshot.options.useShadowRoot
  snapshot.title = snapshot.options.title ?? snapshot.title ?? ""
  snapshot.svgFilePath = snapshot.options.source ?? ""
  return snapshot
}
// Runtime metadata can change when the SVG is reloaded. Authoring dirty ownership is options.
function equal(a: AppSnapshot, b: AppSnapshot): boolean { return stable(a.options) === stable(b.options) }

/** Per-App owner; each draft keeps its independent working and acknowledged snapshots. */
export class AppDraftSession {
  copies = new Map<number, DraftWorkingCopy>()
  activeId: number | null = null
  recoveries: Array<{ key: string; title: string; snapshot: AppSnapshot }> = []
  versions: AppVersion[] = []
  publishedVersionId: number | null = null
  ready = false
  error: string | null = null
  offline = false
  connectionError: string | null = null
  busy = false
  transitioning = false
  setTransitioning(value: boolean): void { this.transitioning = value; this.emit() }
  private listeners = new Set<() => void>()
  private pending: Promise<unknown> | null = null
  private initializing: Promise<void> | null = null
  private reconnecting: Promise<void> | null = null
  private versionMetadataGeneration = 0
  private writer = crypto.randomUUID()
  private scope: string
  private api: Request
  private storage: () => Storage
  private recoveryCache = new Map<string, string>()
  private localPending: Promise<void> = Promise.resolve()
  private localGeneration = new Map<number, number>()
  private localSlots = new Map<number, { key: string; raw: string }>()
  private serverDraftIds = new Set<number>()
  private channel?: BroadcastChannel
  private disposed = false

  constructor(public mapId: number, api: Request = draftRequest, storage: () => Storage = () => window.localStorage, scope?: string, private recoveryStore: DraftRecoveryStore = new IndexedDbDraftRecoveryStore()) {
    const params = getAdminParams()
    this.scope = scope ?? `mapsvg-app-drafts-v3:${encodeURIComponent(params.homeUrl)}:${params.user.id}:${mapId}`
    this.api = api
    this.storage = storage
  }
  subscribe = (listener: () => void) => { this.listeners.add(listener); return () => { this.listeners.delete(listener) } }
  private emit() { for (const listener of this.listeners) listener() }
  get active(): DraftWorkingCopy | undefined { return this.activeId == null ? undefined : this.copies.get(this.activeId) }
  key(id: number) { return `${this.scope}:${id}` }
  private path(id?: number, action = "") { return `/apps/${this.mapId}/drafts${id === undefined ? "" : `/${id}`}${action}` }

  /** Await transaction acknowledgments (also useful before switching an owned test page). */
  async waitForLocalPersistence(): Promise<void> { await this.localPending }

  /** A Paid code reload may proceed offline only after all working copies are durable. */
  async prepareForReload(): Promise<void> {
    if (!this.ready) return
    await this.autosave()
    this.cacheSelection()
    await this.waitForLocalPersistence()
    if ([...this.copies.values()].some(copy => !copy.localSaved) ||
      (this.activeId != null && this.recoveryCache.get(`${this.scope}:active`) !== String(this.activeId)))
      throw new Error("Your App draft could not be saved locally. Keep the editor open and retry before reloading.")
  }

  private localEntries(): Map<string, string> { return new Map(this.recoveryCache) }

  private queueLocal(operation: () => Promise<void>): void {
    this.localPending = this.localPending.catch(() => {}).then(operation).catch(error => {
      this.error = `Local cache failed: ${String(error)}`
      this.emit()
    })
  }

  private async updateCache(change: (entries: Map<string, string>) => void): Promise<void> {
    const entries = await this.recoveryStore.update(this.scope, change)
    this.recoveryCache = new Map(entries.map(item => [item.key, item.value]))
  }

  /** Legacy storage is read only during migration. Never delete a source before the IDB commit. */
  private async migrateLocalStorage(): Promise<void> {
    const legacy = new Map<string, string>()
    let storage: Storage
    try {
      storage = this.storage()
      for (let index = 0; index < storage.length; index++) {
        const key = storage.key(index)
        if (key?.startsWith(`${this.scope}:`)) {
          const raw = storage.getItem(key)
          if (raw !== null) legacy.set(key, raw)
        }
      }
    } catch { return } // A disabled legacy store does not prevent IndexedDB use.
    if (!legacy.size) return
    // Keep readable legacy data available in memory even if migration cannot commit.
    for (const [key, raw] of legacy) if (!this.recoveryCache.has(key)) this.recoveryCache.set(key, raw)
    await this.updateCache(entries => {
      for (const [key, raw] of legacy) {
        const existing = entries.get(key)
        if (existing === undefined) entries.set(key, raw)
        else if (existing !== raw && key !== `${this.scope}:active`) {
          try {
            const old = readLocal(raw), current = readLocal(existing)
            if (old.writer && old.writer === current.writer && Number.isInteger(old.sequence) && Number.isInteger(current.sequence)) {
              if (old.sequence! > current.sequence!) entries.set(key, raw)
              if (old.sequence !== current.sequence) continue
            }
          } catch { /* preserve opaque or divergent records */ }
          if (![...entries.values()].includes(raw)) entries.set(`${key}:legacy:${crypto.randomUUID()}`, raw)
        }
      }
    })
    for (const [key, raw] of legacy) {
      try { if (storage.getItem(key) === raw) storage.removeItem(key) } catch { /* retry migration on next opening */ }
    }
  }

  private draftId(key: string): number { return Number(key.slice(this.scope.length + 1).split(":")[0]) }

  /** Keep one clean cache record per existing draft; never expire unique unsynced work. */
  private collectGarbage(entries: Map<string, string>, confirmed?: { id: number; snapshot: AppSnapshot }): void {
    const seen = new Set<string>()
    const latest = new Map<string, number>()
    for (const [key, raw] of entries) {
      try {
        const local = readLocal(raw)
        if (local.writer && Number.isInteger(local.sequence) && local.snapshot?.options && local.confirmed?.options) {
          const owner = `${this.draftId(key)}:${local.writer}`
          latest.set(owner, Math.max(latest.get(owner) ?? -1, local.sequence!))
        }
      } catch { /* opaque payloads are not candidates for supersession */ }
    }
    // Prefer the canonical record when collapsing identical variants.
    const sorted = [...entries].sort(([a], [b]) => Number(b === this.key(this.draftId(b))) - Number(a === this.key(this.draftId(a))))
    for (const [key, raw] of sorted) {
      try {
        const local = readLocal(raw), id = this.draftId(key)
        if (!id || !local.snapshot?.options || !local.confirmed?.options) continue
        if (Number.isInteger(local.sequence) && local.sequence! < (latest.get(`${id}:${local.writer}`) ?? -1)) { entries.delete(key); continue }
        const clean = !local.conflicted && equal(local.snapshot, local.confirmed)
        const acknowledged = confirmed?.id === id && equal(local.snapshot, confirmed.snapshot)
        if ((clean && key !== this.key(id) && this.serverDraftIds.has(id)) || (acknowledged && !(clean && key === this.key(id)))) {
          entries.delete(key); continue
        }
        const identity = `${id}:${stable(local.snapshot.options)}:${stable(local.confirmed.options)}:${local.revision}:${Boolean(local.conflicted)}`
        if (seen.has(identity)) entries.delete(key)
        else seen.add(identity)
      } catch { /* unreadable recovery data is never garbage */ }
    }
    // SVG responses are disposable only when no retained snapshot/baseline references their source.
    const sources = new Set<string>()
    let opaqueDraft = false
    for (const [key, raw] of entries) {
      if (!this.draftId(key)) continue
      try {
        const local = readLocal(raw)
        if (!local.snapshot?.options || !local.confirmed?.options) { opaqueDraft = true; continue }
        for (const snapshot of [local.snapshot, local.confirmed]) if (typeof snapshot.options.source === "string") sources.add(snapshot.options.source)
      } catch { opaqueDraft = true }
    }
    if (!opaqueDraft) for (const key of entries.keys()) {
      if (!key.startsWith(`${this.scope}:svg:`)) continue
      try { if (!sources.has(decodeURIComponent(key.slice(`${this.scope}:svg:`.length)))) entries.delete(key) } catch { /* preserve malformed legacy asset keys */ }
    }

  }

  private cacheSelection(): void {
    const value = String(this.activeId ?? "")
    this.queueLocal(() => this.updateCache(entries => { if (value) entries.set(`${this.scope}:active`, value); else entries.delete(`${this.scope}:active`) }))
  }

  private persist(copy: DraftWorkingCopy) {
    const id = copy.draft.id
    const generation = (this.localGeneration.get(id) ?? 0) + 1
    this.localGeneration.set(id, generation)
    const payload: LocalCopy = { draft: draftMetadata(copy.draft), snapshot: clone(copy.snapshot), confirmed: clone(copy.confirmed), revision: copy.revision, writer: this.writer, updatedAt: Date.now(), sequence: generation, conflicted: copy.conflicted }
    let text = writeLocal(payload)
    const clean = !copy.dirty && !copy.conflicted
    copy.localSaved = clean // Server acknowledgment itself already makes a clean copy durable.
    copy.localError = undefined
    this.queueLocal(async () => {
      try {
        let slot!: { key: string; raw: string }
        let raced = false
        await this.updateCache(entries => {
          const previous = this.localSlots.get(id)
          const canonical = this.key(id)
          let key = previous?.key ?? canonical
          const current = entries.get(key)
          if (clean) {
            // Explicit restore/undo supersedes this copy, but cannot erase a newer foreign write.
            if (previous && current === previous.raw) entries.delete(key)
            this.collectGarbage(entries, { id, snapshot: payload.confirmed })
            const shared = entries.get(canonical)
            if (shared === undefined || this.isClean(shared)) entries.set(canonical, text)
            slot = { key: canonical, raw: text }
          } else {
            if (current !== undefined && current !== previous?.raw) {
              // Another tab owns a divergent update. Fork only then, never on routine edits/reloads.
              key = `${canonical}:recovery:${this.writer}`
              if (entries.has(key) && entries.get(key) !== previous?.raw) key += `:${crypto.randomUUID()}`
              raced = true
              payload.conflicted = true
              text = writeLocal(payload)
            }
            entries.set(key, text)
            slot = { key, raw: text }
            this.collectGarbage(entries)
          }
        })
        this.localSlots.set(id, slot)
        if (this.localGeneration.get(id) !== generation || this.copies.get(id) !== copy) return
        copy.localSaved = true; copy.localError = undefined
        if (raced) {
          copy.conflicted = true
          copy.serverError = "Another tab changed this draft. Your copy is retained; recover it as a new draft."
        }
        if (!payload.conflicted && !this.disposed) {
          try { this.channel?.postMessage({ key: this.key(id), newValue: text }) } catch { /* server CAS still protects tabs without notifications */ }
        }
        this.emit()
      } catch (error) {
        if (this.localGeneration.get(id) === generation && this.copies.get(id) === copy && !clean) {
          copy.localSaved = false; copy.localError = `Local save failed: ${String(error)}`; this.emit()
        }
      }
    })
  }

  private isClean(raw: string): boolean {
    try { const local = readLocal(raw); return Boolean(!local.conflicted && local.snapshot?.options && local.confirmed?.options && equal(local.snapshot, local.confirmed)) } catch { return false }
  }

  dispose(): void { this.disposed = true; this.channel?.close(); this.channel = undefined }

  private adopt(draft: AppDraft): DraftWorkingCopy {
    const snapshot = authoringSnapshot(draft.snapshot)
    const copy: DraftWorkingCopy = { draft, confirmed: snapshot, snapshot, revision: draft.revision, dirty: false, localSaved: true, conflicted: false }
    let candidates: Array<{ key: string; local: LocalCopy }> = []
    try {
      for (const [key, raw] of this.localEntries()) {
        if (this.draftId(key) !== draft.id) continue
        try {
          const local = readLocal(raw)
          if (!local.snapshot?.options || !local.confirmed?.options || !Number.isInteger(local.revision)) throw new Error("Invalid local draft copy")
          if ((local.conflicted || !equal(local.snapshot, local.confirmed)) && (this.offline || !equal(local.snapshot, snapshot))) candidates.push({ key, local })
        } catch (error) { copy.localError = `Local recovery failed: ${String(error)}` }
      }
      candidates.sort((a, b) => {
        if (a.local.writer === b.local.writer && a.local.sequence !== b.local.sequence) return (b.local.sequence ?? 0) - (a.local.sequence ?? 0)
        return (b.local.updatedAt ?? 0) - (a.local.updatedAt ?? 0) || Number(b.key === this.key(draft.id)) - Number(a.key === this.key(draft.id))
      })
      const selected = candidates.find(item => !item.local.conflicted) ?? candidates[0]
      if (selected) {
        this.localSlots.set(draft.id, { key: selected.key, raw: this.recoveryCache.get(selected.key)! })
        copy.snapshot = authoringSnapshot(selected.local.snapshot)
        copy.dirty = !equal(copy.snapshot, snapshot)
        copy.conflicted = Boolean(selected.local.conflicted) || (copy.dirty && !equal(authoringSnapshot(selected.local.confirmed), snapshot))
        if (copy.conflicted) copy.serverError = "The server has a newer version of this draft. Your local copy is retained."
      }
      if (!selected) {
        const raw = this.recoveryCache.get(this.key(draft.id))
        if (raw !== undefined) this.localSlots.set(draft.id, { key: this.key(draft.id), raw })
      }
      for (const item of candidates) {
        if (!equal(item.local.snapshot, copy.snapshot) && !this.recoveries.some(other => equal(other.snapshot, item.local.snapshot))) {
          this.recoveries.push({ key: item.key, title: `${draft.title} · recovered tab`, snapshot: item.local.snapshot })
        }
      }
    } catch (error) { copy.localError = `Local recovery failed: ${String(error)}` }
    this.copies.set(draft.id, copy)
    this.serverDraftIds.add(draft.id)
    // Adoption itself never creates a new writer or duplicates a recovered snapshot.
    return copy
  }

  private markUnavailable(error: unknown): void {
    this.offline = true
    this.connectionError = error instanceof Error ? error.message : String(error)
    this.emit()
  }

  private async readIndex(): Promise<DraftIndex> {
    const controller = new AbortController()
    let timer: ReturnType<typeof setTimeout> | undefined
    const timeout = new Promise<never>((_, reject) => {
      timer = setTimeout(() => { controller.abort(); reject(new DraftHttpError("Draft server did not respond in time.", 408)) }, 8000)
    })
    try { return await Promise.race([this.api<DraftIndex>(this.path(), "GET", undefined, controller.signal), timeout]) }
    finally { clearTimeout(timer) }
  }

  private cachedDrafts(): AppDraft[] {
    const drafts = new Map<number, AppDraft>()
    for (const [key, raw] of this.recoveryCache) {
      const id = this.draftId(key)
      if (!Number.isSafeInteger(id) || id <= 0) continue
      try {
        const local = readLocal(raw)
        if (local.snapshot?.id !== this.mapId || !local.snapshot.options || local.confirmed?.id !== this.mapId || !local.confirmed.options || !Number.isSafeInteger(local.revision) || local.revision < 1) continue
        if (!drafts.has(id) || key === this.key(id)) drafts.set(id, {
          id, map_id: this.mapId, title: String(local.draft?.title ?? local.snapshot.options.title ?? `Draft ${id}`),
          source_version_id: local.draft?.source_version_id ?? null, author_id: local.draft?.author_id ?? getAdminParams().user.id,
          created_at: local.draft?.created_at ?? "", updated_at: local.draft?.updated_at ?? "",
          snapshot: local.confirmed, revision: local.revision,
        })
      } catch { /* unavailable or unreadable records never replace valid cached drafts */ }
    }
    return [...drafts.values()]
  }

  private async cacheIndex(index: DraftIndex): Promise<void> {
    await this.updateCache(entries => {
      for (const draft of index.drafts) {
        const snapshot = authoringSnapshot(draft.snapshot)
        this.collectGarbage(entries, { id: draft.id, snapshot })
        const key = this.key(draft.id), existing = entries.get(key)
        if (existing === undefined || (this.isClean(existing) && (!readLocal(existing).draft || readLocal(existing).revision !== draft.revision || !equal(readLocal(existing).snapshot, snapshot)))) {
          entries.set(key, writeLocal({ draft: draftMetadata(draft), snapshot, confirmed: snapshot, revision: draft.revision, writer: this.writer, updatedAt: Date.now() }))
        }
      }
      entries.set(`${this.scope}:index`, JSON.stringify({ versions: index.versions, published_version_id: index.published_version_id }))
      this.collectGarbage(entries)
    })
  }

  cachedPreview(error: unknown): AppSnapshot {
    if (!unavailable(error) || !this.active) throw error
    this.markUnavailable(error)
    return clone(this.active.snapshot)
  }

  /** Cache the actual runtime SVG response in the same database, with one entry per source. */
  async previewSvg(source: string, revision: number, load: () => Promise<string>): Promise<string> {
    const key = `${this.scope}:svg:${encodeURIComponent(source)}`
    const cached = () => {
      try { const data = JSON.parse(this.recoveryCache.get(key) ?? "null"); return typeof data?.content === "string" ? data.content as string : undefined } catch { return undefined }
    }
    if (this.offline && cached()) return cached()!
    let content: string
    try { content = await load() }
    catch (error) { const retained = cached(); if (retained && unavailable(error)) return retained; throw error }
    this.queueLocal(() => this.updateCache(entries => { entries.set(key, JSON.stringify({ revision, content })) }))
    return content
  }

  /** Reconcile baselines before retrying writes; never replace the open authoring snapshot. */
  async reconnect(): Promise<void> {
    if (this.reconnecting) return this.reconnecting
    const reconnecting = this.serial(async () => {
      if (!this.offline) return
      let index: DraftIndex
      try { index = await this.readIndex() }
      catch (error) { this.connectionError = error instanceof Error ? error.message : String(error); this.emit(); throw error }
      this.serverDraftIds = new Set(index.drafts.map(draft => draft.id))
      this.versions = index.versions; this.publishedVersionId = index.published_version_id
      for (const copy of this.copies.values()) {
        const remote = index.drafts.find(draft => draft.id === copy.draft.id)
        if (!remote) {
          copy.conflicted = true
          copy.serverError = "Draft is missing on the server. Your local copy is retained; recover it as a new draft."
        } else {
          const snapshot = authoringSnapshot(remote.snapshot)
          if (equal(snapshot, copy.confirmed) || equal(snapshot, copy.snapshot)) {
            copy.draft = remote; copy.revision = remote.revision; copy.confirmed = snapshot
            copy.dirty = !equal(copy.snapshot, snapshot)
            if (!copy.conflicted) copy.serverError = undefined
          } else {
            copy.conflicted = true
            copy.serverError = "The server draft changed while disconnected. Both copies are retained; recover your local copy as a new draft."
          }
        }
        this.persist(copy)
      }
      for (const draft of index.drafts) if (!this.copies.has(draft.id)) this.adopt(draft)
      this.queueLocal(() => this.cacheIndex(index))
      this.offline = false; this.connectionError = null
      this.emit()
    })
    this.reconnecting = reconnecting
    try { await reconnecting } finally { if (this.reconnecting === reconnecting) this.reconnecting = null }

  }

  initialize(legacy?: Record<string, unknown>): Promise<void> {
    if (this.initializing) return this.initializing
    this.initializing = (async () => {
      try {
        let recoveryError: string | undefined
        try {
          for (const item of await this.recoveryStore.read(this.scope)) this.recoveryCache.set(item.key, item.value)
          await this.migrateLocalStorage()
        } catch (error) { recoveryError = `Local recovery failed: ${String(error)}` }
        let index: DraftIndex
        try {
          index = await this.readIndex()
          this.serverDraftIds = new Set(index.drafts.map(draft => draft.id))
          try { await this.cacheIndex(index) } catch (error) { recoveryError = `Local recovery failed: ${String(error)}` }
        } catch (error) {
          if (!unavailable(error)) throw error
          const drafts = this.cachedDrafts()
          if (!drafts.length) throw error
          let metadata: Pick<DraftIndex, "versions" | "published_version_id"> = { versions: [], published_version_id: null }
          try {
            const saved = JSON.parse(this.recoveryCache.get(`${this.scope}:index`) ?? "null")
            if (Array.isArray(saved?.versions)) metadata = { versions: saved.versions, published_version_id: saved.published_version_id ?? null }
          } catch { /* older cache records have no history metadata */ }
          index = { drafts, ...metadata }
          this.markUnavailable(error)
        }
        if (typeof window.BroadcastChannel === "function" && !this.disposed) {
          this.channel = new window.BroadcastChannel(this.scope)
          this.channel.onmessage = event => this.onStorage(event.data)
        }
        for (const draft of index.drafts) {
          const copy = this.adopt(draft)
          if (recoveryError) copy.localError = recoveryError
        }
        this.versions = index.versions
        this.publishedVersionId = index.published_version_id
        let storedId: number | null = null
        storedId = Number(this.recoveryCache.get(`${this.scope}:active`)) || null
        this.activeId = storedId && this.copies.has(storedId) ? storedId : index.drafts[0]?.id ?? null
        if (legacy && this.active && !this.offline) {
          // IndexedDB payload migration is a separate independent draft, idempotent across reloads.
          const snapshot = { ...this.active.snapshot, options: clone(legacy) }
          const result = await this.api<{ draft: AppDraft }>(this.path(), "POST", {
            title: "Recovered local draft", snapshot, client_key: `indexeddb:${stable(legacy)}`,
          })
          this.adopt(result.draft)
          this.activeId = result.draft.id
        }
        try {
          for (const [key, raw] of this.localEntries()) {
            const id = Number(key.slice(this.scope.length + 1).split(":")[0])
            if (!id || this.copies.has(id)) continue
            try {
              const local = readLocal(raw)
              if (local.snapshot?.options && local.confirmed?.options
                && !this.recoveries.some(item => equal(item.snapshot, local.snapshot))) {
                // A missing row is not a deletion acknowledgment, even for a previously synced copy.
                this.recoveries.push({ key, title: `Missing server draft #${id}`, snapshot: local.snapshot })
              }
            } catch { /* preserve malformed records while recovering the readable ones */ }
          }
        } catch { /* unavailable storage never replaces working state */ }
        if (this.offline) this.serverDraftIds.clear()
        this.ready = true
        this.error = null
      } catch (error) { this.error = error instanceof Error ? error.message : String(error); this.initializing = null; throw error }
      finally { this.emit() }
    })()
    return this.initializing
  }

  capture(record: AppSnapshot): void {
    const copy = this.active
    if (!copy || Number(record.id) !== this.mapId) return
    const snapshot = authoringSnapshot(record)
    if (!canEditJavaScript()) snapshot.options = retainReadOnlyJavaScript(snapshot.options, copy.confirmed.options)
    if (equal(snapshot, copy.snapshot)) return
    copy.snapshot = snapshot
    copy.dirty = !equal(snapshot, copy.confirmed)
    this.persist(copy)
    this.emit()
  }

  /** Storage events never acknowledge another tab's revision while this tab is editing. */
  onStorage(event: Pick<StorageEvent, "key" | "newValue">): void {
    for (const copy of this.copies.values()) {
      if (event.key !== this.key(copy.draft.id) || !event.newValue || copy.conflicted) continue
      try {
        const local = JSON.parse(event.newValue) as LocalCopy
        if (local.writer === this.writer || !local.snapshot?.options) return
        if (equal(local.snapshot, copy.snapshot)) return
        copy.conflicted = true
        copy.serverError = "Another tab changed this draft. Your copy is retained; recover it as a new draft."
        this.persist(copy)
        this.emit()
      } catch { /* malformed foreign writes are not adopted */ }
    }
  }

  private async serial<T>(operation: () => Promise<T>): Promise<T> {
    while (this.pending) await this.pending.catch(() => {})
    const promise = operation()
    this.pending = promise
    try { return await promise } finally { if (this.pending === promise) this.pending = null; this.emit() }
  }

  async flush(id = this.activeId): Promise<void> {
    if (id == null) return
    return this.serial(async () => {
      const copy = this.copies.get(id)
      if (!copy) return
      if (copy.conflicted) throw new Error(copy.serverError ?? "Draft revision conflict")
      if (this.offline) throw new Error("Server unavailable. Your local edits are retained.")
      if (!copy.dirty) return
      const submitted = clone(copy.snapshot)
      const revision = copy.revision
      this.busy = true; this.emit()
      try {
        const result = await this.api<{ revision: number }>(this.path(id), "PUT", { snapshot: submitted, revision })
        if (result.revision !== revision + 1) throw new Error("The server did not confirm the expected draft revision.")
        copy.revision = result.revision
        copy.confirmed = submitted
        copy.dirty = !equal(copy.snapshot, submitted)
        copy.serverError = undefined
        this.persist(copy)
      } catch (error) {
        copy.serverError = error instanceof Error ? error.message : String(error)
        if (error instanceof DraftHttpError && (error.status === 409 || error.status === 404)) copy.conflicted = true
        if (unavailable(error)) this.markUnavailable(error)
        this.persist(copy)
        throw error
      } finally { this.busy = false; this.emit() }
    })
  }

  /** Serialize SVG writes with autosave/Publish and acknowledge their draft CAS revision. */
  async saveSvg(source: string, svg: string, resetGeometry: boolean, id = this.activeId): Promise<AppSnapshot> {
    if (id == null) throw new Error("Choose a draft before saving SVG")
    await this.flush(id)
    return this.serial(async () => {
      const copy = this.copies.get(id)
      if (!copy || this.activeId !== id || copy.snapshot.options.source !== source) throw new Error("This SVG editor is no longer active.")
      if (copy.conflicted) throw new Error(copy.serverError ?? "Draft revision conflict")
      if (this.offline) throw new Error("Server unavailable. Your SVG edits are retained in the editor.")
      const revision = copy.revision
      this.busy = true; this.emit()
      try {
        const result = await this.api<{ draft: AppDraft; svg: string }>(this.path(id, "/svg"), "POST", { revision, source, svg, resetGeometry })
        if (result.draft.id !== id || result.draft.revision !== revision + 1
          || typeof result.draft.snapshot?.options?.source !== "string"
          || !Number.isSafeInteger(result.draft.snapshot.svgFileLastChanged) || Number(result.draft.snapshot.svgFileLastChanged) <= 0 || typeof result.svg !== "string" || !result.svg) {
          throw new Error("The server did not confirm the saved SVG revision.")
        }
        const acknowledged = authoringSnapshot(result.draft.snapshot)
        if (copy.snapshot.options.source === source) {
          const options: Record<string, unknown> = { ...copy.snapshot.options, source: acknowledged.options.source }
          if (acknowledged.options.svgAsset) options.svgAsset = clone(acknowledged.options.svgAsset)
          else delete options.svgAsset
          if (resetGeometry) for (const key of ["width", "height", "viewBox"]) options[key] = acknowledged.options[key]
          copy.snapshot = authoringSnapshot({ ...copy.snapshot, options, svgFileLastChanged: acknowledged.svgFileLastChanged })
        }
        copy.draft = result.draft
        copy.revision = result.draft.revision
        copy.confirmed = acknowledged
        copy.dirty = !equal(copy.snapshot, acknowledged)
        copy.serverError = undefined
        // Retain the acknowledged source in a snapshot before SVG cache pruning runs.
        this.persist(copy)
        const key = `${this.scope}:svg:${encodeURIComponent(String(acknowledged.options.source))}`
        this.queueLocal(() => this.updateCache(entries => { entries.set(key, JSON.stringify({ revision: acknowledged.svgFileLastChanged, content: result.svg })) }))
        return clone(acknowledged)
      } catch (error) {
        copy.serverError = error instanceof Error ? error.message : String(error)
        if (error instanceof DraftHttpError && (error.status === 409 || error.status === 404)) copy.conflicted = true
        if (unavailable(error)) this.markUnavailable(error)
        this.persist(copy); throw error
      } finally { this.busy = false; this.emit() }
    })
  }

  async autosave(): Promise<void> {
    if (this.offline) { try { await this.reconnect() } catch { return } }
    for (const copy of this.copies.values()) {
      if (!copy.localSaved) { this.persist(copy); this.emit() }
      if (copy.dirty && !copy.conflicted) await this.flush(copy.draft.id).catch(() => {})
    }
  }

  async select(id: number): Promise<void> {
    if (!this.copies.has(id)) throw new Error("Draft not found")
    // Outgoing dirty copy is already durable locally; do not discard it on network failure.
    await this.flush().catch(() => {})
    await this.serial(async () => {
      if (this.offline) { this.activeId = id; this.cacheSelection(); this.emit(); return }
      const result = await this.api<{ draft: AppDraft }>(this.path(id))
      const existing = this.copies.get(id)!
      if (existing.dirty || existing.conflicted) {
        if (existing.revision !== result.draft.revision) {
          existing.conflicted = true; existing.serverError = "Server revision changed; recover your copy as a new draft."
        }
      } else this.adopt(result.draft)
      this.activeId = id
      this.cacheSelection()
      this.emit()
    })
  }

  /** Explicit, confirmed replacement of this working copy. Never writes to the server. */
  async pull(id = this.activeId): Promise<void> {
    if (id == null) throw new Error("Choose a draft before pulling changes")
    const copy = this.copies.get(id)
    if (!copy) throw new Error("Draft not found")
    const before = clone(copy.snapshot)
    const unchanged = () => this.copies.get(id) === copy && equal(copy.snapshot, before)
    const changed = () => new Error("The local draft changed while pulling. Your newer edits are retained; try again.")
    await this.serial(async () => {
      if (!unchanged()) throw changed()
      this.busy = true; this.emit()
      try {
        await this.waitForLocalPersistence()
        const previous = this.localSlots.get(id)
        const canonical = this.key(id), observed = this.recoveryCache.get(canonical)
        const result = await this.api<{ draft: AppDraft }>(this.path(id)).catch(error => {
          if (unavailable(error)) this.markUnavailable(error)
          throw error
        })
        const draft = result.draft
        if (draft?.id !== id || draft.map_id !== this.mapId || draft.snapshot?.id !== this.mapId
          || !draft.snapshot.options || !Number.isSafeInteger(draft.revision) || draft.revision < 1) {
          throw new Error("The server did not return the requested draft.")
        }
        await this.waitForLocalPersistence()
        if (!unchanged()) throw changed()
        const snapshot = authoringSnapshot(draft.snapshot)
        const generation = (this.localGeneration.get(id) ?? 0) + 1
        const raw = writeLocal({ draft: draftMetadata(draft), snapshot, confirmed: snapshot,
          revision: draft.revision, writer: this.writer, updatedAt: Date.now(), sequence: generation })
        let retained: { key: string; title: string; snapshot: AppSnapshot } | undefined
        await this.updateCache(entries => {
          if (!unchanged()) throw changed()
          if (entries.get(canonical) !== observed || previous && entries.get(previous.key) !== previous.raw) {
            throw new Error("Another tab changed the local cache while pulling. Both copies are retained; try again.")
          }
          // Confirmation discards only this copy. Preserve a divergent canonical copy owned by another tab.
          if (observed !== undefined && previous?.key !== canonical && !this.isClean(observed)) {
            const key = `${canonical}:recovery:${crypto.randomUUID()}`
            entries.set(key, observed)
            try { retained = { key, title: `${draft.title} · recovered tab`, snapshot: readLocal(observed).snapshot } } catch { /* retain opaque data */ }
          }
          if (previous && previous.key !== canonical) entries.delete(previous.key)
          entries.set(canonical, raw)
          this.collectGarbage(entries)
        })
        if (!unchanged()) { this.persist(copy); throw changed() }
        this.localGeneration.set(id, generation)
        this.localSlots.set(id, { key: canonical, raw })
        this.copies.set(id, { draft, snapshot, confirmed: snapshot, revision: draft.revision,
          dirty: false, localSaved: true, conflicted: false })
        this.serverDraftIds.add(id)
        this.recoveries = this.recoveries.filter(item => item.key !== previous?.key)
        if (retained && !this.recoveries.some(item => equal(item.snapshot, retained!.snapshot))) this.recoveries.push(retained)
        this.offline = false; this.connectionError = null
        try { this.channel?.postMessage({ key: canonical, newValue: raw }) } catch { /* server CAS remains authoritative */ }
      } finally { this.busy = false; this.emit() }
    })
  }

  async refreshHistory(): Promise<void> {
    const generation = this.versionMetadataGeneration
    const index = await this.api<DraftIndex>(this.path())
    this.serverDraftIds = new Set(index.drafts.map(draft => draft.id))
    // Refresh metadata only: never replace unacknowledged working copies.
    if (generation === this.versionMetadataGeneration) { this.versions = index.versions; this.publishedVersionId = index.published_version_id }
    for (const draft of index.drafts) if (!this.copies.has(draft.id)) this.adopt(draft)
    this.emit()
  }

  async create(title?: string, versionId?: number, recovered?: AppSnapshot): Promise<void> {
    const source = recovered ? clone(recovered) : this.active ? clone(this.active.snapshot) : undefined
    const result = await this.api<{ draft: AppDraft }>(this.path(), "POST", {
      title, ...(versionId ? { version_id: versionId } : { snapshot: source }), client_key: crypto.randomUUID(),
    })
    this.persist(this.adopt(result.draft))
    this.activeId = result.draft.id
    this.cacheSelection()
    this.emit()
  }

  async rename(id: number, title: string): Promise<void> {
    await this.serial(async () => {
      const copy = this.copies.get(id)
      if (!copy) throw new Error("Draft not found")
      if (this.offline) throw new Error("Reconnect before renaming a draft. Your local edits are retained.")
      if (copy.conflicted) throw new Error(copy.serverError ?? "Draft revision conflict")
      this.busy = true; this.emit()
      try {
        const result = await this.api<{ title: string; revision: number }>(this.path(id, "/rename"), "POST", { title, revision: copy.revision })
        if (result.revision !== copy.revision + 1 || typeof result.title !== "string") throw new Error("The server did not confirm the draft name.")
        copy.revision = result.revision
        copy.draft = { ...copy.draft, title: result.title, revision: result.revision }
        copy.serverError = undefined
        this.persist(copy)
      } catch (error) {
        copy.serverError = error instanceof Error ? error.message : String(error)
        if (error instanceof DraftHttpError && (error.status === 409 || error.status === 404)) copy.conflicted = true
        if (unavailable(error)) this.markUnavailable(error)
        this.persist(copy); throw error
      } finally { this.busy = false; this.emit() }
    })
  }

  async renameVersion(id: number, title: string, expectedTitle: string): Promise<void> {
    await this.serial(async () => {
      if (this.offline) throw new Error("Reconnect before renaming a version.")
      if (!this.versions.some(version => version.id === id)) throw new Error("Version not found")
      this.busy = true; this.emit()
      try {
        const result = await this.api<{ version_id: number; title: string }>(`/apps/${this.mapId}/versions/${id}/rename`, "POST", { title, expected_title: expectedTitle })
        if (result.version_id !== id || typeof result.title !== "string") throw new Error("The server did not confirm the version name.")
        this.versionMetadataGeneration++
        this.versions = this.versions.map(version => version.id === id ? { ...version, title: result.title } : version)
        this.queueLocal(() => this.cacheIndex({ drafts: [], versions: this.versions, published_version_id: this.publishedVersionId }))
      } catch (error) {
        if (unavailable(error)) this.markUnavailable(error)
        throw error
      } finally { this.busy = false; this.emit() }
    })
  }

  async restore(versionId: number): Promise<void> {
    const id = this.activeId
    if (id == null) return
    // Freeze this exact pre-restore copy and flush it before the server creates its immutable backup.
    const before = clone(this.active!.snapshot)
    await this.flush(id)
    await this.serial(async () => {
      const copy = this.copies.get(id)!
      if (!equal(before, copy.snapshot) || copy.dirty || copy.conflicted) throw new Error("The draft changed during restore. Retry to include the latest changes.")
      const result = await this.api<{ draft: AppDraft }>(this.path(id, "/restore"), "POST", { revision: copy.revision, version_id: versionId })
      // A user may keep typing during the request. Preserve those changes instead of replacing them.
      if (!equal(before, copy.snapshot)) {
        copy.revision = result.draft.revision
        copy.confirmed = authoringSnapshot(result.draft.snapshot)
        copy.draft = result.draft
        copy.dirty = !equal(copy.snapshot, copy.confirmed)
        this.persist(copy)
        throw new Error("Version restored on server; newer local edits retained. Save them or switch drafts to inspect the restored version.")
      }
      this.copies.delete(id)
      const restored = result.draft
      // Explicit restore intentionally supersedes this tab's local copy, backed up server-side above.
      const snapshot = authoringSnapshot(restored.snapshot)
      const next: DraftWorkingCopy = { draft: restored, snapshot, confirmed: snapshot, revision: restored.revision, dirty: false, localSaved: false, conflicted: false }
      this.copies.set(id, next); this.persist(next); this.emit()
    })
    await this.refreshHistory()
  }

  async checkout(versionId: number): Promise<AppSnapshot> {
    const snapshot = await this.serial(async () => {
      this.busy = true; this.emit()
      try {
        const result = await this.api<{ version_id: number; snapshot: AppSnapshot }>(`/apps/${this.mapId}/versions/${versionId}/checkout`, "POST")
        if (result.version_id !== versionId || result.snapshot?.id !== this.mapId || !result.snapshot.options) throw new Error("The server did not confirm the live version.")
        this.publishedVersionId = result.version_id
        // Checkout changes production only: no draft revision, acknowledgment or local copy changes.
        return authoringSnapshot(result.snapshot)
      } finally { this.busy = false; this.emit() }
    })
    await this.refreshHistory().catch(() => {})
    return snapshot
  }

  async publish(record: AppSnapshot, id = this.activeId): Promise<number> {
    if (id == null) throw new Error("Choose a draft before Publish")
    // Capture once before waiting for an older autosave; never substitute later edits.
    const submitted = authoringSnapshot(record)
    if (!canEditJavaScript()) submitted.options = retainReadOnlyJavaScript(submitted.options, this.copies.get(id)!.confirmed.options)
    if (id === this.activeId) this.capture(record)
    if (this.offline) await this.reconnect()
    const versionId = await this.serial(async () => {
      const copy = this.copies.get(id)!
      if (copy.conflicted) throw new Error(copy.serverError ?? "Draft revision conflict")
      this.busy = true; this.emit()
      try {
        const result = await this.api<{ revision: number; version_id: number }>(this.path(id, "/publish"), "POST", {
          snapshot: submitted, revision: copy.revision, request_id: crypto.randomUUID(),
        })
        if (result.revision !== copy.revision + 1 || !Number.isSafeInteger(result.version_id)) throw new Error("The server did not confirm the publication revision.")
        copy.draft.migration = false
        copy.revision = result.revision; copy.confirmed = submitted
        copy.dirty = !equal(copy.snapshot, submitted)
        copy.serverError = undefined
        this.publishedVersionId = result.version_id
        this.persist(copy)
        return result.version_id
      } catch (error) {
        copy.serverError = error instanceof Error ? error.message : String(error)
        if (error instanceof DraftHttpError && (error.status === 409 || error.status === 404)) copy.conflicted = true
        if (unavailable(error)) this.markUnavailable(error)
        this.persist(copy); throw error
      } finally { this.busy = false; this.emit() }
    })
    // A history read failure cannot turn an acknowledged publication into a failed write.
    await this.refreshHistory().catch(() => {})
    return versionId
  }

  async versionSnapshot(versionId: number): Promise<AppSnapshot> {
    const result = await this.api<{ version: { snapshot: AppSnapshot } }>(`/apps/${this.mapId}/versions/${versionId}`)
    return authoringSnapshot(result.version.snapshot)
  }

  async unpublish(versionId: number): Promise<void> {
    await this.serial(async () => {
      const result = await this.api<{ unpublished_version_id: number; published_version_id: null }>(`/apps/${this.mapId}/versions/${versionId}/unpublish`, "POST")
      if (result.unpublished_version_id !== versionId || result.published_version_id !== null) throw new Error("The server did not confirm Unpublish.")
      this.publishedVersionId = null
      // The snapshot stays in History and the editor's working copies remain untouched.
      this.emit()
    })
    await this.refreshHistory().catch(() => {})
  }

  async deleteDraft(id: number): Promise<void> {
    const before = this.copies.get(id)
    if (!before) throw new Error("Draft not found")
    const snapshot = clone(before.snapshot)
    await this.serial(async () => {
      const copy = this.copies.get(id)!
      const result = await this.api<{ deleted_draft_id: number }>(this.path(id), "DELETE", { revision: copy.revision })
      if (result.deleted_draft_id !== id) throw new Error("The server did not confirm deletion.")
      if (!equal(snapshot, copy.snapshot)) {
        copy.conflicted = true
        copy.serverError = "Draft deleted on server; newer local edits retained. Recover them as a new draft."
        this.persist(copy)
        throw new Error(copy.serverError)
      }
      this.copies.delete(id)
      this.serverDraftIds.delete(id)
      this.localGeneration.set(id, (this.localGeneration.get(id) ?? 0) + 1)
      const slot = this.localSlots.get(id)
      this.queueLocal(() => this.updateCache(entries => {
        const latestSlot = this.localSlots.get(id)
        if (latestSlot && entries.get(latestSlot.key) === latestSlot.raw) entries.delete(latestSlot.key)
        this.localSlots.delete(id)
        for (const [key, raw] of entries) if (this.draftId(key) === id && this.isClean(raw)) entries.delete(key)
        this.collectGarbage(entries)
      }))
      // Divergent foreign copies remain recoverable after deletion.
      if (slot) this.recoveries = this.recoveries.filter(item => item.key !== slot.key)
      if (this.activeId === id) {
        this.activeId = this.copies.keys().next().value ?? null
        this.cacheSelection()
      }
      this.emit()
    })
  }

  async preview(url?: string): Promise<string> {
    if (this.offline) throw new Error("Reconnect before opening the site preview. Your local edits are retained.")
    const id = this.activeId
    if (id == null) throw new Error("Choose a draft")
    await this.flush(id)
    return this.serial(async () => {
      const copy = this.copies.get(id)!
      if (copy.dirty || copy.conflicted) throw new Error("Draft changed while saving. Retry preview.")
      const result = await this.api<{ url: string }>(this.path(id, "/preview"), "POST", { revision: copy.revision, url })
      return result.url
    })
  }
}

const sessions = new Map<number, AppDraftSession>()
export function getAppDraftSession(mapId: number): AppDraftSession {
  let session = sessions.get(mapId)
  if (!session) { session = new AppDraftSession(mapId); sessions.set(mapId, session) }
  return session
}
export function clearAppDraftSessions(): void { for (const session of sessions.values()) session.dispose(); sessions.clear() }

export async function autosaveAppDraftSessions(): Promise<void> {
  await Promise.all([...sessions.values()].filter(session => session.ready).map(session => session.autosave()))
}
/** A file upgrade must not discard edits whose local transaction has not committed. */
export async function prepareAppDraftSessionsForReload(): Promise<void> {
  const active = [...sessions.values()].filter(session => session.ready)
  await Promise.all(active.map(session => session.prepareForReload()))
}
export function handleAppDraftStorageEvent(event: StorageEvent): void {
  for (const session of sessions.values()) session.onStorage(event)
}

export function forgetAppDraftSession(mapId: number): void { sessions.get(mapId)?.dispose(); sessions.delete(mapId) }

if (import.meta.hot) import.meta.hot.dispose(clearAppDraftSessions)
