import { adminRestFetch } from "@/lib/admin-rest-fetch"
import {
  getAdminParams,
  type ReactAdminMapListItem,
  type ReactAdminSvgFileItem,
  type ReactAdminImageFileItem,
} from "./admin-params"
import { resourceApiUrl } from "./resource-api-url"

async function request(path: string, body: BodyInit): Promise<Record<string, unknown>> {
  const { apiUrl, nonce } = getAdminParams()
  const response = await adminRestFetch(resourceApiUrl(apiUrl, path), {
    method: "POST",
    credentials: "same-origin",
    headers: { Accept: "application/json", "X-WP-Nonce": nonce },
    body,
  })
  const data = await response.json().catch(() => null)
  if (!response.ok) {
    const error = data?.error ?? data?.data?.error ?? data?.message
    throw new Error(typeof error === "string" ? error : `Request failed (${response.status}).`)
  }
  if (!data || typeof data !== "object") throw new Error("The server returned an invalid response.")
  return data
}

function svgFile(data: Record<string, unknown>): ReactAdminSvgFileItem {
  const uploaded = data.file as Partial<ReactAdminSvgFileItem> | undefined
  if (
    !uploaded ||
    typeof uploaded.relativeUrl !== "string" ||
    !uploaded.relativeUrl ||
    typeof uploaded.name !== "string" ||
    typeof uploaded.pathShort !== "string"
  ) {
    throw new Error("The server did not return the uploaded SVG file.")
  }
  return uploaded as ReactAdminSvgFileItem
}

export async function uploadMapSvg(
  file: File,
  requireGoogleOverlay = false,
): Promise<ReactAdminSvgFileItem> {
  if (!/\.svg$/i.test(file.name)) throw new Error("Choose an SVG file.")
  const body = new FormData()
  // The SVG endpoint accepts XML MIME types; files with no browser MIME need an explicit type.
  body.append("file", new Blob([file], { type: "image/svg+xml" }), file.name)
  body.append("createNew", "true")
  if (requireGoogleOverlay) body.append("requireGoogleOverlay", "true")
  return svgFile(await request("/svgfile", body))
}

export async function uploadMapImage(file: File): Promise<ReactAdminImageFileItem> {
  if (!/\.(?:png|jpe?g|gif|webp)$/i.test(file.name))
    throw new Error("Choose a PNG, JPEG, GIF or WebP image.")
  const body = new FormData()
  body.append("file", file, file.name)
  const data = await request("/imagefile", body)
  const uploaded = data.file as Partial<ReactAdminImageFileItem> | undefined
  if (
    !uploaded ||
    typeof uploaded.name !== "string" ||
    typeof uploaded.relativeUrl !== "string" ||
    !uploaded.relativeUrl ||
    typeof uploaded.pathShort !== "string" ||
    uploaded.origin !== "uploads" ||
    !Number.isSafeInteger(uploaded.width) ||
    !Number.isSafeInteger(uploaded.height) ||
    (uploaded.width ?? 0) <= 0 ||
    (uploaded.height ?? 0) <= 0 ||
    !["image/png", "image/jpeg", "image/gif", "image/webp"].includes(uploaded.mimeType ?? "")
  ) {
    throw new Error("The server did not return the uploaded image.")
  }
  return uploaded as ReactAdminImageFileItem
}

/** Resolve a catalog raster and create its independent SVG wrapper before submitting Map creation. */
export async function createImageMapSource(
  image: ReactAdminImageFileItem,
): Promise<ReactAdminSvgFileItem> {
  if (!image.relativeUrl) throw new Error("Choose an image.")
  const body = new URLSearchParams({ source: image.relativeUrl })
  return svgFile(await request("/imagefile/svg", body))
}

async function createMapOptions(
  title: string,
  options: Record<string, unknown>,
): Promise<ReactAdminMapListItem> {
  if (!title.trim() || !options.source) throw new Error("Enter a title and choose a map file.")
  const body = new URLSearchParams()
  // Structural defaults, geographic source defaults and private schemas belong to the backend.
  body.set("map[options]", JSON.stringify({ ...options, title: title.trim() }))
  const data = await request("/maps", body)
  const map = data.map as { id?: unknown; title?: unknown } | undefined
  const id = Number(map?.id)
  if (!Number.isSafeInteger(id) || id <= 0)
    throw new Error("The server did not return the created map.")
  return {
    id,
    title: typeof map?.title === "string" && map.title.trim() ? map.title : title.trim(),
  }
}

export async function createMap(title: string, source: string): Promise<ReactAdminMapListItem> {
  return createMapOptions(title, { source })
}

/** Explicit Google overlay creation also accepts calibrated SVGs without a screenshot marker. */
export async function createGoogleOverlayMap(
  title: string,
  source: string,
): Promise<ReactAdminMapListItem> {
  const options = getAdminParams().options as Record<string, unknown> | null
  if (typeof options?.google_api_key !== "string" || !options.google_api_key.trim()) {
    throw new Error("Add a Google Maps API key in Settings → General.")
  }
  return createMapOptions(title, { source, googleMaps: { on: true } })
}

/** Retained empty, calibrated Google Map creation, using the installation API key. */
export async function createGoogleMap(title: string): Promise<ReactAdminMapListItem> {
  const params = getAdminParams()
  const options =
    params.options && typeof params.options === "object"
      ? (params.options as Record<string, unknown>)
      : {}
  if (typeof options.google_api_key !== "string" || !options.google_api_key.trim()) {
    throw new Error("Add a Google Maps API key in Settings → General.")
  }
  if (!params.pluginUrl) throw new Error("The Google Map source is unavailable.")
  const source = new URL(
    `${params.pluginUrl.replace(/\/?$/, "/")}maps/geo-calibrated/empty.svg`,
    window.location.href,
  ).pathname
  return createMapOptions(title, {
    source,
    viewBox: [-1766.3868973306835, 146.6496453220534, 23928.888888888887, 13460],
    googleMaps: { on: true, zoom: 1, center: { lat: 41.99585227532726, lng: 10.688006500000029 } },
  })
}

/** Copy only the saved map; backend owns SVG, private schema/record and relation copying. */
export async function duplicateMap(mapId: number, title: string): Promise<ReactAdminMapListItem> {
  if (!Number.isSafeInteger(mapId) || mapId <= 0 || !title.trim())
    throw new Error("Choose a map to duplicate.")
  const body = new URLSearchParams()
  // The copy endpoint expects top-level options, unlike the create endpoint's map[options].
  body.set("options", JSON.stringify({ title: title.trim() }))
  const data = await request(`/maps/${mapId}/copy`, body)
  const map = data.map as { id?: unknown; title?: unknown } | undefined
  const id = Number(map?.id)
  if (!Number.isSafeInteger(id) || id <= 0 || id === mapId)
    throw new Error("The server did not return the duplicated map.")
  return {
    id,
    title: typeof map?.title === "string" && map.title.trim() ? map.title : title.trim(),
  }
}
