import { adminRestFetch } from "@/lib/admin-rest-fetch"
import { getAppDraftSession, draftRequest } from "@/lib/app-drafts"
import { getAdminParams } from "@/lib/admin-params"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { invalidateAdminMapRuntime } from "@/lib/admin-map-runtime-cache"
import { cloneMapOptions, fingerprintEditableMapOptions, mapOptionsMatchBaseline, mapOptionsTitle } from "@/lib/map-draft"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { resourceApiUrl } from "@/lib/resource-api-url"
import { useWorkspaceStore } from "@/lib/workspace-store"

export type MapSvgOwner = {
  map: MapsvgMapInstance
  source: string
  draftId?: number | null
  /** Retain a successfully created copy across a failed Save retry. */
  pendingSource?: string
  pendingSvgFileLastChanged?: number
}

type OperationOptions = { signal?: AbortSignal; onSubmitted?: () => void; resetGeometry?: boolean; preserveWorkspace?: boolean }
type SvgMapCommit = { id: number; options: Record<string, unknown>; svgFileLastChanged?: number }

export function captureMapSvgOwner(map: MapsvgMapInstance): MapSvgOwner {
  return { map, source: typeof map.options.source === "string" ? map.options.source : "", draftId: getAppDraftSession(map.id).activeId }
}

export function isMapSvgOwnerCurrent(owner: MapSvgOwner): boolean {
  return getAdminMapInstance() === owner.map && owner.map.options.source === owner.source && (owner.draftId === undefined || owner.draftId === getAppDraftSession(owner.map.id).activeId)
}

function assertOwner(owner: MapSvgOwner, options: OperationOptions): void {
  if (options.signal?.aborted || !isMapSvgOwnerCurrent(owner))
    throw new Error("This SVG editor is no longer active.")
  if (!Number.isSafeInteger(owner.map.id) || owner.map.id <= 0 || !owner.source)
    throw new Error("Choose a saved map with an SVG file.")
  if (useWorkspaceStore.getState().mapDrafts[String(owner.map.id)]?.conflicted)
    throw new Error("Resolve the map draft conflict before editing its SVG file.")
}

async function request(path: string, body: BodyInit): Promise<Record<string, any>> {
  const { apiUrl, nonce } = getAdminParams()
  // Once submitted, cancellation cannot establish that a file write did not commit.
  const response = await adminRestFetch(resourceApiUrl(apiUrl, path), {
    method: "POST", credentials: "same-origin",
    headers: { Accept: "application/json", "X-WP-Nonce": nonce }, body,
  })
  const data = await response.json().catch(() => null)
  if (!response.ok || !data || typeof data !== "object" || data.error) {
    const error = data?.error ?? data?.message
    throw new Error(typeof error === "string" ? error : `SVG operation failed (${response.status}).`)
  }
  return data
}

function svgRevision(value: unknown): number {
  if (typeof value !== "number" && (typeof value !== "string" || !/^\d+$/.test(value))) return 0
  const revision = Number(value)
  return Number.isSafeInteger(revision) && revision > 0 ? revision : 0
}

function currentSvgRevision(owner: MapSvgOwner): number {
  return Math.max(svgRevision(owner.map.svgFileLastChanged), svgRevision(owner.map.getData?.().svgFileLastChanged))
}

function savedSvgRevision(value: unknown): number {
  const revision = svgRevision(value)
  if (!revision) throw new Error("The server did not return the saved SVG revision.")
  return revision
}

function refresh(owner: MapSvgOwner, revision?: number): void {
  if (!isMapSvgOwnerCurrent(owner)) return
  if (revision !== undefined) owner.map.svgFileLastChanged = revision
  window.dispatchEvent(new CustomEvent("mapsvg:options-replace", {
    detail: { mapId: owner.map.id, options: cloneMapOptions(owner.map) },
  }))
}

/** Acknowledge only saved SVG keys; unrelated current edits remain a draft. */
function adoptCommit(owner: MapSvgOwner, committed: SvgMapCommit, resetGeometry: boolean): void {
  const state = useWorkspaceStore.getState(), id = owner.map.id, key = String(id)
  const current = getAdminMapInstance()
  if (Number(committed?.id) !== id || !committed.options || typeof committed.options.source !== "string")
    throw new Error("The server did not return the saved SVG source.")
  const revision = committed.svgFileLastChanged === undefined ? undefined : savedSvgRevision(committed.svgFileLastChanged)
  if (current?.id === id && !isMapSvgOwnerCurrent(owner)) return
  // A deleted resource has had its workspace state removed; a late reply cannot restore it.
  if (current?.id !== id && !state.mapSessions[key] && !state.mapDrafts[key] && !state.mapServerBaselines[key]) return
  const local = current?.id === id ? cloneMapOptions(current) : state.mapDrafts[key]?.options ?? cloneMapOptions(owner.map)
  const next = { ...local }
  if (local.source === owner.source || local.source === committed.options.source) {
    for (const field of resetGeometry ? ["source", "width", "height", "viewBox"] : ["source"]) {
      if (Object.prototype.hasOwnProperty.call(committed.options, field)) next[field] = structuredClone(committed.options[field])
      else delete next[field]
    }
  }
  const baseline = fingerprintEditableMapOptions(committed.options), title = mapOptionsTitle(committed.options)
  state.setMapServerBaseline(id, baseline)
  state.setMapBaseline(id, baseline)
  state.setMapTitleBaseline(id, title)
  if (mapOptionsMatchBaseline(next, baseline, title)) state.clearMapDraft(id)
  else state.setMapDraft(id, {
    options: next, baselineFingerprint: baseline, baselineOptionsFingerprint: baseline,
    baselineTitle: title, draftFingerprint: fingerprintEditableMapOptions(next), updatedAt: Date.now(),
  })
  if (current?.id === id) {
    if (next.source === committed.options.source && revision !== undefined)
      current.svgFileLastChanged = revision
    window.dispatchEvent(new CustomEvent("mapsvg:options-replace", { detail: { mapId: id, options: next } }))
  } else invalidateAdminMapRuntime(id)
}

async function commitSource(owner: MapSvgOwner, source: string, resetGeometry: boolean, revision = currentSvgRevision(owner)): Promise<void> {
  const session = getAppDraftSession(owner.map.id)
  if (session.ready && session.activeId != null) {
    const data = await draftRequest<{ source: string; geometry: Record<string, unknown>; svgAsset?: unknown }>(`/apps/${owner.map.id}/drafts/${session.activeId}/svg-source`, "POST", { source })
    assertOwner(owner, {})
    const next: Record<string, unknown> = { ...cloneMapOptions(owner.map), ...(resetGeometry ? data.geometry : {}), source: data.source }
    if (data.svgAsset) next.svgAsset = data.svgAsset
    else delete next.svgAsset
    session.capture({ ...session.active!.snapshot, options: next })
    window.dispatchEvent(new CustomEvent("mapsvg:options-replace", { detail: { mapId: owner.map.id, options: next } }))
    return
  }
  const body = new URLSearchParams({ mapId: String(owner.map.id), source, expectedSource: owner.source, resetGeometry: String(resetGeometry), svgFileLastChanged: String(revision) })
  const data = await request("/svgfile/map-source", body)
  adoptCommit(owner, data.map, resetGeometry)
}

export async function changeMapSvg(owner: MapSvgOwner, source: string, options: OperationOptions = {}): Promise<void> {
  assertOwner(owner, options)
  if (!source || source === owner.source) return
  options.onSubmitted?.()
  await commitSource(owner, source, true)
}

export async function reloadMapSvg(owner: MapSvgOwner, updateTitles: boolean, options: OperationOptions = {}): Promise<void> {
  assertOwner(owner, options)
  options.onSubmitted?.()
  if (getAppDraftSession(owner.map.id).ready) {
    if (updateTitles) throw new Error("Region titles are shared Database records. Edit them in Database; draft reload preserves shared titles.")
    refresh(owner)
    return
  }
  const data = await request("/svgfile/reload", new URLSearchParams({ "file[relativeUrl]": owner.source, updateTitles: String(updateTitles) }))
  if (!options.signal?.aborted) refresh(owner, savedSvgRevision(data.regionSync?.svgFileLastChanged))
}

function isWritableSource(source: string): boolean {
  const globals = window as Window & {
    mapsvgFrontendParams?: { routes?: { uploads?: string } }
    mapsvg?: { routes?: { uploads?: string } }
  }
  const uploads = globals.mapsvgFrontendParams?.routes?.uploads ?? globals.mapsvg?.routes?.uploads
  if (!uploads) return false
  const path = new URL(source, window.location.href), base = new URL(uploads, window.location.href)
  return path.origin === base.origin && path.pathname.startsWith(base.pathname.replace(/\/$/, "") + "/")
}

export async function saveMapSvg(owner: MapSvgOwner, svg: string, options: OperationOptions = {}): Promise<void> {
  assertOwner(owner, options)
  if (!svg.trim()) throw new Error("The drawing editor returned an empty SVG.")
  options.onSubmitted?.()
  const session = getAppDraftSession(owner.map.id)
  if (session.ready) {
    session.capture({ ...session.active!.snapshot, options: cloneMapOptions(owner.map) })
    const saved = await session.saveSvg(owner.source, svg, options.resetGeometry === true, owner.draftId)
    assertOwner(owner, options)
    const next: Record<string, unknown> = { ...cloneMapOptions(owner.map), source: saved.options.source }
    if (saved.options.svgAsset) next.svgAsset = structuredClone(saved.options.svgAsset)
    else delete next.svgAsset
    if (options.resetGeometry) for (const key of ["width", "height", "viewBox"]) next[key] = saved.options[key]
    owner.map.svgFileLastChanged = Number(saved.svgFileLastChanged)
    window.dispatchEvent(new CustomEvent("mapsvg:options-replace", { detail: { mapId: owner.map.id, options: next, preserveWorkspace: options.preserveWorkspace === true } }))
    return
  }
  let source = owner.source
  if (!isWritableSource(source)) {
    if (!owner.pendingSource) {
      const copied = await request("/svgfile/copy", new URLSearchParams({ "file[path]": source }))
      if (typeof copied.file?.relativeUrl !== "string" || !copied.file.relativeUrl)
        throw new Error("The server did not return a writable SVG copy.")
      owner.pendingSource = copied.file.relativeUrl
    }
    source = owner.pendingSource!
  }
  // A completed copy is retained, but a retired editor cannot start another write.
  assertOwner(owner, options)
  const encodedName = new URL(source, window.location.href).pathname.split("/").pop()
  const name = encodedName ? decodeURIComponent(encodedName) : ""
  if (!name || !/\.svg$/i.test(name)) throw new Error("The SVG file has an invalid filename.")
  const body = new FormData()
  body.append("file", new Blob([svg], { type: "image/svg+xml" }), name)
  body.append("path", source)
  const previous = Math.max(currentSvgRevision(owner), source === owner.pendingSource ? owner.pendingSvgFileLastChanged ?? 0 : 0)
  body.append("svgFileLastChanged", String(previous))
  const data = await request("/svgfile/update", body)
  const revision = savedSvgRevision(data.svgFileLastChanged)
  if (revision <= previous) throw new Error("The server did not advance the saved SVG revision.")
  if (source !== owner.source) {
    owner.pendingSvgFileLastChanged = revision
    assertOwner(owner, options)
    await commitSource(owner, source, options.resetGeometry === true, revision)
  } else if (!options.signal?.aborted) {
    if (options.resetGeometry) await commitSource(owner, source, true, revision)
    else refresh(owner, revision)
  }
}
