export const PREPARED_SVG_REQUEST = "mapsvg:apply-prepared-svg"
export type PreparedSvgOperation = {
  mapId: number; draftId: number
  prepare: () => Promise<{ source: string; svg: string; draftId: number; alreadyApplied: boolean; regionIds: string[]; syncRegions?: boolean }>
  complete: (pageId: string, stateId: string) => Promise<unknown>
}
export type PreparedSvgResult = { ok: true; count: number } | { ok: false; message: string }
export type PreparedSvgRequest = PreparedSvgOperation & { respond: (result: PreparedSvgResult) => void }

/** Native editor owns execution; a paid extension supplies only a prepared edit. */
export function requestPreparedSvg(operation: PreparedSvgOperation): Promise<PreparedSvgResult> {
  return new Promise(resolve => {
    const event = new CustomEvent<PreparedSvgRequest>(PREPARED_SVG_REQUEST, { detail: { ...operation, respond: resolve }, cancelable: true })
    if (window.dispatchEvent(event)) resolve({ ok: false, message: "The SVG editor is not ready for this draft." })
  })
}
