import { getAdminParams } from "./admin-params"

const hooks = ["events", "middlewares", "onClick", "mouseOver", "mouseOut", "menuOnClick", "beforeLoad", "afterLoad"]
type Fields = Record<string, unknown>
const fields = (value: unknown): Fields => value && typeof value === "object" && !Array.isArray(value) ? value as Fields : {}
const nonempty = (value: unknown): boolean => value !== null && typeof value === "object"
  ? Object.values(value).some(nonempty) : value !== undefined && value !== null && value !== ""

/** UI hint only; PHP independently authorizes every persisted executable slot. */
export const canEditJavaScript = () => getAdminParams().user.canEditJavaScript !== false

function scripts(options: Fields): Fields {
  const result: Fields = {}
  for (const key of hooks) if (nonempty(options[key])) result[key] = options[key]
  const templates: Fields = {}
  for (const [key, value] of Object.entries(fields(options.templates))) {
    const js = fields(value).js
    if (nonempty(js)) templates[key] = js
  }
  if (Object.keys(templates).length) result.templates = templates
  const nodes: Fields = {}
  for (const [index, value] of Object.entries(options.nodes as object ?? {})) {
    const node = fields(value), code: Fields = {}
    if (nonempty(node.js)) code.js = node.js
    if (nonempty(fields(node.template).js)) code.template = fields(node.template).js
    if (Object.keys(code).length) nodes[String(node.id ?? index)] = code
  }
  if (Object.keys(nodes).length) result.nodes = nodes
  return result
}
function isScriptChange(value: unknown): boolean {
  const change = fields(value)
  if (!Array.isArray(change.path)) return false
  const path = change.path
  if (hooks.includes(path[0]) || (path[0] === "templates" && (path.length < 3 || path[2] === "js"))
    || (path[0] === "nodes" && (path.length < 3 || path[2] === "js"
      || (path[2] === "template" && (path.length < 4 || path[3] === "js"))))) return true
  let tree = change.value
  for (const part of [...change.path].reverse()) tree = { [part]: tree }
  return Object.keys(scripts(fields(tree))).length > 0
}

/** Runtime adds default handlers/template JS. Keep the acknowledged server code in
 * full snapshots for restricted editors, without mutating runtime or server records. */
export function retainReadOnlyJavaScript(options: Fields, previous: Fields): Fields {
  const result = structuredClone(options)
  const restore = (target: Fields, source: Fields, key: string) => {
    if (Object.prototype.hasOwnProperty.call(source, key)) target[key] = structuredClone(source[key])
    else delete target[key]
  }
  for (const key of hooks) restore(result, previous, key)
  for (const [name, value] of Object.entries(fields(result.templates))) {
    if (value && typeof value === "object" && !Array.isArray(value)) restore(value as Fields, fields(fields(previous.templates)[name]), "js")
  }
  const oldNodes = new Map((Array.isArray(previous.nodes) ? previous.nodes : []).map(node => [fields(node).id, fields(node)]))
  for (const node of Array.isArray(result.nodes) ? result.nodes : []) {
    const target = fields(node), source = oldNodes.get(target.id) ?? {}
    restore(target, source, "js")
    if (target.template && typeof target.template === "object") restore(fields(target.template), fields(source.template), "js")
  }
  const oldStates = new Map((fields(previous.stateGraph).states as unknown[] ?? []).map(state => [fields(state).id, fields(state)]))
  for (const state of fields(result.stateGraph).states as unknown[] ?? []) {
    const target = fields(state), source = oldStates.get(target.id)
    target.changes = [
      ...(Array.isArray(target.changes) ? target.changes.filter(change => !isScriptChange(change)) : []),
      ...(Array.isArray(source?.changes) ? structuredClone(source.changes.filter(isScriptChange)) : []),
    ]
  }
  return result
}
