/** UI terminology only: retain legacy scene IDs and stored titles. */
export function appPageLabel(page?: { id: string; title?: string }): string {
  const number = page?.id.match(/^scene-(\d+)$/)?.[1]
  if (number && (!page?.title || page.title === `Scene ${number}`)) return `Page ${number}`
  return page?.title || page?.id || "Page"
}
