import { createContext, type ReactNode } from "react"

export const ComponentInteractionsContext = createContext<{
  body: ReactNode
  toolbarEnd?: ReactNode
  settingsLead?: ReactNode
  settingsEnd?: ReactNode
} | null>(null)

/** One provider shared by core settings and compiled paid controller delegates. */
export function ComponentInteractionsProvider({ children, interactions, toolbarEnd, settingsLead, settingsEnd }: {
  children: ReactNode
  interactions: ReactNode | null
  toolbarEnd?: ReactNode
  settingsLead?: ReactNode
  settingsEnd?: ReactNode
}) {
  return <ComponentInteractionsContext.Provider value={{ body: interactions, toolbarEnd, settingsLead, settingsEnd }}>{children}</ComponentInteractionsContext.Provider>
}
