import { getAppDraftSession } from "./app-drafts"
import { getAdminMapInstance } from "./apply-options-patch"
import { captureMapSvgOwner, saveMapSvg } from "./map-svg-operations"
import { captureRegionSyncOwner, previewRegionSync, applyRegionSync } from "./region-svg-sync"
import type { PreparedSvgOperation } from "./prepared-svg-actions"

/** Reuse Draw's canonical Save and reviewed sync. Source/runtime ownership stays native. */
export async function applyPreparedSvg(target: PreparedSvgOperation): Promise<{ count: number }> {
  const map = getAdminMapInstance(), session = getAppDraftSession(target.mapId)
  if (!map || map.id !== target.mapId || session.activeId !== target.draftId || !session.ready || !session.active
    || session.active.conflicted || session.offline || session.busy || session.transitioning) throw new Error("Keep the same ready online draft open to apply detected zones")
  const owner = captureMapSvgOwner(map), scope = captureRegionSyncOwner(map)
  const prepared = await target.prepare()
  if (prepared.draftId !== target.draftId || prepared.source !== owner.source || typeof prepared.svg !== "string") throw new Error("The proposal source changed")
  if (!prepared.alreadyApplied) await saveMapSvg(owner, prepared.svg, { preserveWorkspace: true })
  let current = getAdminMapInstance()
  for (let n = 0; n < 200 && (!current || (!prepared.alreadyApplied && current === map)); n++) {
    await new Promise(resolve => setTimeout(resolve, 50)); current = getAdminMapInstance()
  }
  if (!current || current.id !== target.mapId || session.activeId !== target.draftId) throw new Error("The active App/draft changed after SVG save")
  const next = captureRegionSyncOwner(current)
  if (next.pageId !== scope.pageId || next.stateId !== scope.stateId || next.binding !== scope.binding || next.prefix !== scope.prefix) throw new Error("The Page, Scene or Regions binding changed after detection")
  if (prepared.syncRegions !== false) {
    const sync = await previewRegionSync(next)
    if (sync.additions.length) await applyRegionSync(next, sync)
  }
  await target.complete(next.pageId, next.stateId)
  return { count: prepared.regionIds.length }
}
