import {
  createContext,
  useContext,
  type ReactNode,
} from "react"

type ShadowRootContextValue = {
  shadowRoot: ShadowRoot
  portalContainer: HTMLElement
}

const ShadowRootContext = createContext<ShadowRootContextValue | null>(null)

function getDomShadowRootContext(): ShadowRootContextValue | null {
  if (typeof document === "undefined") return null

  const host = document.getElementById("mapsvg-admin-react-root")
  const shadowRoot = host?.shadowRoot
  const portalContainer = shadowRoot?.querySelector<HTMLElement>(
    "#mapsvg-admin-react-portal",
  )

  if (!shadowRoot || !portalContainer) return null

  return { shadowRoot, portalContainer }
}

export function ShadowRootProvider({
  shadowRoot,
  portalContainer,
  children,
}: ShadowRootContextValue & { children: ReactNode }) {
  return (
    <ShadowRootContext.Provider value={{ shadowRoot, portalContainer }}>
      {children}
    </ShadowRootContext.Provider>
  )
}

export function useShadowRoot(): ShadowRootContextValue {
  const ctx = useContext(ShadowRootContext) ?? getDomShadowRootContext()
  if (!ctx) {
    throw new Error("useShadowRoot must be used within ShadowRootProvider")
  }
  return ctx
}

/** Portal target for Radix/shadcn overlays (Dialog, Select, etc.). */
export function usePortalContainer(): HTMLElement | undefined {
  return (
    useContext(ShadowRootContext)?.portalContainer ??
    getDomShadowRootContext()?.portalContainer
  )
}
