import { Component, Suspense, createElement, lazy, useState, type ComponentProps, type ComponentType, type ReactNode } from "react"
import { Button } from "@/components/ui/button"

export function AdminPanelLoading() {
  return <div role="status" className="flex min-h-0 flex-1 items-center justify-center p-6 text-sm text-muted-foreground">Loading…</div>
}

/** Keep a used dialog mounted without exposing pending/error UI after closing. */
export function DeferredDialogVisibility({ open, children }: { open: boolean; children: ReactNode }) {
  return <div hidden={!open} style={{ display: open ? "contents" : "none" }}>{children}</div>
}

class PanelErrorBoundary extends Component<{ children: ReactNode; onRetry: () => void }, { failed: boolean }> {
  state = { failed: false }
  static getDerivedStateFromError() { return { failed: true } }
  render() {
    if (this.state.failed) return <div role="alert" className="flex flex-col items-center justify-center gap-3 p-6 text-sm">
      <p>This panel could not load.</p>
      <Button type="button" size="sm" variant="outline" onClick={this.props.onRetry}>Try again</Button>
    </div>
    return this.props.children
  }
}

/** A real dynamic import in compiled ES builds, isolated from the retained shell. */
export function deferredAdminComponent<T extends ComponentType<any>>(load: () => Promise<{ default: T }>): ComponentType<ComponentProps<T>> {
  let CurrentComponent = lazy(load)
  return function DeferredAdminComponent(props: ComponentProps<T>) {
    const [{ Panel, attempt }, setAttempt] = useState(() => ({ Panel: CurrentComponent, attempt: 0 }))
    return <PanelErrorBoundary key={attempt} onRetry={() => {
      // A failed React.lazy caches its rejection. Retain the retry wrapper for
      // later route/dialog mounts too, rather than restoring the rejected one.
      CurrentComponent = lazy(load)
      setAttempt(({ attempt }) => ({ Panel: CurrentComponent, attempt: attempt + 1 }))
    }}>
      <Suspense fallback={<AdminPanelLoading />}>{createElement(Panel, props)}</Suspense>
    </PanelErrorBoundary>
  }
}
