import type {
  MapSVGExtensionHostApi,
  MapSVGPaidAddonMetadata,
} from "../../../mapsvg/Extensions/ExtensionHost"

declare global {
  interface Window {
    MapSVG?: {
      extensions?: MapSVGExtensionHostApi
      [key: string]: unknown
    }
  }
}

export function getSharedExtensionHost(): MapSVGExtensionHostApi {
  const host = window.MapSVG?.extensions
  if (!host) {
    throw new Error("[mapsvg-admin-react] Shared MapSVG extension host is not available")
  }
  return host
}

export function hasMapSVGCapability(id: string): boolean {
  return getSharedExtensionHost().hasCapability(id)
}

export function getActiveMapSVGAddon(): MapSVGPaidAddonMetadata | null {
  return getSharedExtensionHost().getActiveAddon()
}
