import { getAdminParams } from "./admin-params"
import { productFeatureAvailable, type MapProductFeature } from "../../../mapsvg/Core/productFeatures"
export function hasProductFeature(feature: MapProductFeature): boolean {
  return productFeatureAvailable(feature, getAdminParams().plan, window.MapSVG?.extensions)
}
export function productFeatureForNode(type: string): MapProductFeature | null {
  return ["directory", "mobileToolbar"].includes(type) ? "directory" : null
}
export function isProductNodeAvailable(type: string): boolean {
  const feature = productFeatureForNode(type)
  return !feature || hasProductFeature(feature)
}
