import type { ComponentType, ReactNode } from "react"
import type {ProjectChat,ProjectChatProvider} from "./project-chats"
import type { PremiumFeatureId } from "@/lib/premium-features"
import type { LucideIcon } from "lucide-react"
import { getSharedExtensionHost } from "@/lib/extensions"

export type AdminPanelProps = {
  selectedGalleryId?: string | null
  mapId?: number | null
  /** Core-owned manual creation actions, available in welcome and conversation. */
  startScreenActions?: ReactNode
  chatId?: number|null
  onChatSaved?: (chat:ProjectChat)=>void
}

export type AdminPanelDefinition = {
  id: string
  Panel: ComponentType<AdminPanelProps>
  projectChats?: ProjectChatProvider
}

export type AdminStyleDefinition = {
  id: string
  url: string
}

export type PremiumFallback = {
  feature?: PremiumFeatureId
  title?: string
  description: string
  disabledInputPlaceholder?: string
}

export type SettingsTabDefinition = {
  id: string
  label: string
  icon: LucideIcon
  order: number
  requiresCapability?: string
  premiumFallback?: PremiumFallback
  keepMounted?: boolean
}

export type ComponentNavLeafExtension = {
  id: string
  label: string
  groupId: string
  nestId?: string
  order?: number
}

type SettingsTabNavigationExtension = {
  surface: "settings-tab"
  tab: SettingsTabDefinition
}

type ComponentLeafNavigationExtension = {
  surface: "component-leaf"
  leaf: ComponentNavLeafExtension
}

export type AdminNavigationExtension =
  | SettingsTabNavigationExtension
  | ComponentLeafNavigationExtension

function navigationKey(extension: AdminNavigationExtension): string {
  if (extension.surface === "settings-tab") {
    return "settings-tab:" + extension.tab.id
  }
  const nest = extension.leaf.nestId ? ":" + extension.leaf.nestId : ""
  return "component-leaf:" + extension.leaf.groupId + nest + ":" + extension.leaf.id
}

export function registerAdminPanel(definition: AdminPanelDefinition): void {
  getSharedExtensionHost().register("admin.panel", definition.id, definition)
}

export function getAdminPanelDefinition(id: string): AdminPanelDefinition | undefined {
  const host = getSharedExtensionHost()
  host.seal("admin.panel")
  return host.get<AdminPanelDefinition>("admin.panel", id)
}

export function registerSettingsTab(tab: SettingsTabDefinition): void {
  getSharedExtensionHost().register(
    "admin.navigation",
    navigationKey({ surface: "settings-tab", tab }),
    { surface: "settings-tab", tab } satisfies SettingsTabNavigationExtension,
  )
}

export function registerComponentNavLeaf(leaf: ComponentNavLeafExtension): void {
  getSharedExtensionHost().register(
    "admin.navigation",
    navigationKey({ surface: "component-leaf", leaf }),
    { surface: "component-leaf", leaf } satisfies ComponentLeafNavigationExtension,
  )
}

function registeredNavigation(): AdminNavigationExtension[] {
  const host = getSharedExtensionHost()
  host.seal("admin.navigation")
  return host.list<AdminNavigationExtension>("admin.navigation").map((entry) => entry.value)
}

export function getRegisteredComponentNavLeaves(): ComponentNavLeafExtension[] {
  return registeredNavigation()
    .filter(
      (extension): extension is ComponentLeafNavigationExtension =>
        extension.surface === "component-leaf",
    )
    .map((extension) => extension.leaf)
    .sort(
      (left, right) =>
        (left.order ?? 1000) - (right.order ?? 1000) || left.id.localeCompare(right.id),
    )
}

export function getRegisteredAdminStyles(): AdminStyleDefinition[] {
  return getSharedExtensionHost()
    .list<AdminStyleDefinition>("admin.style")
    .map((entry) => entry.value)
    .filter((style) => typeof style.url === "string" && style.url !== "")
}

export function sealAdminExtensionRegistration(): void {
  const host = getSharedExtensionHost()
  for (const point of [
    "admin.navigation",
    "admin.panel",
    "admin.style",
    "admin.component",
    "admin.node",
    "admin.schema",
  ] as const) {
    host.seal(point)
  }
  host.sealCapabilities()
}

export function resolveSettingsTabs(
  coreTabs: readonly SettingsTabDefinition[],
): SettingsTabDefinition[] {
  const ids = new Set(coreTabs.map((tab) => tab.id))
  const paidTabs = registeredNavigation()
    .filter(
      (extension): extension is SettingsTabNavigationExtension =>
        extension.surface === "settings-tab",
    )
    .map((extension) => extension.tab)

  for (const tab of paidTabs) {
    if (ids.has(tab.id)) {
      throw new Error(
        '[MapSVG admin extensions] Paid settings tab "' +
          tab.id +
          '" collides with a Lite-owned tab. Register a panel for the Lite tab instead.',
      )
    }
    ids.add(tab.id)
  }

  return [...coreTabs, ...paidTabs].sort(
    (left, right) => left.order - right.order || left.id.localeCompare(right.id),
  )
}
