export type DataSchema = {
  id: string | number
  name: string
  title?: string
  type?: string
  objectNameSingular?: string
  objectNamePlural?: string
  postType?: string
  regionSupport?: boolean
  remote?: boolean
  fields?: SchemaField[]
  bindings?: { svg?: unknown; editor?: CollectionEditorDefaults; [key: string]: unknown }
  zodSettings?: ZodSettings | null
  [key: string]: unknown
}

type ApiListResponse<T> = {
  items?: T[]
  [key: string]: unknown
}

export class MapSvgApiError extends Error {
  readonly status: number
  readonly code?: string
  readonly issues?: unknown[]

  constructor(message: string, status: number, options?: { code?: string; issues?: unknown[] }) {
    super(message)
    this.name = "MapSvgApiError"
    this.status = status
    this.code = options?.code
    this.issues = options?.issues
  }
}

function apiErrorDetails(payload: unknown): {
  message?: string
  code?: string
  issues?: unknown[]
} {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) return {}
  const root = payload as Record<string, unknown>
  const nested =
    root.error && typeof root.error === "object" && !Array.isArray(root.error)
      ? (root.error as Record<string, unknown>)
      : null
  const data =
    root.data && typeof root.data === "object" && !Array.isArray(root.data)
      ? (root.data as Record<string, unknown>)
      : null

  const message =
    typeof root.error === "string"
      ? root.error
      : typeof nested?.message === "string"
        ? nested.message
        : typeof data?.error === "string"
          ? data.error
          : undefined
  const code =
    typeof root.code === "string"
      ? root.code
      : typeof nested?.code === "string"
        ? nested.code
        : undefined
  const issues = Array.isArray(root.issues)
    ? root.issues
    : Array.isArray(nested?.issues)
      ? nested.issues
      : undefined

  return { message, code, issues }
}

function apiBase(): { base: string; nonce: string } {
  const p = getAdminParams()
  return { base: p.apiUrl, nonce: p.nonce }
}

function apiUrl(base: string, path: string, query?: Record<string, string | number>): string {
  const url = resourceApiUrl(base, path.startsWith("/") ? path : `/${path}`)
  if (!query) return url
  const split = url.indexOf("?")
  const pathname = split < 0 ? url : url.slice(0, split)
  const parameters = new URLSearchParams(split < 0 ? "" : url.slice(split + 1))
  for (const [key, value] of Object.entries(query)) parameters.set(key, String(value))
  return pathname + (parameters.size ? "?" + parameters.toString() : "")
}

async function apiGet<T>(
  path: string,
  query?: Record<string, string | number>,
  signal?: AbortSignal,
): Promise<T> {
  const { base, nonce } = apiBase()
  const url = apiUrl(base, path, query)
  const res = await adminRestFetch(url, {
    headers: {
      Accept: "application/json",
      "X-WP-Nonce": nonce,
    },
    credentials: "same-origin",
    ...(signal ? { signal } : {}),
  })
  if (!res.ok) {
    throw new Error(`API ${res.status}: ${path}`)
  }
  return (await res.json()) as T
}

async function apiWrite<T>(
  method: "POST" | "PUT" | "DELETE" | "PATCH",
  path: string,
  body?: unknown,
  signal?: AbortSignal,
): Promise<T> {
  const { base, nonce } = apiBase()
  const res = await adminRestFetch(apiUrl(base, path), {
    method,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      "X-WP-Nonce": nonce,
    },
    credentials: "same-origin",
    body: body === undefined ? undefined : JSON.stringify(body),
    ...(signal ? { signal } : {}),
  })
  if (!res.ok) {
    const payload = await res.json().catch(() => null)
    const details = apiErrorDetails(payload)
    throw new MapSvgApiError(details.message || `API ${res.status}: ${path}`, res.status, {
      code: details.code,
      issues: details.issues,
    })
  }
  return (await res.json().catch(() => ({}))) as T
}

async function apiPost<T>(path: string, body: unknown, signal?: AbortSignal): Promise<T> {
  return apiWrite<T>("POST", path, body, signal)
}

async function apiPut<T>(path: string, body: unknown): Promise<T> {
  return apiWrite<T>("PUT", path, body)
}

export function isRegionSchema(schema: DataSchema): boolean {
  if (schema.bindings?.svg) return true
  if (schema.type === "region") return true
  return Boolean(schema.name && String(schema.name).startsWith("regions_"))
}

export function schemaDisplayTitle(schema: DataSchema): string {
  return schema.title?.trim() || schema.name || `Schema #${schema.id}`
}

export async function fetchSchemas(): Promise<DataSchema[]> {
  const data = await apiGet<ApiListResponse<DataSchema> | DataSchema[]>("/schemas", {
    perpage: 9999,
  })
  if (Array.isArray(data)) return data
  return Array.isArray(data.items) ? data.items : []
}

export type NewCollection = {
  type: "object" | "post"
  title: string
  objectNameSingular: string
  objectNamePlural: string
  postType?: string
  markerSupport?: boolean
  regionSupport?: boolean
}

export async function fetchWordPressPostTypes(signal?: AbortSignal): Promise<string[]> {
  const data = await apiGet<unknown>("/post-types", undefined, signal)
  if (!Array.isArray(data) || data.some((type) => typeof type !== "string" || !type)) {
    throw new Error("MapSVG returned an invalid post type catalog.")
  }
  return [...new Set(data as string[])].sort((a, b) => a.localeCompare(b))
}

export async function createCollection(input: NewCollection): Promise<DataSchema> {
  const schema = {
    type: input.type,
    title: input.title.trim(),
    objectNameSingular: input.objectNameSingular.trim(),
    objectNamePlural: input.objectNamePlural.trim(),
    ...(input.type === "post"
      ? {
          postType: input.postType,
          markerSupport: input.markerSupport ? 1 : 0,
          regionSupport: input.regionSupport ? 1 : 0,
        }
      : {}),
  }
  const result = await apiPost<{ schema?: DataSchema }>("/schemas", { schema })
  if (!result.schema?.id || !result.schema.name || result.schema.type !== input.type) {
    throw new Error("MapSVG returned an invalid created Collection.")
  }
  return result.schema
}

export type CollectionSettingsValue = Pick<NewCollection,
  "title" | "objectNameSingular" | "objectNamePlural" | "markerSupport" | "regionSupport">

/** Metadata-only update: the URL owns identity; fields, source and table name stay server-owned. */
export async function updateCollectionSettings(schema: DataSchema, settings: CollectionSettingsValue): Promise<void> {
  await apiPut(`/schemas/${encodeURIComponent(String(schema.id))}`, {
    schema: {
      title: settings.title.trim(),
      objectNameSingular: settings.objectNameSingular.trim(),
      objectNamePlural: settings.objectNamePlural.trim(),
      ...(schema.type === "post" ? {
        type: "post",
        markerSupport: settings.markerSupport ? 1 : 0,
        regionSupport: settings.regionSupport ? 1 : 0,
      } : {}),
    },
  })
}

export async function clearCollection(schema: DataSchema): Promise<void> {
  await apiWrite("DELETE", `/collection/${encodeURIComponent(schema.name)}`)
}

export async function deleteCollection(schema: DataSchema): Promise<void> {
  await apiWrite("DELETE", `/schemas/${encodeURIComponent(String(schema.id))}`)
}

export async function fetchMapDatabaseMeta(mapId: number): Promise<{
  objectsTableName: string | null
  regionsTableName: string | null
  objectsSchemaId: string | null
  regionsSchemaId: string | null
  connectedSchemaIds: string[]
}> {
  const data = await apiGet<Record<string, unknown>>(`/maps/${mapId}`)
  const mapData =
    data.map && typeof data.map === "object" ? (data.map as Record<string, unknown>) : data
  const options = (mapData.options ?? mapData) as Record<string, unknown>
  const database = (options.database ?? {}) as Record<string, unknown>
  const schemas = (database.schemas ?? {}) as Record<string, unknown>
  const objectsSchema = schemas.objects as { id?: string | number; name?: string } | undefined
  const regionsSchema = schemas.regions as { id?: string | number; name?: string } | undefined

  const connectedSchemaIds: string[] = []
  if (objectsSchema?.id != null) connectedSchemaIds.push(String(objectsSchema.id))
  if (regionsSchema?.id != null) connectedSchemaIds.push(String(regionsSchema.id))

  return {
    objectsSchemaId: objectsSchema?.id != null ? String(objectsSchema.id) : null,
    regionsSchemaId: regionsSchema?.id != null ? String(regionsSchema.id) : null,
    objectsTableName:
      typeof database.objectsTableName === "string"
        ? database.objectsTableName
        : (objectsSchema?.name ?? null),
    regionsTableName:
      typeof database.regionsTableName === "string"
        ? database.regionsTableName
        : (regionsSchema?.name ?? null),
    connectedSchemaIds,
  }
}

function schemaObjectNameSingular(schema: DataSchema): string {
  if (schema.objectNameSingular) return schema.objectNameSingular
  if (isRegionSchema(schema)) return "region"
  if (schema.type === "post") return "post"
  return "object"
}

// Match OperationSchemaCompiler's FILTER_VALIDATE_BOOLEAN policy for persisted flags.
function collectionFieldBoolean(value: unknown): boolean {
  return (
    value === true ||
    value === 1 ||
    (typeof value === "string" && ["1", "true", "on", "yes"].includes(value.trim().toLowerCase()))
  )
}

function writableCollectionRecord(
  schema: DataSchema,
  row: Record<string, unknown>,
  operation: "create" | "update",
): Record<string, unknown> {
  const writable = { ...row }
  for (const field of schema.fields ?? []) {
    // The public id remains the Update route selector, even when displayed readonly.
    if (operation === "update" && field.name === "id") continue
    const generated =
      field.type?.toLowerCase() === "id" &&
      (field.auto_increment == null || collectionFieldBoolean(field.auto_increment))
    if (collectionFieldBoolean(field.readonly) || (operation === "create" && generated)) {
      delete writable[field.name]
    }
  }
  return writable
}

export async function createCollectionRow(
  schema: DataSchema,
  row: Record<string, unknown>,
): Promise<Record<string, unknown>> {
  const singular = schemaObjectNameSingular(schema)
  const result = await apiPost<Record<string, unknown>>(
    `/collection/${encodeURIComponent(schema.name)}`,
    {
      [singular]: writableCollectionRecord(schema, row, "create"),
    },
  )
  const created = result[singular]
  if (!created || typeof created !== "object" || Array.isArray(created)) {
    throw new Error("MapSVG returned an invalid created row.")
  }
  return created as Record<string, unknown>
}

export async function fetchCollectionRow(
  schema: DataSchema,
  id: string | number,
  signal?: AbortSignal,
): Promise<Record<string, unknown>> {
  if (
    (typeof id !== "string" && typeof id !== "number") ||
    id === "" ||
    (typeof id === "number" && !Number.isFinite(id))
  ) {
    throw new Error("Cannot load a row without an id.")
  }
  const result = await apiGet<Record<string, unknown>>(
    `/collection/${encodeURIComponent(schema.name)}/${encodeURIComponent(String(id))}`,
    undefined,
    signal,
  )
  const record = result?.[schemaObjectNameSingular(schema)]
  if (
    !record ||
    typeof record !== "object" ||
    Array.isArray(record) ||
    !["string", "number"].includes(typeof (record as Record<string, unknown>).id) ||
    String((record as Record<string, unknown>).id) !== String(id)
  ) {
    throw new Error("MapSVG returned an invalid source row.")
  }
  return record as Record<string, unknown>
}

export async function updateCollectionRow(
  schema: DataSchema,
  row: Record<string, unknown>,
): Promise<void> {
  const id = row.id
  if (id == null || id === "") {
    throw new Error("Cannot update a row without an id.")
  }

  const singular = schemaObjectNameSingular(schema)
  await apiPut(`/collection/${encodeURIComponent(schema.name)}/${encodeURIComponent(String(id))}`, {
    [singular]: writableCollectionRecord(schema, row, "update"),
  })
}

export async function deleteCollectionRow(schema: DataSchema, id: string | number): Promise<void> {
  if ((typeof id !== "string" && typeof id !== "number") || id === "" || (typeof id === "number" && !Number.isFinite(id))) throw new Error("Cannot delete a row without an id.")
  await apiWrite("DELETE", `/collection/${encodeURIComponent(schema.name)}/${encodeURIComponent(String(id))}`)
}

export type CollectionCapabilities = {
  canCreate: boolean
  canEdit: boolean
  canDelete: boolean
  reason: string | null
}
export type CollectionPage = {
  items: Record<string, unknown>[]
  page: number
  perpage: number
  count: number | null
  hasMore: boolean
  capabilities: CollectionCapabilities
}

export async function fetchCollectionPage(
  schema: DataSchema,
  opts: { page: number; perpage: number; search: string },
  signal?: AbortSignal,
): Promise<CollectionPage> {
  const result = await apiGet<CollectionPage>(`/collection/${encodeURIComponent(schema.name)}`, {
    includeCollectionInfo: "true", page: opts.page, perpage: opts.perpage, search: opts.search,
  }, signal)
  const capabilities = result?.capabilities
  if (!Array.isArray(result?.items) || (result.count !== null && (!Number.isSafeInteger(result.count) || result.count < 0))
    || !Number.isInteger(result.page) || result.page < 1 || !Number.isInteger(result.perpage) || result.perpage < 1
    || typeof result.hasMore !== "boolean" || !capabilities
    || typeof capabilities.canCreate !== "boolean" || typeof capabilities.canEdit !== "boolean" || typeof capabilities.canDelete !== "boolean"
    || (capabilities.reason !== null && typeof capabilities.reason !== "string")) throw new Error("MapSVG returned an invalid Collection page.")
  return result
}

export async function updateSchemaFields(
  schema: DataSchema,
  fields: SchemaField[],
  zodSettings: ZodSettings | null | undefined = schema.zodSettings,
): Promise<void> {
  // Fields drafts do not own binding metadata and may predate a picker choice.
  const { bindings: _bindings, ...definition } = schema
  await apiPut(`/schemas/${encodeURIComponent(String(schema.id))}`, {
    schema: {
      ...definition,
      fields,
      ...(zodSettings !== undefined ? { zodSettings } : {}),
    },
  })
}

export async function fetchCollectionRows(
  schema: DataSchema,
  opts?: { perpage?: number; search?: string },
): Promise<Record<string, unknown>[]> {
  const kind = isRegionSchema(schema) ? "regions" : "objects"
  const query: Record<string, string | number> = {
    perpage: opts?.perpage ?? 50,
  }
  if (opts?.search) query.search = opts.search

  const data = await apiGet<ApiListResponse<Record<string, unknown>> | Record<string, unknown>[]>(
    `/${kind}/${schema.name}`,
    query,
  )

  if (Array.isArray(data)) return data
  return Array.isArray(data.items) ? data.items : []
}

export type MapDataQueryRequest = {
  where?: Record<string, unknown>
  select?: string[]
  orderBy?: Record<string, "asc" | "desc"> | Array<Record<string, "asc" | "desc">>
  take?: number
  skip?: number
}

export type MapDataQueryResult = {
  rows: Record<string, unknown>[]
  count: number
}

export async function executeMapDataQuery(
  mapId: number,
  sourceRole: "objects" | "regions",
  query: MapDataQueryRequest,
): Promise<MapDataQueryResult> {
  const result = await apiPost<MapDataQueryResult>(`/maps/${mapId}/data-query`, {
    sourceRole,
    query,
  })
  if (!Array.isArray(result.rows) || !Number.isSafeInteger(result.count) || result.count < 0) {
    throw new Error("MapSVG returned an invalid data-query response.")
  }
  return result
}

