/** Columns for List table — visible schema fields. */
export function listColumns(schema: DataSchema): SchemaField[] {
  const fields = schema.fields ?? []
  return fields.filter((f) => f.visible !== false)
}

export function formatCellValue(row: Record<string, unknown>, field: SchemaField): string {
  const raw = row[field.name]
  if (raw == null || raw === "") return ""
  if (field.type === "select" || field.type === "radio") {
    const values = Array.isArray(raw) ? raw : [raw]
    return values.map((value) => {
      const item = value && typeof value === "object" ? value as Record<string, unknown> : null
      const key = item ? item.value : value
      const label = item?.label ?? field.options?.find((option) => String(option.value) === String(key))?.label ?? key
      return label == null ? "" : typeof label === "object" ? JSON.stringify(label) : String(label)
    }).join(", ")
  }
  if (typeof raw === "boolean") return raw ? "true" : "false"
  if (typeof raw === "number" || typeof raw === "string") return String(raw)
  if (field.type === "post" && typeof raw === "object") {
    const post = raw as { post_title?: string; title?: string }
    return post.post_title || post.title || JSON.stringify(raw)
  }
  if (field.type === "location" && typeof raw === "object") {
    const loc = raw as { address?: { formatted?: string }; img?: string }
    return loc.address?.formatted || loc.img || "📍"
  }
  if ((field.type === "region" || field.type === "relation") && Array.isArray(raw)) {
    return raw
      .map((r) =>
        typeof r === "object" && r && "id" in r ? String((r as { id: unknown }).id) : String(r),
      )
      .join(", ")
  }
  if (Array.isArray(raw)) return raw.map(String).join(", ")
  try {
    return JSON.stringify(raw)
  } catch {
    return String(raw)
  }
}
