import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react"
import { Database, Map as MapIcon, MessageCircle, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { useWorkspaceStore, workspaceMapId, workspaceDatabaseSelection, type WorkspaceTab } from "@/lib/workspace-store"
import { cn } from "@/lib/utils"

type Props = {
  tabs: WorkspaceTab[]
  activeTabId: string | null
  onActivate: (id: string) => void
  onClose: (id: string) => void
}

type CardSize = {
  width: number
  height: number
}

const PREVIEW_OPEN_DELAY = 110
const PREVIEW_CLOSE_DELAY = 90

export function WorkspaceTabs({
  tabs,
  activeTabId,
  onActivate,
  onClose,
}: Props) {
  const mapDrafts = useWorkspaceStore((state) => state.mapDrafts)
  const rootRef = useRef<HTMLDivElement>(null)
  const tabRefs = useRef(new Map<string, HTMLDivElement>())
  const cardContentRef = useRef<HTMLDivElement>(null)
  const openTimerRef = useRef<number | null>(null)
  const closeTimerRef = useRef<number | null>(null)

  const [hoveredTabId, setHoveredTabId] = useState<string | null>(null)
  const [previewTabId, setPreviewTabId] = useState<string | null>(null)
  const [previewVisible, setPreviewVisible] = useState(false)
  const [anchorLeft, setAnchorLeft] = useState(8)
  const [rootWidth, setRootWidth] = useState(0)
  const [cardSize, setCardSize] = useState<CardSize>({
    width: 256,
    height: 68,
  })

  const activeTitle=tabs.find(tab=>tab.id===activeTabId)?.title
  useEffect(()=>{
    const reveal=()=>{if(activeTabId)tabRefs.current.get(activeTabId)?.scrollIntoView?.({block:"nearest",inline:"nearest"})}
    reveal()
    if(typeof ResizeObserver==="undefined" || !rootRef.current)return
    const observer=new ResizeObserver(reveal);observer.observe(rootRef.current)
    return()=>observer.disconnect()
  },[activeTabId,tabs.length,activeTitle])

  const previewTab =
    tabs.find((tab) => tab.id === previewTabId) ?? null

  const clearOpenTimer = () => {
    if (openTimerRef.current != null) {
      window.clearTimeout(openTimerRef.current)
      openTimerRef.current = null
    }
  }

  const clearCloseTimer = () => {
    if (closeTimerRef.current != null) {
      window.clearTimeout(closeTimerRef.current)
      closeTimerRef.current = null
    }
  }

  const updateAnchor = (tabId: string) => {
    const root = rootRef.current
    const tab = tabRefs.current.get(tabId)
    if (!root || !tab) return

    const rootRect = root.getBoundingClientRect()
    const tabRect = tab.getBoundingClientRect()
    setAnchorLeft(tabRect.left - rootRect.left)
    setRootWidth(rootRect.width)
  }

  const showPreview = (tabId: string) => {
    clearCloseTimer()
    clearOpenTimer()
    setHoveredTabId(tabId)
    setPreviewTabId(tabId)
    updateAnchor(tabId)

    if (previewVisible) return

    openTimerRef.current = window.setTimeout(() => {
      openTimerRef.current = null
      setPreviewVisible(true)
      updateAnchor(tabId)
    }, PREVIEW_OPEN_DELAY)
  }

  const scheduleHidePreview = () => {
    setHoveredTabId(null)
    clearOpenTimer()
    clearCloseTimer()
    closeTimerRef.current = window.setTimeout(() => {
      closeTimerRef.current = null
      setPreviewVisible(false)
    }, PREVIEW_CLOSE_DELAY)
  }

  useEffect(() => {
    return () => {
      clearOpenTimer()
      clearCloseTimer()
    }
  }, [])

  useLayoutEffect(() => {
    if (!previewTab || !cardContentRef.current) return

    const frame = window.requestAnimationFrame(() => {
      const rect = cardContentRef.current?.getBoundingClientRect()
      if (!rect) return
      setCardSize({
        width: Math.ceil(rect.width),
        height: Math.ceil(rect.height),
      })
      updateAnchor(previewTab.id)
    })

    return () => window.cancelAnimationFrame(frame)
  }, [previewTab])

  if (tabs.length === 0) return null

  const previewDraft =
    workspaceMapId(previewTab?.resource)
      ? mapDrafts[String(workspaceMapId(previewTab?.resource))]
      : undefined
  const PreviewIcon =
    workspaceMapId(previewTab?.resource) ? MapIcon : previewTab?.resource.kind === "chat" ? MessageCircle : Database
  const maxCardLeft =
    rootWidth > 0
      ? Math.max(8, rootWidth - cardSize.width - 8)
      : anchorLeft
  const cardLeft = Math.min(Math.max(anchorLeft, 8), maxCardLeft)

  return (
    <div
      ref={rootRef}
      data-slot="workspace-tabs"
      className="relative flex h-11 shrink-0 items-end bg-[#f3f3f3]"
    >
      <div
        className="relative z-10 flex min-w-0 flex-1 items-end gap-1 overflow-x-auto px-2 pt-1"
        role="tablist"
        aria-label="Open workspaces"
      >
        {tabs.map((tab, index) => {
          const active = tab.id === activeTabId
          const previousActive = tabs[index - 1]?.id === activeTabId
          const Icon = workspaceMapId(tab.resource) ? MapIcon : tab.resource.kind === "chat" ? MessageCircle : Database
          const draft =
            workspaceMapId(tab.resource)
              ? mapDrafts[String(workspaceMapId(tab.resource))]
              : undefined
          const previousTab = tabs[index - 1]
          const showDivider =
            index > 0 &&
            !active &&
            !previousActive &&
            hoveredTabId !== tab.id &&
            hoveredTabId !== previousTab?.id

          return (
            <div
              key={tab.id}
              ref={(node) => {
                if (node) tabRefs.current.set(tab.id, node)
                else tabRefs.current.delete(tab.id)
              }}
              className={cn(
                "group/tab relative flex h-[34px] w-[215px] min-w-0 shrink-0 items-center transition-colors duration-[120ms] ease-out",
                active
                  ? "z-20 rounded-t-[10px] bg-background text-foreground"
                  : "z-10 text-muted-foreground hover:text-foreground",
              )}
              onMouseEnter={() => showPreview(tab.id)}
              onMouseLeave={scheduleHidePreview}
            >
              {active ? (
                <>
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute -left-[10px] bottom-0 z-0 size-[10px] rounded-br-[8px] shadow-[5px_5px_0_5px_var(--background)]"
                  />
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute -right-[10px] bottom-0 z-0 size-[10px] rounded-bl-[8px] shadow-[-5px_5px_0_5px_var(--background)]"
                  />
                </>
              ) : (
                <span
                  aria-hidden="true"
                  className="pointer-events-none absolute inset-x-0 top-px bottom-[5px] rounded-[8px] bg-transparent transition-colors duration-[120ms] ease-out group-hover/tab:bg-foreground/[0.06]"
                />
              )}

              {showDivider ? (
                <span
                  aria-hidden="true"
                  className="pointer-events-none absolute -left-0.5 top-1/2 z-20 h-5 w-px -translate-y-1/2 bg-foreground/15 transition-opacity duration-100"
                />
              ) : null}

              <button
                type="button"
                role="tab"
                aria-selected={active}
                className="relative z-10 flex h-full min-w-0 flex-1 items-center gap-2 rounded-[inherit] px-3 text-sm outline-none"
                onClick={() => onActivate(tab.id)}
              >
                <Icon className="size-3.5 shrink-0" />
                <span className={cn("truncate", active && "font-medium")}>
                  {tab.title}
                </span>
                {draft?.conflicted ? (
                  <span
                    className="shrink-0 text-[10px] text-destructive"
                    aria-label="Draft conflict"
                  >
                    ●
                  </span>
                ) : null}
              </button>

              <Button
                type="button"
                variant="ghost"
                size="icon-xs"
                className={cn(
                  "relative z-10 mr-1 size-5 shrink-0 rounded-full hover:bg-foreground/10 hover:opacity-100",
                  active
                    ? "opacity-60"
                    : "opacity-0 group-hover/tab:opacity-70",
                )}
                aria-label={`Close ${tab.title}`}
                onClick={(event) => {
                  event.stopPropagation()
                  onClose(tab.id)
                }}
              >
                <X className="size-3.5" />
              </Button>
            </div>
          )
        })}
      </div>

      {previewTab ? (
        <div
          className={cn(
            "absolute left-0 top-full z-50 overflow-hidden rounded-xl bg-popover text-popover-foreground shadow-lg",
            "transition-[transform,width,height,opacity] duration-150 ease-out will-change-transform",
            previewVisible
              ? "pointer-events-auto opacity-100"
              : "pointer-events-none opacity-0",
          )}
          style={{
            width: cardSize.width,
            height: cardSize.height,
            transform: `translate3d(${cardLeft}px, 7px, 0)`,
          }}
          onMouseEnter={clearCloseTimer}
          onMouseLeave={scheduleHidePreview}
        >
          <div
            ref={cardContentRef}
            className="absolute left-0 top-0 w-max min-w-56 max-w-80 p-3"
          >
            <div className="flex min-w-0 items-center gap-2">
              <PreviewIcon className="size-4 shrink-0 text-muted-foreground" />
              <span className="max-w-64 truncate text-sm font-medium">
                {previewTab.title}
              </span>
            </div>
            <div className="mt-1 text-xs text-muted-foreground">
              {workspaceMapId(previewTab.resource)
                ? `Map · ID ${workspaceMapId(previewTab.resource)}`
                : workspaceDatabaseSelection(previewTab.resource)?.kind === "db-table" ? `Collection · ${previewTab.title}`
                : workspaceDatabaseSelection(previewTab.resource)?.kind === "db-query" ? `Query · ${previewTab.title}`
                : previewTab.resource.kind === "database" ? "Database" : "Conversation"}
            </div>
            {previewDraft?.conflicted ? (
              <div className="mt-2 text-xs text-destructive">
                Draft conflict
              </div>
            ) : null}
          </div>
        </div>
      ) : null}
    </div>
  )
}
