import { useEffect, useRef } from "react"

const guards = new Set<() => void>()

export function assertUpgradeReloadSafe() {
  for (const guard of guards) guard()
}

/** Files and active writes stay with their owning UI; an installed upgrade may wait to reload. */
export function useUpgradeReloadGuard(blocked: boolean, message: string) {
  const current = useRef({ blocked, message })
  current.current = { blocked, message }
  useEffect(() => {
    const guard = () => {
      if (current.current.blocked) throw new Error(current.current.message)
    }
    guards.add(guard)
    return () => {
      guards.delete(guard)
    }
  }, [])
}

export function useUpgradeReloadPreparation(prepare: () => void) {
  const current = useRef(prepare)
  current.current = prepare
  useEffect(() => {
    const guard = () => current.current()
    guards.add(guard)
    return () => {
      guards.delete(guard)
    }
  }, [])
}
