const LEGACY_CONTAINER_CLASSES = [
  "mapsvg-sidebar-left",
  "mapsvg-sidebar-right",
  "mapsvg-sidebar",
  "mapsvg-top-container",
  "mapsvg-header",
  "mapsvg-footer",
  "mapsvg-wrap",
] as const

/** Best-effort scan of the map's own CSS; theme and plugin CSS is outside this scope. */
export function findLegacyContainerCssClasses(css: unknown): string[] {
  if (typeof css !== "string") return []
  const withoutComments = css.replace(/\/\*[\s\S]*?\*\//g, "")
  return LEGACY_CONTAINER_CLASSES.filter((name) =>
    new RegExp(`(?:^|[^-\\w])${name}(?![-\\w])`).test(withoutComments),
  )
}
