import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

let current: MapsvgMapInstance | null = null
const listeners = new Set<(map: MapsvgMapInstance | null) => void>()

function notifyListeners(): void {
  for (const listener of listeners) {
    listener(current)
  }
}

/** Register the live MapPreview instance for AI options patches. */
export function registerAdminMapInstance(map: MapsvgMapInstance | null): void {
  current = map
  notifyListeners()
}

export function getAdminMapInstance(): MapsvgMapInstance | null {
  return current
}

/** Snapshot the selected map's live options before an AI turn starts. */
export function getAdminMapPreviewState(
  mapId: number | null,
): { mapId: number; options: Record<string, unknown> } | null {
  if (!current || current.id !== mapId || !isPlainObject(current.options)) return null
  try {
    const options = JSON.parse(JSON.stringify(current.options)) as unknown
    return isPlainObject(options) ? { mapId: current.id, options } : null
  } catch {
    return null
  }
}

/** Subscribe to MapPreview register/unregister (and get current immediately). */
export function subscribeAdminMapInstance(
  listener: (map: MapsvgMapInstance | null) => void,
): () => void {
  listeners.add(listener)
  listener(current)
  return () => {
    listeners.delete(listener)
  }
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v)
}

/**
 * Apply an options patch to the live map preview via MapSVG `update()`.
 * Returns false if no map is registered / update is unavailable.
 */
export function applyOptionsPatchToLiveMap(
  patch: Record<string, unknown>,
): boolean {
  if (!current || !isPlainObject(patch) || Object.keys(patch).length === 0) {
    return false
  }
  if (typeof current.update !== "function") return false

  try {
    const previousNodes = Object.keys(patch).length === 1 && patch.nodes ? current.options.nodes : undefined
    // Map.update invokes setters in key order. setLayout normalizes the registry
    // and remounts controllers, so it must see the final nodes/settings/pages.
    const { layout, ...settings } = patch
    const orderedPatch = "layout" in patch ? { ...settings, layout } : patch
    current.update(orderedPatch)
    if ((patch.nodes || patch.scenes) && !patch.layout) current.refreshTreeLayout?.(previousNodes)
    return true
  } catch (err) {
    console.error(
      "[mapsvg-admin-react] Failed to apply options patch to live map",
      err,
    )
    return false
  }
}
