import { useEffect, useReducer } from "react"
import { getAppDraftSession, type AppDraftSession } from "@/lib/app-drafts"

/** The shell observes draft state without loading the Versions UI. */
export function useAppDraftSession(mapId: number | null): AppDraftSession | null {
  const [, render] = useReducer(value => value + 1, 0)
  const session = mapId == null ? null : getAppDraftSession(mapId)
  useEffect(() => session?.subscribe(render), [session])
  return session
}
