import { getAdminParams } from "@/lib/admin-params"
import type { MapWorkspaceDraft } from "@/lib/workspace-store"

const STORE_NAME = "drafts"
const DB_VERSION = 1

type StoredDraft = {
  mapId: string
  draft: MapWorkspaceDraft
}

function databaseName(): string {
  const params = getAdminParams()
  return `mapsvg-admin-drafts-v1:${params.homeUrl}:${params.user.id}`
}

function openDatabase(): Promise<IDBDatabase | null> {
  if (typeof indexedDB === "undefined") return Promise.resolve(null)

  return new Promise((resolve, reject) => {
    const request = indexedDB.open(databaseName(), DB_VERSION)
    request.onupgradeneeded = () => {
      const database = request.result
      if (!database.objectStoreNames.contains(STORE_NAME)) {
        database.createObjectStore(STORE_NAME, { keyPath: "mapId" })
      }
    }
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error ?? new Error("Failed to open draft database"))
  })
}

export async function loadLocalMapDrafts(): Promise<
  Record<string, MapWorkspaceDraft>
> {
  const database = await openDatabase()
  if (!database) return {}

  try {
    return await new Promise((resolve, reject) => {
      const transaction = database.transaction(STORE_NAME, "readonly")
      const request = transaction.objectStore(STORE_NAME).getAll()
      request.onsuccess = () => {
        const drafts: Record<string, MapWorkspaceDraft> = {}
        for (const item of request.result as StoredDraft[]) {
          if (item?.mapId && item.draft) drafts[item.mapId] = item.draft
        }
        resolve(drafts)
      }
      request.onerror = () => reject(request.error ?? new Error("Failed to load map drafts"))
    })
  } finally {
    database.close()
  }
}
export async function saveLocalMapDraft(
  mapId: number,
  draft: MapWorkspaceDraft | null,
): Promise<void> {
  const database = await openDatabase()
  if (!database) return

  try {
    await new Promise<void>((resolve, reject) => {
      const transaction = database.transaction(STORE_NAME, "readwrite")
      const store = transaction.objectStore(STORE_NAME)
      if (draft) {
        store.put({ mapId: String(mapId), draft } satisfies StoredDraft)
      } else {
        store.delete(String(mapId))
      }
      transaction.oncomplete = () => resolve()
      transaction.onerror = () =>
        reject(transaction.error ?? new Error("Failed to persist map draft"))
      transaction.onabort = () =>
        reject(transaction.error ?? new Error("Draft persistence aborted"))
    })
  } finally {
    database.close()
  }
}
