/** Experimental editor states. Layout and component identity remain shared. */
export type StateChange = { path: string[]; value?: unknown; remove?: true }
export type AppState = {
  id: string
  title: string
  sceneId: string
  branchId: string
  parentId: string | null
  changes: StateChange[]
}
export type StateBranch = { id: string; name: string; sceneId: string }
export type StateGraph = {
  version: 1 | 2
  branches: StateBranch[]
  states: AppState[]
  defaultStateId: string | null
}
export type StateScene = { id: string; title: string }
type Options = Record<string, unknown>

export const ROOT_STATE = "root"
export const scenePointId = (id: string) => `scene:${id}`
export const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T
export const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b)
const object = (v: unknown): v is Options => v !== null && typeof v === "object" && !Array.isArray(v)
const safeKey = (key: string) => !["__proto__", "prototype", "constructor"].includes(key)
const entity = (id: string) => `@${id}`

export function stateScenes(options: Options): StateScene[] {
  const scenes = Array.isArray(options.scenes) ? options.scenes : []
  return scenes.filter((s): s is StateScene => object(s) && typeof s.id === "string" && typeof s.title === "string")
}

/** IDs address node/scene entities; array indexes never become persisted identities. */
export function diffSettings(before: unknown, after: unknown, path: string[] = []): StateChange[] {
  if (same(before, after)) return []
  // PHP legacy documents can encode an empty settings object as []. Diff its fields,
  // rather than treating all settings (including shared placement) as one override.
  if (path[0] === "nodes" && path.length === 3 && path[2] === "settings") {
    if (Array.isArray(before) && !before.length && object(after)) before = {}
    if (Array.isArray(after) && !after.length && object(before)) after = {}
  }
  if (["nodes", "scenes"].includes(path[0]) && path.length === 1 && Array.isArray(before) && Array.isArray(after)) {
    const changes: StateChange[] = []
    const previous = new Map(before.filter(object).map((item) => [String(item.id), item]))
    const next = new Map(after.filter(object).map((item) => [String(item.id), item]))
    for (const id of new Set([...previous.keys(), ...next.keys()])) {
      changes.push(...diffSettings(previous.get(id), next.get(id), [...path, entity(id)]))
    }
    return changes
  }
  if (object(before) && object(after)) {
    return [...new Set([...Object.keys(before), ...Object.keys(after)])]
      .filter(safeKey)
      .flatMap((key) => diffSettings(before[key], after[key], [...path, key]))
  }
  return [{ path, ...(after === undefined ? { remove: true as const } : { value: clone(after) }) }]
}

/** Only properties can vary; identities, membership, placement and layout cannot. */
export function isStateSetting(path: string[]): boolean {
  const [key, , property] = path
  if (!path.length || path.some((part) => !safeKey(part))) return false
  if (["stateGraph", "layout", "containers", "id", "title", "loadingText", "source", "svgData", "svgFileVersion", "useShadowRoot", "typography", "database", "db_map_id", "regionPrefix", "galleries"].includes(key)) return false
  if (key === "nodes") {
    return path.length > 2 && ["settings", "styles", "template", "css", "js"].includes(property)
      && !(property === "settings" && path.length < 4)
      && !(property === "settings" && ["placement", "chromeGrid", "responsiveLayout"].includes(path[3]))
  }
  if (key === "scenes") return path.length > 2 && ["theme", "dataBindings"].includes(property)
  return true
}

/** Apply on a cloned options document. Missing entities are not resurrected. */
export function applyChanges(options: Options, changes: StateChange[]): Options {
  const result = clone(options)
  for (const change of changes) {
    if (!change.path.length || change.path.some((part) => !safeKey(part))) throw new Error("Invalid state property path.")
    let target: unknown = result
    for (let i = 0; i < change.path.length; i++) {
      const key = change.path[i]
      const final = i === change.path.length - 1
      if (Array.isArray(target) && key.startsWith("@")) {
        const index = target.findIndex((item) => object(item) && String(item.id) === key.slice(1))
        if (final) {
          if (change.remove) { if (index >= 0) target.splice(index, 1) }
          else if (index >= 0) target[index] = clone(change.value)
          else target.push(clone(change.value))
        } else {
          if (index < 0) break
          target = target[index]
        }
      } else if (object(target)) {
        if (final) {
          if (change.remove) delete target[key]
          else target[key] = clone(change.value)
        } else {
          if (Array.isArray(target[key]) && !target[key].length && !change.path[i + 1].startsWith("@")) target[key] = {}
          if (!object(target[key]) && !Array.isArray(target[key])) target[key] = {}
          target = target[key]
        }
      } else break
    }
  }
  return result
}

export function emptyStateGraph(scenes: StateScene[]): StateGraph {
  return {
    version: 1,
    branches: scenes.map((scene) => ({ id: scenePointId(scene.id), name: scene.title, sceneId: scene.id })),
    states: [],
    defaultStateId: null,
  }
}

export function validateStateGraph(value: unknown, scenes: StateScene[]): StateGraph {
  if (!object(value) || (value.version !== 1 && value.version !== 2) || !Array.isArray(value.branches) || !Array.isArray(value.states)) throw new Error("Unsupported App Scenes document.")
  const graph = clone(value) as unknown as StateGraph
  const sceneIds = new Set(scenes.map((scene) => scene.id))
  const branches = new Map<string, StateBranch>()
  const ids = new Map<string, AppState>()
  for (const branch of graph.branches) {
    if (!branch || typeof branch.id !== "string" || !branch.id || typeof branch.name !== "string" || !branch.name.trim() || !sceneIds.has(branch.sceneId) || branches.has(branch.id)) throw new Error("Invalid App Scenes group.")
    branches.set(branch.id, branch)
  }
  for (const state of graph.states) {
    if (!state || typeof state.id !== "string" || !state.id || state.id === ROOT_STATE || state.id.startsWith("scene:") || ids.has(state.id) || typeof state.title !== "string" || !state.title.trim() || !Array.isArray(state.changes) || !sceneIds.has(state.sceneId) || branches.get(state.branchId)?.sceneId !== state.sceneId) throw new Error("Invalid App Scene.")
    for (const change of state.changes) {
      if (!change || !Array.isArray(change.path) || !change.path.every((part) => typeof part === "string") || !isStateSetting(change.path) || (change.remove !== true && !Object.prototype.hasOwnProperty.call(change, "value"))) throw new Error("Invalid App Scene override.")
      if (change.path[0] === "scenes" && change.path[1] !== entity(state.sceneId)) throw new Error("A Scene cannot override another Page.")
    }
    ids.set(state.id, state)
  }
  for (const state of graph.states) {
    if (graph.version === 2 && state.parentId !== null) throw new Error("Scenes inherit Page base, not another Scene.")
    const seen = new Set<string>()
    let cursor: AppState | undefined = state
    while (cursor) {
      if (seen.has(cursor.id)) throw new Error("App Scenes cannot contain cycles.")
      seen.add(cursor.id)
      if (cursor.parentId === null) break
      const parent: AppState | undefined = ids.get(cursor.parentId)
      if (!parent || parent.sceneId !== state.sceneId) throw new Error("Missing or incompatible Scene parent.")
      cursor = parent
    }
  }
  if (graph.defaultStateId !== null && !ids.has(graph.defaultStateId) && !(graph.version === 2 && scenes.some(scene => scenePointId(scene.id) === graph.defaultStateId))) throw new Error("Unknown default Scene.")
  return graph
}

export function stateChain(graph: StateGraph, id: string): AppState[] {
  const chain: AppState[] = []
  const visited = new Set<string>()
  const states = new Map(graph.states.map((state) => [state.id, state]))
  let cursor = states.get(id)
  while (cursor) {
    if (visited.has(cursor.id)) throw new Error("App Scenes cannot contain cycles.")
    visited.add(cursor.id)
    chain.unshift(cursor)
    cursor = cursor.parentId ? states.get(cursor.parentId) : undefined
  }
  return chain
}

export function resolveState(base: Options, graph: StateGraph, id: string): Options {
  return stateChain(graph, id).reduce((options, state) => applyChanges(options, state.changes), clone(base))
}

export function addAppState(graph: StateGraph, sceneId: string, parentId: string | null, mode: "continue" | "branch", title: string, branchName?: string): { graph: StateGraph; id: string } {
  const next = clone(graph)
  const parent = parentId ? next.states.find((state) => state.id === parentId) : undefined
  if (parentId && (!parent || parent.sceneId !== sceneId)) throw new Error("Invalid Scene parent.")
  if (graph.version === 2 && parentId !== null) throw new Error("Scenes inherit Page base, not another Scene.")
  if (mode === "branch" && parentId !== null) throw new Error("Create a new variant from the Page base.")
  const cleanTitle = title.trim()
  if (!cleanTitle) throw new Error("Enter a Scene title.")
  const id = `state-${crypto.randomUUID()}`
  let branchId = parent?.branchId ?? scenePointId(sceneId)
  if (mode === "branch") {
    const name = branchName?.trim()
    if (!name) throw new Error("Enter a branch name.")
    if (next.branches.some((branch) => branch.sceneId === sceneId && branch.name.toLowerCase() === name.toLowerCase())) throw new Error("That branch name is already used.")
    branchId = `branch-${crypto.randomUUID()}`
    next.branches.push({ id: branchId, name, sceneId })
  }
  // Continuing an earlier point inserts an empty increment before its existing continuation.
  // This is not arbitrary reparenting; the original lineage and effective settings are preserved.
  if (mode === "continue" && graph.version === 1) {
    const continuation = next.states.find((state) => state.parentId === parentId && state.sceneId === sceneId && state.branchId === branchId)
    if (continuation) continuation.parentId = id
  }
  next.states.push({ id, title: cleanTitle, sceneId, branchId, parentId, changes: [] })
  return { graph: next, id }
}

export function updateStateChanges(graph: StateGraph, id: string, changes: StateChange[]): StateGraph {
  const next = clone(graph)
  const state = next.states.find((item) => item.id === id)
  if (!state) throw new Error("Unknown Scene.")
  for (const change of changes) {
    if (!isStateSetting(change.path)) throw new Error("Structural settings belong to App.")
    const key = JSON.stringify(change.path)
    state.changes = state.changes.filter((previous) => JSON.stringify(previous.path) !== key)
    state.changes.push(clone(change))
  }
  return next
}

/** Preserve ordered overrides (including explicit values equal to base) when detaching v1 chains. */
export function independentStateGraph(graph: StateGraph, scenes: StateScene[]): StateGraph {
  if (graph.version === 2) return clone(graph)
  return {
    ...emptyStateGraph(scenes), version: 2, defaultStateId: graph.defaultStateId,
    states: graph.states.map(state => ({
      ...clone(state), parentId: null, branchId: scenePointId(state.sceneId),
      changes: clone(stateChain(graph, state.id).flatMap(parent => parent.changes)),
    })),
  }
}
