import type { DatabaseWorkspaceResource, WorkspaceResource } from "@/lib/workspace-store"

export const WORKSPACE_ROUTE_PARAM = "mapsvg_workspace"

export type WorkspaceSurfaceRoute = "start" | "settings" | "database-index"

export type WorkspaceRouteTarget =
  | { type: "surface"; surface: WorkspaceSurfaceRoute }
  | { type: "resource"; resource: WorkspaceResource }
  | { type: "database-browse"; resource: DatabaseWorkspaceResource }

export function parseWorkspaceRouteValue(value: string | null): WorkspaceRouteTarget {
  if (!value || value === "start") {
    return { type: "surface", surface: "start" }
  }
  if (value === "settings") {
    return { type: "surface", surface: "settings" }
  }
  if (value === "database") {
    return { type: "surface", surface: "database-index" }
  }
  if (value.startsWith("database-tab:")) {
    const match = /^database-tab:([a-zA-Z0-9-]{1,80})(?::(collection|query):(.+))?$/.exec(value)
    if (!match) return { type: "surface", surface: "start" }
    if (match[2] && !match[3].trim()) return { type: "surface", surface: "start" }
    const selection: DatabaseWorkspaceResource | null = match[2] === "collection"
      ? { kind: "db-table", schemaId: match[3], tableName: "" }
      : match[2] === "query" ? { kind: "db-query", queryId: match[3] } : null
    return { type: "resource", resource: { kind: "database", sessionId: match[1], selection } }
  }
  for (const [prefix, kind] of [["database:collection:", "db-table"], ["database:query:", "db-query"], ["db-query:", "db-query"]] as const) {
    if (value.startsWith(prefix)) {
      const id = value.slice(prefix.length).trim()
      if (!id) return { type: "surface", surface: "start" }
      const resource: DatabaseWorkspaceResource = kind === "db-query"
        ? { kind, queryId: id } : { kind, schemaId: id, tableName: "" }
      return prefix === "db-query:" ? { type: "resource", resource } : { type: "database-browse", resource }
    }
  }
  if (value.startsWith("map:")) {
    const mapId = Number(value.slice(4))
    if (Number.isInteger(mapId) && mapId > 0) {
      return { type: "resource", resource: { kind: "map", mapId } }
    }
  }
  if (value.startsWith("chat:")) {
    const key = value.slice(5),
      isNew = key.startsWith("new:"),
      sessionId = isNew ? key.slice(4) : key
    const chatId = isNew ? null : Number(key)
    if (
      /^[a-zA-Z0-9-]{1,80}$/.test(sessionId) &&
      (isNew || (Number.isSafeInteger(chatId) && chatId! > 0))
    )
      return { type: "resource", resource: { kind: "chat", sessionId, chatId, mapId: null } }
  }
  if (value.startsWith("db-table:")) {
    const schemaId = value.slice("db-table:".length).trim()
    if (schemaId) {
      return {
        type: "resource",
        resource: { kind: "db-table", schemaId, tableName: "" },
      }
    }
  }
  return { type: "surface", surface: "start" }
}

export function workspaceRouteValue(target: WorkspaceRouteTarget): string {
  if (target.type === "database-browse") return target.resource.kind === "db-query"
    ? `database:query:${target.resource.queryId}` : `database:collection:${target.resource.schemaId}`
  if (target.type === "surface") {
    if (target.surface === "start") return "start"
    if (target.surface === "settings") return "settings"
    return "database"
  }
  if (target.resource.kind === "map") {
    return `map:${target.resource.mapId}`
  }
  if (target.resource.kind === "chat")
    return `chat:${target.resource.chatId ?? "new:" + target.resource.sessionId}`
  if (target.resource.kind === "database") {
    const selection = target.resource.selection
    return `database-tab:${target.resource.sessionId}${selection?.kind === "db-table" ? `:collection:${selection.schemaId}` : selection?.kind === "db-query" ? `:query:${selection.queryId}` : ""}`
  }
  if (target.resource.kind === "db-query") return `db-query:${target.resource.queryId}`
  return `db-table:${target.resource.schemaId}`
}

export function readWorkspaceRoute(): WorkspaceRouteTarget | null {
  const url = new URL(window.location.href)
  const value = url.searchParams.get(WORKSPACE_ROUTE_PARAM)
  return value === null ? null : parseWorkspaceRouteValue(value)
}

export function writeWorkspaceRoute(
  target: WorkspaceRouteTarget,
  mode: "push" | "replace" = "push",
): void {
  const url = new URL(window.location.href)
  const value = workspaceRouteValue(target)
  url.searchParams.set(WORKSPACE_ROUTE_PARAM, value)

  const next = url.toString()
  if (next === window.location.href) return

  if (mode === "replace") {
    window.history.replaceState(window.history.state, "", next)
  } else {
    window.history.pushState(window.history.state, "", next)
  }
}
