import { getAdminParams } from "./admin-params"

const sessionMessage = "Your WordPress session could not be renewed. Sign in again, then retry. Your local drafts are retained."
export class AdminSessionError extends Error {}
let renewing: Promise<string> | null = null

function rememberNonce(nonce: string) {
  if (window.mapsvgReactAdminParams) window.mapsvgReactAdminParams.nonce = nonce
}

function currentUserUrl(): string {
  const url = new URL(getAdminParams().apiUrl, window.location.href)
  if (url.origin !== window.location.origin) throw new AdminSessionError(sessionMessage)
  if (url.searchParams.has("rest_route")) url.searchParams.set("rest_route", "/wp/v2/users/me")
  else url.pathname = url.pathname.replace(/\/mapsvg\/v1\/?$/, "/wp/v2/users/me")
  url.searchParams.set("_fields", "id")
  return url.href
}

async function renewNonce(): Promise<string> {
  if (renewing) return renewing
  const params = getAdminParams()
  const userId = params.user.id
  renewing = (async () => {
    const controller = new AbortController()
    const timer = window.setTimeout(() => controller.abort(), 10000)
    try {
      const url = new URL(params.ajaxUrl || "admin-ajax.php", window.location.href)
      if (url.origin !== window.location.origin || !userId) throw new AdminSessionError(sessionMessage)
      url.searchParams.set("action", "rest-nonce")
      const response = await fetch(url.href, { credentials: "same-origin", cache: "no-store", signal: controller.signal })
      const nonce = (await response.text()).trim()
      if (!response.ok || !/^[a-z0-9]{10}$/i.test(nonce)) throw new AdminSessionError(sessionMessage)
      // Never replay an old tab's write under a different signed-in WordPress account.
      const identity = await fetch(currentUserUrl(), {
        credentials: "same-origin", cache: "no-store", signal: controller.signal,
        headers: { "X-WP-Nonce": nonce },
      })
      const user = await identity.json()
      if (!identity.ok || user?.id !== userId || getAdminParams().user.id !== userId) throw new AdminSessionError(sessionMessage)
      rememberNonce(nonce)
      return nonce
    } catch { throw new AdminSessionError(sessionMessage) }
    finally { window.clearTimeout(timer) }
  })()
  try { return await renewing } finally { renewing = null }
}

/** Retry only WordPress's pre-dispatch nonce rejection, once, with the exact same body. */
export async function adminRestFetch(url: string, init: RequestInit = {}): Promise<Response> {
  let sentNonce = new Headers(init.headers).get("X-WP-Nonce")
  let response = await fetch(url, init)
  if (sentNonce && response.status === 403 && window.location && new URL(url, window.location.href).origin === window.location.origin) {
    const error = typeof response.clone === "function" ? await response.clone().json().catch(() => null) : null
    if (error?.code === "rest_cookie_invalid_nonce") {
      init.signal?.throwIfAborted()
      const current = getAdminParams().nonce
      const nonce = current && current !== sentNonce ? current : await renewNonce()
      init.signal?.throwIfAborted()
      const headers = new Headers(init.headers)
      headers.set("X-WP-Nonce", nonce)
      response = await fetch(url, { ...init, headers })
      sentNonce = nonce
      if (response.status === 403 && (await response.clone().json().catch(() => null))?.code === "rest_cookie_invalid_nonce") throw new AdminSessionError(sessionMessage)
    }
  }
  // WordPress rotates this header on authenticated success; ignore late replies from older requests.
  const refreshed = response.ok ? response.headers?.get("X-WP-Nonce") : null
  if (refreshed && getAdminParams().nonce === sentNonce) rememberNonce(refreshed)
  return response
}
