type Page = { id: string; rootNodeId?: string; bodyNodeId?: string }
type Node = { id: string; children?: string[] }
type Options = Record<string, unknown>

/** Single-page legacy documents own all nodes; multi-page ownership follows roots. */
export function pageNodeIds(options: Options, pageId: string): Set<string> {
  const pages = (Array.isArray(options.scenes) ? options.scenes : []) as Page[]
  const nodes = (Array.isArray(options.nodes) ? options.nodes : []) as Node[]
  const page = pages.find(item => item.id === pageId)
  if (!page) return new Set()
  if (pages.length === 1) return new Set(nodes.map(node => node.id))
  const byId = new Map(nodes.map(node => [node.id, node]))
  const pending = [page.rootNodeId, page.bodyNodeId].filter((id): id is string => !!id)
  const found = new Set<string>()
  while (pending.length) {
    const id = pending.pop()!
    if (found.has(id) || !byId.has(id)) continue
    found.add(id)
    pending.push(...(byId.get(id)?.children ?? []))
  }
  return found
}

/** Ambiguous/shared multi-page nodes cannot receive a page-local override. */
export function pageOwnsNode(options: Options, pageId: string, nodeId: string): boolean {
  if (!pageNodeIds(options, pageId).has(nodeId)) return false
  const pages = (Array.isArray(options.scenes) ? options.scenes : []) as Page[]
  return !pages.some(page => page.id !== pageId && pageNodeIds(options, page.id).has(nodeId))
}
